from __future__ import annotations

from collections.abc import Callable
from typing import Any, Literal

import networkx as nx

from . import optimization
from .receipt import EvaluationReceipt

Evaluator = Callable[[nx.Graph], EvaluationReceipt]


def _direct(
    key: str,
    method: str,
    function: Callable[[nx.Graph], Any],
    *,
    exactness: Literal["exact", "approximate"] = "exact",
) -> Evaluator:
    def wrapped(graph: nx.Graph) -> EvaluationReceipt:
        value = function(graph)
        return EvaluationReceipt(key, value, "verified", exactness, method)

    return wrapped


def _distance(key: str, function: Callable[[nx.Graph], int]) -> Evaluator:
    def wrapped(graph: nx.Graph) -> EvaluationReceipt:
        if not nx.is_connected(graph):
            return EvaluationReceipt(key, None, "undefined", "exact", f"networkx.{key}", message="Disconnected graph")
        return EvaluationReceipt(key, int(function(graph)), "verified", "exact", f"networkx.{key}")

    return wrapped


EVALUATORS: dict[str, Evaluator] = {
    "n": _direct("n", "networkx.number_of_nodes", nx.number_of_nodes),
    "m": _direct("m", "networkx.number_of_edges", nx.number_of_edges),
    "minimum_degree": _direct(
        "minimum_degree", "degree_scan", lambda graph: min(dict(graph.degree()).values(), default=0)
    ),
    "maximum_degree": _direct(
        "maximum_degree", "degree_scan", lambda graph: max(dict(graph.degree()).values(), default=0)
    ),
    "average_degree": _direct(
        "average_degree",
        "handshake_identity",
        lambda graph: 0.0 if not graph else 2.0 * graph.number_of_edges() / graph.number_of_nodes(),
        exactness="approximate",
    ),
    "component_count": _direct(
        "component_count", "networkx.number_connected_components", nx.number_connected_components
    ),
    "is_connected": _direct(
        "is_connected", "networkx.is_connected", lambda graph: bool(graph) and nx.is_connected(graph)
    ),
    "is_tree": _direct("is_tree", "networkx.is_tree", nx.is_tree),
    "is_bipartite": _direct("is_bipartite", "networkx.is_bipartite", nx.is_bipartite),
    "is_regular": _direct("is_regular", "degree_scan", lambda graph: len(set(dict(graph.degree()).values())) <= 1),
    "is_complete": _direct(
        "is_complete",
        "edge_count_identity",
        lambda graph: graph.number_of_edges() == graph.number_of_nodes() * (graph.number_of_nodes() - 1) // 2,
    ),
    "is_cubic": _direct(
        "is_cubic", "degree_scan", lambda graph: bool(graph) and all(degree == 3 for _, degree in graph.degree())
    ),
    "is_subcubic": _direct(
        "is_subcubic", "degree_scan", lambda graph: all(degree <= 3 for _, degree in graph.degree())
    ),
    "bridge_count": _direct("bridge_count", "networkx.bridges", lambda graph: sum(1 for _ in nx.bridges(graph))),
    "has_bridge": _direct(
        "has_bridge", "networkx.has_bridges", lambda graph: bool(graph.number_of_edges()) and nx.has_bridges(graph)
    ),
    "cutvertex_count": _direct(
        "cutvertex_count", "networkx.articulation_points", lambda graph: sum(1 for _ in nx.articulation_points(graph))
    ),
    "has_cutvertex": _direct(
        "has_cutvertex",
        "networkx.articulation_points",
        lambda graph: next(iter(nx.articulation_points(graph)), None) is not None,
    ),
    "triangle_count": _direct(
        "triangle_count", "networkx.triangles/3", lambda graph: sum(nx.triangles(graph).values()) // 3
    ),
    "is_triangle_free": _direct(
        "is_triangle_free", "networkx.triangles", lambda graph: not any(nx.triangles(graph).values())
    ),
    "isolated_vertex_count": _direct(
        "isolated_vertex_count", "networkx.isolates", lambda graph: sum(1 for _ in nx.isolates(graph))
    ),
    "has_isolated_vertex": _direct(
        "has_isolated_vertex", "networkx.isolates", lambda graph: next(iter(nx.isolates(graph)), None) is not None
    ),
    "n1_degree_count": _direct(
        "n1_degree_count", "degree_scan", lambda graph: sum(degree == 1 for _, degree in graph.degree())
    ),
    "has_leaf": _direct("has_leaf", "degree_scan", lambda graph: any(degree == 1 for _, degree in graph.degree())),
    "density": _direct("density", "networkx.density", nx.density, exactness="approximate"),
    "cycle_rank": _direct(
        "cycle_rank",
        "cycle_space_dimension",
        lambda graph: graph.number_of_edges() - graph.number_of_nodes() + nx.number_connected_components(graph),
    ),
    "radius": _distance("radius", nx.radius),
    "diameter": _distance("diameter", nx.diameter),
    "matching_number": optimization.matching_number,
    "independence_number": optimization.independence_number,
    "vertex_cover_number": optimization.vertex_cover_number,
    "clique_number": optimization.clique_number,
    "domination_number": optimization.domination_number,
}


def available_evaluators() -> tuple[str, ...]:
    from .full_provider import available_descriptor_keys

    return available_descriptor_keys()


def evaluate(descriptor_key: str, graph: nx.Graph) -> EvaluationReceipt:
    try:
        evaluator = EVALUATORS[descriptor_key]
    except KeyError:
        from .full_provider import evaluate_extracted

        return evaluate_extracted(descriptor_key, graph)
    else:
        return evaluator(graph)

from __future__ import annotations

from dataclasses import dataclass
from itertools import product

import networkx as nx
import numpy as np
from scipy.optimize import Bounds, LinearConstraint, milp


@dataclass(frozen=True)
class AllianceBundle:
    defensive_alliance_number: int
    offensive_alliance_number: int
    powerful_alliance_number: int
    global_defensive_alliance_number: int
    global_offensive_alliance_number: int
    global_powerful_alliance_number: int
    defensive_alliance_partition_number: int


def _star_leaf_count(graph: nx.Graph) -> int | None:
    order = graph.number_of_nodes()
    if order < 3 or graph.number_of_edges() != order - 1 or not nx.is_connected(graph):
        return None
    degrees = sorted(dict(graph.degree()).values())
    return order - 1 if degrees == [1] * (order - 1) + [order - 1] else None


def _solve(c, integrality, lower, upper, rows, row_lower, row_upper):
    result = milp(
        np.asarray(c, dtype=float),
        integrality=np.asarray(integrality, dtype=int),
        bounds=Bounds(np.asarray(lower, dtype=float), np.asarray(upper, dtype=float)),
        constraints=LinearConstraint(
            np.asarray(rows, dtype=float),
            np.asarray(row_lower, dtype=float),
            np.asarray(row_upper, dtype=float),
        ),
        options={"presolve": True},
    )
    if not result.success:
        raise RuntimeError("Alliance MILP did not solve")
    return result


def _append(rows, lower, upper, row, low, high) -> None:
    rows.append(row)
    lower.append(low)
    upper.append(high)


def _indexed_neighbors(graph: nx.Graph) -> list[list[int]]:
    nodes = list(graph)
    index = {node: i for i, node in enumerate(nodes)}
    return [[index[u] for u in graph[node]] for node in nodes]


def _minimum_alliance(
    graph: nx.Graph,
    *,
    defensive: bool,
    offensive: bool,
    global_alliance: bool,
) -> int:
    neighbors = _indexed_neighbors(graph)
    order = len(neighbors)
    has_boundary = offensive and not global_alliance
    variable_count = 2 * order if has_boundary else order
    rows, row_lower, row_upper = [], [], []

    row = [0] * variable_count
    for vertex in range(order):
        row[vertex] = 1
    _append(rows, row_lower, row_upper, row, 1, np.inf)

    if global_alliance:
        for vertex in range(order):
            row = [0] * variable_count
            row[vertex] = 1
            for neighbor in neighbors[vertex]:
                row[neighbor] = 1
            _append(rows, row_lower, row_upper, row, 1, np.inf)

    if defensive:
        for vertex in range(order):
            row = [0] * variable_count
            row[vertex] = -(len(neighbors[vertex]) - 1)
            for neighbor in neighbors[vertex]:
                row[neighbor] += 2
            _append(rows, row_lower, row_upper, row, 0, np.inf)

    if offensive and global_alliance:
        for vertex in range(order):
            degree = len(neighbors[vertex])
            row = [0] * variable_count
            row[vertex] = degree + 1
            for neighbor in neighbors[vertex]:
                row[neighbor] += 2
            _append(rows, row_lower, row_upper, row, degree + 1, np.inf)

    if has_boundary:
        for vertex in range(order):
            degree = len(neighbors[vertex])
            boundary = order + vertex

            row = [0] * variable_count
            row[boundary] = row[vertex] = 1
            _append(rows, row_lower, row_upper, row, -np.inf, 1)

            row = [0] * variable_count
            row[boundary] = 1
            for neighbor in neighbors[vertex]:
                row[neighbor] -= 1
            _append(rows, row_lower, row_upper, row, -np.inf, 0)

            row = [0] * variable_count
            row[boundary] = degree
            row[vertex] = degree
            for neighbor in neighbors[vertex]:
                row[neighbor] -= 1
            _append(rows, row_lower, row_upper, row, 0, np.inf)

            row = [0] * variable_count
            row[boundary] = -(degree + 1)
            for neighbor in neighbors[vertex]:
                row[neighbor] += 2
            _append(rows, row_lower, row_upper, row, 0, np.inf)

    result = _solve(
        [1] * order + [0] * (variable_count - order),
        [1] * variable_count,
        [0] * variable_count,
        [1] * variable_count,
        rows,
        row_lower,
        row_upper,
    )
    return round(float(result.fun))


def defensive_alliance_number(graph: nx.Graph) -> int:
    return _minimum_alliance(graph, defensive=True, offensive=False, global_alliance=False)


def offensive_alliance_number(graph: nx.Graph) -> int:
    return _minimum_alliance(graph, defensive=False, offensive=True, global_alliance=False)


def powerful_alliance_number(graph: nx.Graph) -> int:
    return _minimum_alliance(graph, defensive=True, offensive=True, global_alliance=False)


def global_defensive_alliance_number(graph: nx.Graph) -> int:
    return _minimum_alliance(graph, defensive=True, offensive=False, global_alliance=True)


def global_offensive_alliance_number(graph: nx.Graph) -> int:
    return _minimum_alliance(graph, defensive=False, offensive=True, global_alliance=True)


def global_powerful_alliance_number(graph: nx.Graph) -> int:
    return _minimum_alliance(graph, defensive=True, offensive=True, global_alliance=True)


def _defensive_partition_at_least(graph: nx.Graph, classes: int) -> bool:
    neighbors = _indexed_neighbors(graph)
    order = len(neighbors)
    variable_count = order * classes
    rows, row_lower, row_upper = [], [], []

    def x(vertex: int, color: int) -> int:
        return color * order + vertex

    for vertex in range(order):
        row = [0] * variable_count
        for color in range(classes):
            row[x(vertex, color)] = 1
        _append(rows, row_lower, row_upper, row, 1, 1)
    for color in range(classes):
        row = [0] * variable_count
        for vertex in range(order):
            row[x(vertex, color)] = 1
        _append(rows, row_lower, row_upper, row, 1, np.inf)
        for vertex in range(order):
            row = [0] * variable_count
            row[x(vertex, color)] = -(len(neighbors[vertex]) - 1)
            for neighbor in neighbors[vertex]:
                row[x(neighbor, color)] += 2
            _append(rows, row_lower, row_upper, row, 0, np.inf)
    result = milp(
        np.zeros(variable_count),
        integrality=np.ones(variable_count),
        bounds=Bounds(np.zeros(variable_count), np.ones(variable_count)),
        constraints=LinearConstraint(
            np.asarray(rows, dtype=float),
            np.asarray(row_lower, dtype=float),
            np.asarray(row_upper, dtype=float),
        ),
        options={"presolve": True},
    )
    return bool(result.success)


def defensive_alliance_partition_number(
    graph: nx.Graph,
    defensive_number: int | None = None,
) -> int:
    leaf_count = _star_leaf_count(nx.Graph(graph))
    if leaf_count is not None:
        # The center's class needs at least ceil((r - 1) / 2) leaves. Every
        # remaining leaf can form its own defensive-alliance class.
        return (leaf_count + 1) // 2 + 1
    minimum = defensive_number or defensive_alliance_number(graph)
    for classes in range(len(graph) // minimum, 0, -1):
        if _defensive_partition_at_least(graph, classes):
            return classes
    raise RuntimeError("Every nonempty graph has a defensive-alliance partition")


def alliance_bundle(graph: nx.Graph) -> AllianceBundle:
    defensive = defensive_alliance_number(graph)
    return AllianceBundle(
        defensive,
        offensive_alliance_number(graph),
        powerful_alliance_number(graph),
        global_defensive_alliance_number(graph),
        global_offensive_alliance_number(graph),
        global_powerful_alliance_number(graph),
        defensive_alliance_partition_number(graph, defensive),
    )


def _properties(graph: nx.Graph, selected: set) -> tuple[bool, bool, bool]:
    outside = set(graph) - selected
    defensive = all(
        len((set(graph[vertex]) | {vertex}) & selected)
        >= len(set(graph[vertex]) & outside)
        for vertex in selected
    )
    boundary = {vertex for vertex in outside if set(graph[vertex]) & selected}
    offensive = all(
        len(set(graph[vertex]) & selected)
        >= len((set(graph[vertex]) | {vertex}) & outside)
        for vertex in boundary
    )
    dominating = all(set(graph[vertex]) & selected for vertex in outside)
    return defensive, offensive, dominating


def alliance_bundle_bruteforce(graph: nx.Graph) -> AllianceBundle:
    nodes = list(graph)
    properties = {}
    for mask in range(1, 1 << len(nodes)):
        selected = {nodes[i] for i in range(len(nodes)) if mask & (1 << i)}
        properties[mask] = _properties(graph, selected)

    minima = []
    for requirement in (
        lambda d, o, g: d,
        lambda d, o, g: o,
        lambda d, o, g: d and o,
        lambda d, o, g: d and g,
        lambda d, o, g: o and g,
        lambda d, o, g: d and o and g,
    ):
        minima.append(min(
            mask.bit_count()
            for mask, values in properties.items()
            if requirement(*values)
        ))

    partition = 1
    for classes in range(2, len(nodes) + 1):
        if any(
            set(assignment) == set(range(classes))
            and all(
                properties[sum(
                    1 << vertex
                    for vertex, color_value in enumerate(assignment)
                    if color_value == color
                )][0]
                for color in range(classes)
            )
            for assignment in product(range(classes), repeat=len(nodes))
        ):
            partition = classes
    return AllianceBundle(*minima, partition)

from __future__ import annotations

from dataclasses import dataclass
from functools import lru_cache
from itertools import combinations
from typing import Any

import networkx as nx
import numpy as np
import pulp
from pysat.card import CardEnc, EncType
from pysat.formula import CNF, IDPool
from pysat.solvers import Solver
from scipy.optimize import Bounds, LinearConstraint, milp
from scipy.sparse import lil_matrix

EXACT_COLORING_TIME_LIMIT_SECONDS = 120.0


class ExactColoringStateLimitExceeded(RuntimeError):
    pass


@dataclass(frozen=True)
class ColoringPartitionBundle:
    grundy_number: int
    partial_grundy_number: int
    achromatic_number: int
    pseudo_achromatic_number: int
    b_chromatic_number: int
    fall_chromatic_number: int | None
    fall_achromatic_number: int | None

    @property
    def has_fall_coloring(self) -> bool:
        return self.fall_chromatic_number is not None


def _complete_bipartition(graph: nx.Graph) -> tuple[set[Any], set[Any]] | None:
    if not graph or not nx.is_connected(graph) or not nx.is_bipartite(graph):
        return None
    coloring = nx.bipartite.color(graph)
    left = {vertex for vertex, color in coloring.items() if color == 0}
    right = set(graph) - left
    if graph.number_of_edges() != len(left) * len(right):
        return None
    return left, right


def _is_complete(graph: nx.Graph) -> bool:
    return graph.number_of_edges() == len(graph) * (len(graph) - 1) // 2


def _fixed_coloring_milp(  # noqa: C901 - shared variables belong in one model
    graph: nx.Graph,
    color_count: int,
    property_name: str,
) -> tuple[int, ...] | None:
    nodes = list(graph)
    order = len(nodes)
    node_index = {node: position for position, node in enumerate(nodes)}
    edges = [(node_index[u], node_index[v]) for u, v in graph.edges()]
    neighbors = [set() for _ in range(order)]
    for u, v in edges:
        neighbors[u].add(v)
        neighbors[v].add(u)
    complete = property_name in {"achromatic", "pseudo_achromatic"}
    tight_complete = complete and graph.number_of_edges() == color_count * (
        color_count - 1
    ) // 2
    proper = tight_complete or property_name in {
        "grundy",
        "partial_grundy",
        "achromatic",
        "b_chromatic",
        "fall",
    }
    has_markers = property_name in {"partial_grundy", "b_chromatic"}
    x_count = order * color_count
    z_offset = x_count
    z_count = order * color_count if has_markers else 0
    pairs = list(combinations(range(color_count), 2)) if complete else []
    y_offset = z_offset + z_count
    y_count = len(edges) * len(pairs) * 2
    variable_count = y_offset + y_count
    rows: list[dict[int, float]] = []
    row_lower: list[float] = []
    row_upper: list[float] = []

    def add(coefficients: dict[int, float], lower: float, upper: float) -> None:
        rows.append(coefficients)
        row_lower.append(lower)
        row_upper.append(upper)

    def x(vertex: int, color: int) -> int:
        return vertex * color_count + color

    def z(vertex: int, color: int) -> int:
        return z_offset + vertex * color_count + color

    def y(edge: int, pair: int, orientation: int) -> int:
        return y_offset + (edge * len(pairs) + pair) * 2 + orientation

    for vertex in range(order):
        add({x(vertex, color): 1.0 for color in range(color_count)}, 1.0, 1.0)
    for color in range(color_count):
        add({x(vertex, color): 1.0 for vertex in range(order)}, 1.0, np.inf)
    if property_name in {"achromatic", "pseudo_achromatic", "b_chromatic", "fall"}:
        add({x(0, 0): 1.0}, 1.0, 1.0)
        # These properties are invariant under color permutations.  Requiring
        # colors to appear in first-use order removes k! equivalent solutions.
        for vertex in range(1, order):
            for color in range(1, color_count):
                coefficients = {x(vertex, color): 1.0}
                coefficients.update(
                    {
                        x(earlier_vertex, color - 1): -1.0
                        for earlier_vertex in range(vertex)
                    }
                )
                add(coefficients, -np.inf, 0.0)
    if proper:
        for u, v in edges:
            for color in range(color_count):
                add({x(u, color): 1.0, x(v, color): 1.0}, -np.inf, 1.0)
    if complete:
        degrees = [len(neighbors[vertex]) for vertex in range(order)]
        for color in range(color_count):
            add(
                {
                    x(vertex, color): float(degrees[vertex])
                    for vertex in range(order)
                },
                color_count - 1,
                np.inf,
            )
    if tight_complete:
        for color in range(color_count):
            add(
                {
                    x(vertex, color): float(degrees[vertex])
                    for vertex in range(order)
                },
                color_count - 1,
                color_count - 1,
            )
        for vertex in range(order):
            degree = degrees[vertex]
            for own_color in range(color_count):
                for neighbor_color in range(color_count):
                    if own_color == neighbor_color:
                        continue
                    coefficients = {
                        x(vertex, own_color): float(degree),
                    }
                    coefficients.update(
                        {
                            x(neighbor, neighbor_color): 1.0
                            for neighbor in neighbors[vertex]
                        }
                    )
                    add(coefficients, -np.inf, degree + 1)
    if property_name == "grundy":
        for vertex in range(order):
            for color in range(1, color_count):
                for earlier in range(color):
                    coefficients = {x(vertex, color): 1.0}
                    coefficients.update(
                        {x(neighbor, earlier): -1.0 for neighbor in neighbors[vertex]}
                    )
                    add(coefficients, -np.inf, 0.0)
    if has_markers:
        for vertex in range(order):
            for color in range(color_count):
                add({z(vertex, color): 1.0, x(vertex, color): -1.0}, -np.inf, 0.0)
                required_colors = (
                    range(color)
                    if property_name == "partial_grundy"
                    else (other for other in range(color_count) if other != color)
                )
                for required in required_colors:
                    coefficients = {z(vertex, color): 1.0}
                    coefficients.update(
                        {
                            x(neighbor, required): -1.0
                            for neighbor in neighbors[vertex]
                        }
                    )
                    add(coefficients, -np.inf, 0.0)
        for color in range(color_count):
            add({z(vertex, color): 1.0 for vertex in range(order)}, 1.0, np.inf)
    if property_name == "fall":
        for vertex in range(order):
            for color in range(color_count):
                for other in range(color_count):
                    if color == other:
                        continue
                    coefficients = {x(vertex, color): 1.0}
                    coefficients.update(
                        {x(neighbor, other): -1.0 for neighbor in neighbors[vertex]}
                    )
                    add(coefficients, -np.inf, 0.0)
    if complete:
        for edge_index, (u, v) in enumerate(edges):
            for pair_index, (first, second) in enumerate(pairs):
                for orientation, (left, right) in enumerate(
                    ((first, second), (second, first))
                ):
                    variable = y(edge_index, pair_index, orientation)
                    add({variable: 1.0, x(u, left): -1.0}, -np.inf, 0.0)
                    add({variable: 1.0, x(v, right): -1.0}, -np.inf, 0.0)
                    add(
                        {
                            variable: 1.0,
                            x(u, left): -1.0,
                            x(v, right): -1.0,
                        },
                        -1.0,
                        np.inf,
                    )
        for pair_index in range(len(pairs)):
            add(
                {
                    y(edge, pair_index, orientation): 1.0
                    for edge in range(len(edges))
                    for orientation in range(2)
                },
                1.0,
                np.inf,
            )
    matrix = lil_matrix((len(rows), variable_count), dtype=float)
    for row_index, coefficients in enumerate(rows):
        for variable, coefficient in coefficients.items():
            matrix[row_index, variable] = coefficient
    integrality = np.zeros(variable_count, dtype=int)
    integrality[:x_count] = 1
    integrality[z_offset : z_offset + z_count] = 1
    result = milp(
        c=np.zeros(variable_count),
        integrality=integrality,
        bounds=Bounds(np.zeros(variable_count), np.ones(variable_count)),
        constraints=LinearConstraint(
            matrix.tocsr(), np.asarray(row_lower), np.asarray(row_upper)
        ),
        options={"time_limit": EXACT_COLORING_TIME_LIMIT_SECONDS, "mip_rel_gap": 0.0},
    )
    if result.status == 2:
        return None
    if not result.success or result.x is None:
        raise ExactColoringStateLimitExceeded(
            f"MILP did not certify {property_name} with {color_count} colors: "
            f"status={result.status}, message={result.message}"
        )
    return tuple(
        max(range(color_count), key=lambda color: result.x[x(vertex, color)])
        for vertex in range(order)
    )


def _fixed_complete_coloring_cbc(
    graph: nx.Graph,
    color_count: int,
    *,
    proper: bool,
) -> tuple[int, ...] | None:
    nodes = list(graph)
    order = len(nodes)
    index = {node: position for position, node in enumerate(nodes)}
    edges = [(index[u], index[v]) for u, v in graph.edges()]
    pairs = list(combinations(range(color_count), 2))
    tight = len(edges) == len(pairs)
    proper = proper or tight
    problem = pulp.LpProblem("complete_coloring", pulp.LpMinimize)
    x = {
        (vertex, color): pulp.LpVariable(
            f"x_{vertex}_{color}", cat=pulp.LpBinary
        )
        for vertex in range(order)
        for color in range(color_count)
    }
    y = {
        (edge, pair, orientation): pulp.LpVariable(
            f"y_{edge}_{pair}_{orientation}", cat=pulp.LpBinary
        )
        for edge in range(len(edges))
        for pair in range(len(pairs))
        for orientation in range(2)
    }
    problem += 0
    for vertex in range(order):
        problem += pulp.lpSum(x[vertex, color] for color in range(color_count)) == 1
    for color in range(color_count):
        problem += pulp.lpSum(x[vertex, color] for vertex in range(order)) >= 1
    problem += x[0, 0] == 1
    if proper:
        for u, v in edges:
            for color in range(color_count):
                problem += x[u, color] + x[v, color] <= 1
    if tight:
        degrees = dict(graph.degree())
        for color in range(color_count):
            problem += (
                pulp.lpSum(
                    degrees[nodes[vertex]] * x[vertex, color]
                    for vertex in range(order)
                )
                == color_count - 1
            )
    for edge_index, (u, v) in enumerate(edges):
        for pair_index, (first, second) in enumerate(pairs):
            for orientation, (left, right) in enumerate(
                ((first, second), (second, first))
            ):
                variable = y[edge_index, pair_index, orientation]
                problem += variable <= x[u, left]
                problem += variable <= x[v, right]
                problem += variable >= x[u, left] + x[v, right] - 1
    for pair_index in range(len(pairs)):
        problem += (
            pulp.lpSum(
                y[edge, pair_index, orientation]
                for edge in range(len(edges))
                for orientation in range(2)
            )
            >= 1
        )
    status = problem.solve(
        pulp.PULP_CBC_CMD(msg=False, timeLimit=120, threads=4, gapRel=0.0)
    )
    label = pulp.LpStatus[status]
    if label == "Infeasible":
        return None
    if label != "Optimal":
        raise ExactColoringStateLimitExceeded(
            f"CBC did not certify a {color_count}-color complete coloring: {label}"
        )
    return tuple(
        max(range(color_count), key=lambda color: pulp.value(x[vertex, color]))
        for vertex in range(order)
    )


def _fixed_coloring_sat(  # noqa: C901 - one shared encoding avoids divergent definitions
    graph: nx.Graph,
    color_count: int,
    property_name: str,
) -> tuple[int, ...] | None:
    nodes = list(graph)
    order = len(nodes)
    index = {node: position for position, node in enumerate(nodes)}
    edges = [(index[u], index[v]) for u, v in graph.edges()]
    neighbors = [[index[u] for u in graph[node]] for node in nodes]
    complete = property_name in {"achromatic", "pseudo_achromatic"}
    tight_complete = complete and len(edges) == color_count * (color_count - 1) // 2
    proper = tight_complete or property_name in {
        "grundy",
        "partial_grundy",
        "achromatic",
        "b_chromatic",
        "fall",
    }
    unordered = property_name in {
        "achromatic",
        "pseudo_achromatic",
        "b_chromatic",
        "fall",
    }
    pool = IDPool()
    formula = CNF()

    def x(vertex: int, color: int) -> int:
        return pool.id(("x", vertex, color))

    def marker(vertex: int, color: int) -> int:
        return pool.id(("marker", vertex, color))

    for vertex in range(order):
        formula.extend(
            CardEnc.equals(
                [x(vertex, color) for color in range(color_count)],
                bound=1,
                vpool=pool,
                encoding=EncType.seqcounter,
            )
        )
    for color in range(color_count):
        formula.append([x(vertex, color) for vertex in range(order)])
    if unordered:
        formula.append([x(0, 0)])
        for vertex in range(1, order):
            for color in range(1, color_count):
                formula.append(
                    [
                        -x(vertex, color),
                        *(x(earlier, color - 1) for earlier in range(vertex)),
                    ]
                )
    if proper:
        for u, v in edges:
            for color in range(color_count):
                formula.append([-x(u, color), -x(v, color)])
    if property_name == "grundy":
        for vertex in range(order):
            for color in range(1, color_count):
                if len(neighbors[vertex]) < color:
                    formula.append([-x(vertex, color)])
                    continue
                for earlier in range(color):
                    formula.append(
                        [
                            -x(vertex, color),
                            *(x(neighbor, earlier) for neighbor in neighbors[vertex]),
                        ]
                    )
    if property_name in {"partial_grundy", "b_chromatic"}:
        for color in range(color_count):
            witnesses = []
            required_count = color if property_name == "partial_grundy" else color_count - 1
            for vertex in range(order):
                if len(neighbors[vertex]) < required_count:
                    continue
                witness = marker(vertex, color)
                witnesses.append(witness)
                formula.append([-witness, x(vertex, color)])
                required_colors = (
                    range(color)
                    if property_name == "partial_grundy"
                    else (other for other in range(color_count) if other != color)
                )
                for required in required_colors:
                    formula.append(
                        [
                            -witness,
                            *(x(neighbor, required) for neighbor in neighbors[vertex]),
                        ]
                    )
            formula.append(witnesses)
    if property_name == "fall":
        for vertex in range(order):
            for color in range(color_count):
                for other in range(color_count):
                    if color == other:
                        continue
                    formula.append(
                        [
                            -x(vertex, color),
                            *(x(neighbor, other) for neighbor in neighbors[vertex]),
                        ]
                    )
    if complete:
        for first, second in combinations(range(color_count), 2):
            pair_witnesses = []
            for edge_index, (u, v) in enumerate(edges):
                for orientation, (left, right) in enumerate(
                    ((first, second), (second, first))
                ):
                    witness = pool.id(
                        ("pair", edge_index, first, second, orientation)
                    )
                    pair_witnesses.append(witness)
                    formula.append([-witness, x(u, left)])
                    formula.append([-witness, x(v, right)])
            formula.append(pair_witnesses)
    with Solver(name="cadical195", bootstrap_with=formula.clauses) as solver:
        if not solver.solve():
            return None
        model = set(solver.get_model() or ())
    return tuple(
        next(color for color in range(color_count) if x(vertex, color) in model)
        for vertex in range(order)
    )


def coloring_partition_bundle_sat(graph: nx.Graph) -> ColoringPartitionBundle:
    if not graph:
        return ColoringPartitionBundle(0, 0, 0, 0, 0, 0, 0)
    order = len(graph)
    maximum_degree = max(dict(graph.degree()).values(), default=0)
    minimum_degree = min(dict(graph.degree()).values(), default=0)
    edge_bound = min(
        order,
        int((1 + np.sqrt(1 + 8 * graph.number_of_edges())) // 2),
    )
    degrees = sorted(dict(graph.degree()).values())
    stair_upper = max(
        (
            color_count
            for color_count in range(1, order + 1)
            if all(
                degrees[order - color_count + offset] >= offset
                for offset in range(color_count)
            )
        ),
        default=1,
    )
    b_upper = max(
        (
            color_count
            for color_count in range(1, order + 1)
            if sum(degree >= color_count - 1 for degree in degrees) >= color_count
        ),
        default=1,
    )

    def maximum(property_name: str, upper: int) -> int:
        for color_count in range(upper, 0, -1):
            if _fixed_coloring_sat(graph, color_count, property_name) is not None:
                return color_count
        raise RuntimeError(f"One color must be feasible for {property_name}")

    grundy = maximum("grundy", min(order, maximum_degree + 1, stair_upper))
    partial = maximum(
        "partial_grundy", min(order, maximum_degree + 1, stair_upper)
    )
    tight_edge_bound = (
        graph.number_of_edges() == edge_bound * (edge_bound - 1) // 2
    )
    tight_witness = (
        _fixed_coloring_milp(graph, edge_bound, "achromatic")
        if tight_edge_bound
        else None
    )
    if tight_witness is not None:
        achromatic = pseudo = edge_bound
    elif tight_edge_bound:
        achromatic = maximum("achromatic", edge_bound - 1)
        pseudo = maximum("pseudo_achromatic", edge_bound - 1)
    else:
        achromatic = maximum("achromatic", edge_bound)
        pseudo = maximum("pseudo_achromatic", edge_bound)
    b_chromatic = maximum(
        "b_chromatic", min(order, maximum_degree + 1, b_upper)
    )
    fall_orders = [
        color_count
        for color_count in range(1, min(order, minimum_degree + 1) + 1)
        if _fixed_coloring_sat(graph, color_count, "fall") is not None
    ]
    return ColoringPartitionBundle(
        grundy,
        partial,
        achromatic,
        pseudo,
        b_chromatic,
        min(fall_orders) if fall_orders else None,
        max(fall_orders) if fall_orders else None,
    )


def coloring_partition_bundle_milp(
    graph: nx.Graph,
    *,
    complete_coloring_upper_bound: int | None = None,
) -> ColoringPartitionBundle:
    if not graph:
        return ColoringPartitionBundle(0, 0, 0, 0, 0, 0, 0)
    order = len(graph)
    maximum_degree = max(dict(graph.degree()).values(), default=0)
    minimum_degree = min(dict(graph.degree()).values(), default=0)
    edge_bound = min(
        order,
        int((1 + np.sqrt(1 + 8 * graph.number_of_edges())) // 2),
    )
    if complete_coloring_upper_bound is not None:
        edge_bound = min(edge_bound, complete_coloring_upper_bound)

    def maximum(property_name: str, upper: int) -> int:
        for color_count in range(upper, 0, -1):
            witness = _fixed_coloring_milp(graph, color_count, property_name)
            if witness is not None:
                return color_count
        raise RuntimeError(f"One color must be feasible for {property_name}")

    grundy = maximum("grundy", min(order, maximum_degree + 1))
    partial = maximum("partial_grundy", min(order, maximum_degree + 1))
    achromatic = maximum("achromatic", edge_bound)
    pseudo = maximum("pseudo_achromatic", edge_bound)
    b_chromatic = maximum("b_chromatic", min(order, maximum_degree + 1))
    fall_orders = [
        color_count
        for color_count in range(1, min(order, minimum_degree + 1) + 1)
        if _fixed_coloring_milp(graph, color_count, "fall") is not None
    ]
    return ColoringPartitionBundle(
        grundy,
        partial,
        achromatic,
        pseudo,
        b_chromatic,
        min(fall_orders) if fall_orders else None,
        max(fall_orders) if fall_orders else None,
    )


def _ordered_property_exists(
    classes: list[list[int]],
    neighbor_color_masks: list[int],
    *,
    partial: bool,
) -> bool:
    color_count = len(classes)

    def search(placed: int) -> bool:
        if placed == (1 << color_count) - 1:
            return True
        for color, vertices in enumerate(classes):
            bit = 1 << color
            if placed & bit:
                continue
            if partial:
                admissible = any(
                    neighbor_color_masks[vertex] & placed == placed
                    for vertex in vertices
                )
            else:
                admissible = all(
                    neighbor_color_masks[vertex] & placed == placed
                    for vertex in vertices
                )
            if admissible and search(placed | bit):
                return True
        return False

    return search(0)


def _score_partition(
    order: int,
    edges: tuple[tuple[int, int], ...],
    colors: tuple[int, ...],
) -> tuple[int, bool, bool, bool, bool, bool, bool]:
    color_count = max(colors, default=-1) + 1
    classes = [[] for _ in range(color_count)]
    for vertex, color in enumerate(colors):
        classes[color].append(vertex)
    neighbor_color_masks = [0] * order
    proper = True
    pair_masks = [0] * color_count
    for u, v in edges:
        cu, cv = colors[u], colors[v]
        if cu == cv:
            proper = False
            continue
        neighbor_color_masks[u] |= 1 << cv
        neighbor_color_masks[v] |= 1 << cu
        pair_masks[cu] |= 1 << cv
        pair_masks[cv] |= 1 << cu
    all_colors = (1 << color_count) - 1
    complete = all(
        pair_masks[color] | (1 << color) == all_colors
        for color in range(color_count)
    )
    if not proper:
        return color_count, False, complete, False, False, False, False
    colorful_class = []
    all_colorful = True
    for color, vertices in enumerate(classes):
        required = all_colors ^ (1 << color)
        flags = [neighbor_color_masks[vertex] & required == required for vertex in vertices]
        colorful_class.append(any(flags))
        all_colorful &= all(flags)
    grundy = _ordered_property_exists(
        classes, neighbor_color_masks, partial=False
    )
    partial_grundy = grundy or _ordered_property_exists(
        classes, neighbor_color_masks, partial=True
    )
    return (
        color_count,
        True,
        complete,
        grundy,
        partial_grundy,
        all(colorful_class),
        all_colorful,
    )


def _enumerate_color_partitions(order: int):
    if order == 0:
        yield ()
        return
    colors = [0] * order

    def search(vertex: int, maximum: int):
        if vertex == order:
            yield tuple(colors)
            return
        for color in range(maximum + 2):
            colors[vertex] = color
            yield from search(vertex + 1, max(maximum, color))

    yield from search(1, 0)


@lru_cache(maxsize=32_768)
def _bundle_from_signature(
    order: int,
    edges: tuple[tuple[int, int], ...],
) -> ColoringPartitionBundle:
    if order == 0:
        return ColoringPartitionBundle(0, 0, 0, 0, 0, 0, 0)
    grundy = partial = achromatic = pseudo = b_chromatic = 1
    fall_min: int | None = None
    fall_max: int | None = None
    for colors in _enumerate_color_partitions(order):
        (
            color_count,
            proper,
            complete,
            is_grundy,
            is_partial,
            is_b_coloring,
            is_fall,
        ) = _score_partition(order, edges, colors)
        if complete:
            pseudo = max(pseudo, color_count)
        if not proper:
            continue
        if complete:
            achromatic = max(achromatic, color_count)
        if is_grundy:
            grundy = max(grundy, color_count)
        if is_partial:
            partial = max(partial, color_count)
        if is_b_coloring:
            b_chromatic = max(b_chromatic, color_count)
        if is_fall:
            fall_min = color_count if fall_min is None else min(fall_min, color_count)
            fall_max = color_count if fall_max is None else max(fall_max, color_count)
    return ColoringPartitionBundle(
        grundy,
        partial,
        achromatic,
        pseudo,
        b_chromatic,
        fall_min,
        fall_max,
    )


def coloring_partition_bundle(graph: nx.Graph) -> ColoringPartitionBundle:
    if len(graph) > 9:
        if _is_complete(graph):
            order = len(graph)
            return ColoringPartitionBundle(
                order, order, order, order, order, order, order
            )
        bipartition = _complete_bipartition(graph)
        if bipartition is not None:
            smaller = min(map(len, bipartition))
            return ColoringPartitionBundle(
                2,
                2,
                2,
                smaller + 1,
                2,
                2,
                2,
            )
        return coloring_partition_bundle_sat(graph)
    nodes = list(graph)
    index = {node: position for position, node in enumerate(nodes)}
    edges = tuple(sorted((min(index[u], index[v]), max(index[u], index[v])) for u, v in graph.edges()))
    return _bundle_from_signature(len(nodes), edges)


def grundy_number(graph: nx.Graph) -> int:
    return coloring_partition_bundle(graph).grundy_number


def partial_grundy_number(graph: nx.Graph) -> int:
    return coloring_partition_bundle(graph).partial_grundy_number


def achromatic_number(graph: nx.Graph) -> int:
    return coloring_partition_bundle(graph).achromatic_number


def pseudo_achromatic_number(graph: nx.Graph) -> int:
    return coloring_partition_bundle(graph).pseudo_achromatic_number


def b_chromatic_number(graph: nx.Graph) -> int:
    return coloring_partition_bundle(graph).b_chromatic_number


def fall_chromatic_number(graph: nx.Graph) -> int | None:
    return coloring_partition_bundle(graph).fall_chromatic_number


def fall_achromatic_number(graph: nx.Graph) -> int | None:
    return coloring_partition_bundle(graph).fall_achromatic_number


def has_fall_coloring(graph: nx.Graph) -> bool:
    return coloring_partition_bundle(graph).has_fall_coloring

from __future__ import annotations

from collections import deque
from collections.abc import Callable
from math import ceil, log2
from typing import Any

import networkx as nx


def is_rainbow_connected_coloring(
    graph: nx.Graph, coloring: dict[frozenset, int]
) -> bool:
    """Independently check that ``coloring`` rainbow-connects ``graph``."""
    if len(graph) <= 1:
        return True
    if not nx.is_connected(graph):
        return False
    for left, right in graph.edges():
        if frozenset((left, right)) not in coloring:
            return False
    for source in graph:
        reached: set[tuple[Any, frozenset[int]]] = {(source, frozenset())}
        queue = deque(reached)
        visible = {source}
        while queue:
            vertex, used = queue.popleft()
            for neighbor in graph[vertex]:
                color = coloring[frozenset((vertex, neighbor))]
                if color in used:
                    continue
                state = (neighbor, used | {color})
                if state not in reached:
                    reached.add(state)
                    visible.add(neighbor)
                    queue.append(state)
        if len(visible) != len(graph):
            return False
    return True


def rainbow_connection_coloring(
    graph: nx.Graph, color_count: int
) -> dict[frozenset, int] | None:
    """Return an exact SAT witness using at most ``color_count`` colors."""
    from pysat.card import CardEnc, EncType
    from pysat.formula import CNF, IDPool
    from pysat.solvers import Solver

    if len(graph) <= 1:
        return {}
    if not nx.is_connected(graph) or color_count < 1:
        return None

    nodes = list(graph)
    node_index = {vertex: index for index, vertex in enumerate(nodes)}
    edges = [
        (min(node_index[left], node_index[right]), max(node_index[left], node_index[right]))
        for left, right in graph.edges()
    ]
    edges.sort()
    edge_index = {edge: index for index, edge in enumerate(edges)}
    indexed = nx.Graph()
    indexed.add_nodes_from(range(len(nodes)))
    indexed.add_edges_from(edges)

    variables = IDPool()
    cnf = CNF()

    def edge_color(edge: int, color: int) -> int:
        return variables.id(("edge_color", edge, color))

    for edge in range(len(edges)):
        literals = [edge_color(edge, color) for color in range(color_count)]
        cnf.extend(
            CardEnc.equals(
                lits=literals,
                bound=1,
                vpool=variables,
                encoding=EncType.seqcounter,
            ).clauses
        )

    # Color names are interchangeable, so one edge may be fixed to color zero.
    cnf.append([edge_color(0, 0)])
    for source in range(len(nodes)):
        for target in range(source + 1, len(nodes)):
            path_literals: list[int] = []
            for path_number, path in enumerate(
                nx.all_simple_paths(indexed, source, target, cutoff=color_count)
            ):
                path_edge_indices = [
                    edge_index[(min(left, right), max(left, right))]
                    for left, right in zip(path, path[1:], strict=False)
                ]
                witness = variables.id(("path", source, target, path_number))
                path_literals.append(witness)
                for first in range(len(path_edge_indices)):
                    for second in range(first + 1, len(path_edge_indices)):
                        for color in range(color_count):
                            cnf.append(
                                [
                                    -witness,
                                    -edge_color(path_edge_indices[first], color),
                                    -edge_color(path_edge_indices[second], color),
                                ]
                            )
            if not path_literals:
                return None
            cnf.append(path_literals)

    with Solver(name="cadical195", bootstrap_with=cnf.clauses) as solver:
        if not solver.solve():
            return None
        model = set(solver.get_model())

    coloring: dict[frozenset, int] = {}
    for edge, (left, right) in enumerate(edges):
        color = next(
            color for color in range(color_count) if edge_color(edge, color) in model
        )
        coloring[frozenset((nodes[left], nodes[right]))] = color
    if not is_rainbow_connected_coloring(graph, coloring):
        raise RuntimeError("SAT solver returned an invalid rainbow-coloring witness")
    return coloring


def rainbow_connection_number(graph: nx.Graph) -> int:
    """Compute the rainbow connection number of a connected simple graph."""
    order = len(graph)
    if order <= 1:
        return 0
    if not nx.is_connected(graph):
        raise ValueError("The rainbow connection number is defined here for connected graphs.")
    if _is_complete(graph):
        return 1
    if nx.is_tree(graph):
        return order - 1
    lower = nx.diameter(graph)
    for color_count in range(lower, order):
        if rainbow_connection_coloring(graph, color_count) is not None:
            return color_count
    raise RuntimeError("The spanning-tree upper bound failed unexpectedly")


def _maximal_matchings(graph: nx.Graph) -> list[tuple[tuple, ...]]:
    nodes = list(graph)
    matchings: list[tuple[tuple, ...]] = []

    def visit(index: int, used: set, edges: list[tuple]) -> None:
        while index < len(nodes) and nodes[index] in used:
            index += 1
        if index == len(nodes):
            if all(left in used or right in used for left, right in graph.edges()):
                matchings.append(tuple(edges))
            return
        vertex = nodes[index]
        visit(index + 1, used, edges)
        used.add(vertex)
        for neighbor in graph[vertex]:
            if neighbor in used:
                continue
            used.add(neighbor)
            edges.append((vertex, neighbor))
            visit(index + 1, used, edges)
            edges.pop()
            used.remove(neighbor)
        used.remove(vertex)

    visit(0, set(), [])
    return matchings


def broadcast_time_bruteforce(graph: nx.Graph) -> int:
    nodes = list(graph)
    index = {node: i for i, node in enumerate(nodes)}
    full = (1 << len(nodes)) - 1
    matchings = _maximal_matchings(graph)
    best = len(nodes)
    for source in nodes:
        start = 1 << index[source]
        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            informed, distance = queue.popleft()
            if informed == full:
                best = min(best, distance)
                break
            for matching in matchings:
                updated = informed
                for left, right in matching:
                    left_bit = 1 << index[left]
                    right_bit = 1 << index[right]
                    if bool(informed & left_bit) != bool(informed & right_bit):
                        updated |= left_bit | right_bit
                if updated not in seen:
                    seen.add(updated)
                    queue.append((updated, distance + 1))
    return best


def gossip_time_bruteforce(graph: nx.Graph) -> int:
    nodes = list(graph)
    index = {node: i for i, node in enumerate(nodes)}
    full = (1 << len(nodes)) - 1
    start = tuple(1 << index[node] for node in nodes)
    matchings = _maximal_matchings(graph)
    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        knowledge, distance = queue.popleft()
        if all(value == full for value in knowledge):
            return distance
        for matching in matchings:
            updated = list(knowledge)
            for left, right in matching:
                left_index = index[left]
                right_index = index[right]
                union = knowledge[left_index] | knowledge[right_index]
                updated[left_index] = updated[right_index] = union
            state = tuple(updated)
            if state not in seen:
                seen.add(state)
                queue.append((state, distance + 1))
    raise RuntimeError("No gossip schedule found")


def polling_time_bruteforce(graph: nx.Graph) -> int:
    nodes = list(graph)
    index = {node: i for i, node in enumerate(nodes)}
    full = (1 << len(nodes)) - 1
    matchings = _maximal_matchings(graph)
    best = 2 * len(nodes)
    for root in nodes:
        root_bit = 1 << index[root]
        start = (root_bit, tuple(root_bit if node == root else 0 for node in nodes))
        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            (queried, responses), distance = queue.popleft()
            if responses[index[root]] == full:
                best = min(best, distance)
                break
            if distance >= best:
                continue
            for matching in matchings:
                updated_queried = queried
                updated_responses = list(responses)
                for left, right in matching:
                    left_index = index[left]
                    right_index = index[right]
                    left_bit = 1 << left_index
                    right_bit = 1 << right_index
                    if queried & (left_bit | right_bit):
                        updated_queried |= left_bit | right_bit
                        union = responses[left_index] | responses[right_index]
                        updated_responses[left_index] = updated_responses[right_index] = union
                newly_queried = updated_queried & ~queried
                while newly_queried:
                    bit = newly_queried & -newly_queried
                    updated_responses[bit.bit_length() - 1] |= bit
                    newly_queried &= newly_queried - 1
                state = (updated_queried, tuple(updated_responses))
                if state not in seen:
                    seen.add(state)
                    queue.append((state, distance + 1))
    return best


class _BinaryProgram:
    def __init__(self) -> None:
        self.lower: list[float] = []
        self.upper: list[float] = []
        self.row: list[int] = []
        self.column: list[int] = []
        self.value: list[float] = []
        self.constraint_lower: list[float] = []
        self.constraint_upper: list[float] = []

    def variable(self, lower: int = 0, upper: int = 1) -> int:
        index = len(self.lower)
        self.lower.append(lower)
        self.upper.append(upper)
        return index

    def constraint(
        self,
        coefficients: list[tuple[int, int]],
        *,
        lower: float = -float("inf"),
        upper: float = float("inf"),
    ) -> None:
        row = len(self.constraint_lower)
        for column, value in coefficients:
            self.row.append(row)
            self.column.append(column)
            self.value.append(value)
        self.constraint_lower.append(lower)
        self.constraint_upper.append(upper)

    def feasible(self) -> bool:
        import numpy as np
        from scipy.optimize import Bounds, LinearConstraint, milp
        from scipy.sparse import coo_array

        variable_count = len(self.lower)
        matrix = coo_array(
            (self.value, (self.row, self.column)),
            shape=(len(self.constraint_lower), variable_count),
        ).tocsc()
        result = milp(
            np.zeros(variable_count),
            integrality=np.ones(variable_count),
            bounds=Bounds(self.lower, self.upper),
            constraints=LinearConstraint(
                matrix,
                np.asarray(self.constraint_lower),
                np.asarray(self.constraint_upper),
            ),
            options={"presolve": True},
        )
        if result.status not in {0, 2}:
            raise RuntimeError(f"Communication-time MILP failed: {result.message}")
        return result.status == 0


def _indexed_graph(graph: nx.Graph) -> tuple[list, list[tuple[int, int]]]:
    nodes = list(graph)
    index = {node: position for position, node in enumerate(nodes)}
    edges = [(index[left], index[right]) for left, right in graph.edges()]
    return nodes, edges


def _add_matching_constraints(
    program: _BinaryProgram,
    order: int,
    edges: list[tuple[int, int]],
    rounds: int,
) -> list[list[int]]:
    calls = [[program.variable() for _ in edges] for _ in range(rounds)]
    for time in range(rounds):
        for vertex in range(order):
            incident = [
                (calls[time][edge_index], 1)
                for edge_index, edge in enumerate(edges)
                if vertex in edge
            ]
            program.constraint(incident, upper=1)
    return calls


def _add_information_process(
    program: _BinaryProgram,
    order: int,
    edges: list[tuple[int, int]],
    calls: list[list[int]],
    rounds: int,
    initial: list[list[int]],
    *,
    activation: list[list[list[int]]] | None = None,
    initial_is_variable: bool = False,
) -> list[list[list[int]]]:
    item_count = len(initial)
    information = [
        [
            [
                initial[item][vertex]
                if initial_is_variable
                else program.variable(initial[item][vertex], initial[item][vertex])
            ]
            + [program.variable() for _ in range(rounds)]
            for vertex in range(order)
        ]
        for item in range(item_count)
    ]
    incoming: list[list[tuple[int, int]]] = [[] for _ in range(order)]
    for edge_index, (left, right) in enumerate(edges):
        incoming[left].append((edge_index, right))
        incoming[right].append((edge_index, left))

    for time in range(1, rounds + 1):
        transfers: dict[tuple[int, int, int], int] = {}
        for item in range(item_count):
            for edge_index, (left, right) in enumerate(edges):
                for target, source in ((left, right), (right, left)):
                    transfer = program.variable()
                    transfers[item, target, edge_index] = transfer
                    call = calls[time - 1][edge_index]
                    previous = information[item][source][time - 1]
                    program.constraint([(transfer, 1), (call, -1)], upper=0)
                    program.constraint([(transfer, 1), (previous, -1)], upper=0)
                    program.constraint(
                        [(transfer, 1), (call, -1), (previous, -1)], lower=-1
                    )

        for item in range(item_count):
            for vertex in range(order):
                current = information[item][vertex][time]
                previous = information[item][vertex][time - 1]
                program.constraint([(current, 1), (previous, -1)], lower=0)
                causes = [
                    transfers[item, vertex, edge_index]
                    for edge_index, _ in incoming[vertex]
                ]
                for cause in causes:
                    program.constraint([(current, 1), (cause, -1)], lower=0)
                upper_terms = [(current, 1), (previous, -1)]
                upper_terms.extend((cause, -1) for cause in causes)
                if activation is not None:
                    activator = activation[item][vertex][time]
                    upper_terms.append((activator, -1))
                    program.constraint([(current, 1), (activator, -1)], lower=0)
                program.constraint(upper_terms, upper=0)
    return information


def _broadcast_times(graph: nx.Graph) -> list[int]:
    nodes = list(graph)
    index = {node: position for position, node in enumerate(nodes)}
    full = (1 << len(nodes)) - 1
    matchings = _maximal_matchings(graph)
    times: list[int] = []
    for source in nodes:
        start = 1 << index[source]
        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            informed, distance = queue.popleft()
            if informed == full:
                times.append(distance)
                break
            for matching in matchings:
                updated = informed
                for left, right in matching:
                    left_bit = 1 << index[left]
                    right_bit = 1 << index[right]
                    if bool(informed & left_bit) != bool(informed & right_bit):
                        updated |= left_bit | right_bit
                if updated not in seen:
                    seen.add(updated)
                    queue.append((updated, distance + 1))
        else:
            raise RuntimeError("No broadcast schedule found")
    return times


def _gossip_feasible(graph: nx.Graph, rounds: int) -> bool:
    nodes, edges = _indexed_graph(graph)
    order = len(nodes)
    program = _BinaryProgram()
    calls = _add_matching_constraints(program, order, edges, rounds)
    initial = [[int(item == vertex) for vertex in range(order)] for item in range(order)]
    information = _add_information_process(
        program, order, edges, calls, rounds, initial
    )
    for item in range(order):
        for vertex in range(order):
            final = information[item][vertex][rounds]
            program.lower[final] = 1
            program.upper[final] = 1
    return program.feasible()


def _minimum_feasible_rounds(
    lower: int, upper: int, feasible: Callable[[int], bool]
) -> int:
    while lower < upper:
        middle = (lower + upper) // 2
        if feasible(middle):
            upper = middle
        else:
            lower = middle + 1
    return lower


def _broadcast_feasible(graph: nx.Graph, rounds: int) -> bool:
    nodes, edges = _indexed_graph(graph)
    order = len(nodes)
    program = _BinaryProgram()
    calls = _add_matching_constraints(program, order, edges, rounds)
    sources = [program.variable() for _ in range(order)]
    program.constraint([(source, 1) for source in sources], lower=1, upper=1)
    information = _add_information_process(
        program,
        order,
        edges,
        calls,
        rounds,
        [sources],
        initial_is_variable=True,
    )[0]
    for vertex in range(order):
        final = information[vertex][rounds]
        program.lower[final] = 1
        program.upper[final] = 1
    return program.feasible()


def broadcast_time_milp(graph: nx.Graph) -> int:
    lower = max(ceil(log2(len(graph))), nx.radius(graph))
    return _minimum_feasible_rounds(
        lower, len(graph) - 1, lambda rounds: _broadcast_feasible(graph, rounds)
    )


def gossip_time_milp(graph: nx.Graph) -> int:
    order = len(graph)
    complete_lower = ceil(log2(order)) + order % 2
    lower = max(nx.diameter(graph), complete_lower)
    return _minimum_feasible_rounds(
        lower, 2 * (order - 1), lambda rounds: _gossip_feasible(graph, rounds)
    )


def _polling_feasible(
    graph: nx.Graph, rounds: int, *, fixed_root: int | None = None
) -> bool:
    nodes, edges = _indexed_graph(graph)
    order = len(nodes)
    program = _BinaryProgram()
    calls = _add_matching_constraints(program, order, edges, rounds)
    roots = [
        program.variable(int(vertex == fixed_root), int(vertex == fixed_root))
        if fixed_root is not None
        else program.variable()
        for vertex in range(order)
    ]
    program.constraint([(root, 1) for root in roots], lower=1, upper=1)
    if fixed_root is not None:
        first_edge = next(
            edge_index
            for edge_index, edge in enumerate(edges)
            if fixed_root in edge
        )
        first_call = calls[0][first_edge]
        program.lower[first_call] = 1
        program.upper[first_call] = 1
    queries = _add_information_process(
        program,
        order,
        edges,
        calls,
        rounds,
        [roots],
        initial_is_variable=True,
    )[0]
    for vertex in range(order):
        final_query = queries[vertex][rounds]
        program.lower[final_query] = 1
        program.upper[final_query] = 1

    response_initial = [
        [roots[item] if item == vertex else program.variable(0, 0) for vertex in range(order)]
        for item in range(order)
    ]
    activation = [
        [
            [queries[vertex][time] if item == vertex else program.variable(0, 0)
             for time in range(rounds + 1)]
            for vertex in range(order)
        ]
        for item in range(order)
    ]
    responses = _add_information_process(
        program,
        order,
        edges,
        calls,
        rounds,
        response_initial,
        activation=activation,
        initial_is_variable=True,
    )
    for item in range(order):
        for vertex in range(order):
            program.constraint(
                [(responses[item][vertex][rounds], 1), (roots[vertex], -1)],
                lower=0,
            )
    return program.feasible()


def _polling_feasible_cp_sat(
    graph: nx.Graph, rounds: int, *, fixed_root: int | None = None
) -> bool:
    from ortools.sat.python import cp_model

    nodes, edges = _indexed_graph(graph)
    order = len(nodes)
    model = cp_model.CpModel()
    calls = [
        [model.new_bool_var(f"call_{time}_{edge}") for edge in range(len(edges))]
        for time in range(rounds)
    ]
    for time in range(rounds):
        for vertex in range(order):
            model.add(
                sum(
                    calls[time][edge]
                    for edge, endpoints in enumerate(edges)
                    if vertex in endpoints
                )
                <= 1
            )
    roots = [model.new_bool_var(f"root_{vertex}") for vertex in range(order)]
    model.add(sum(roots) == 1)
    if fixed_root is not None:
        for vertex, root in enumerate(roots):
            model.add(root == int(vertex == fixed_root))
        first_edge = next(
            edge for edge, endpoints in enumerate(edges) if fixed_root in endpoints
        )
        model.add(calls[0][first_edge] == 1)

    incoming: list[list[tuple[int, int]]] = [[] for _ in range(order)]
    for edge, (left, right) in enumerate(edges):
        incoming[left].append((edge, right))
        incoming[right].append((edge, left))

    def information_process(
        name: str,
        initial: list[list],
        activation: list[list[list]] | None = None,
    ) -> list[list[list]]:
        item_count = len(initial)
        information = [
            [
                [initial[item][vertex]]
                + [
                    model.new_bool_var(f"{name}_{item}_{vertex}_{time}")
                    for time in range(1, rounds + 1)
                ]
                for vertex in range(order)
            ]
            for item in range(item_count)
        ]
        for time in range(1, rounds + 1):
            transfers: dict[tuple[int, int, int], Any] = {}
            for item in range(item_count):
                for edge, (left, right) in enumerate(edges):
                    for target, source in ((left, right), (right, left)):
                        transfer = model.new_bool_var(
                            f"{name}_transfer_{item}_{target}_{edge}_{time}"
                        )
                        transfers[item, target, edge] = transfer
                        model.add(transfer <= calls[time - 1][edge])
                        model.add(transfer <= information[item][source][time - 1])
                        model.add(
                            transfer
                            >= calls[time - 1][edge]
                            + information[item][source][time - 1]
                            - 1
                        )
            for item in range(item_count):
                for vertex in range(order):
                    current = information[item][vertex][time]
                    previous = information[item][vertex][time - 1]
                    causes = [
                        transfers[item, vertex, edge] for edge, _ in incoming[vertex]
                    ]
                    model.add(current >= previous)
                    for cause in causes:
                        model.add(current >= cause)
                    upper = previous + sum(causes)
                    if activation is not None:
                        activator = activation[item][vertex][time]
                        model.add(current >= activator)
                        upper += activator
                    model.add(current <= upper)
        return information

    queries = information_process("query", [roots])[0]
    for vertex in range(order):
        model.add(queries[vertex][rounds] == 1)
    symmetry_classes: list[list[int]] = []
    if fixed_root is not None and _is_complete(graph):
        symmetry_classes = [[vertex for vertex in range(order) if vertex != fixed_root]]
    elif fixed_root is not None and _balanced_complete_bipartite_order(graph) is not None:
        left_nodes, right_nodes = nx.bipartite.sets(graph)
        indexed = {node: position for position, node in enumerate(nodes)}
        symmetry_classes = [
            sorted(indexed[node] for node in side if indexed[node] != fixed_root)
            for side in (left_nodes, right_nodes)
        ]
    for equivalence_class in symmetry_classes:
        for first, second in zip(equivalence_class, equivalence_class[1:], strict=False):
            for time in range(rounds + 1):
                model.add(queries[first][time] >= queries[second][time])
    response_initial = [
        [roots[item] if item == vertex else 0 for vertex in range(order)]
        for item in range(order)
    ]
    activation = [
        [
            [queries[vertex][time] if item == vertex else 0 for time in range(rounds + 1)]
            for vertex in range(order)
        ]
        for item in range(order)
    ]
    responses = information_process("response", response_initial, activation)
    for item in range(order):
        for vertex in range(order):
            model.add(responses[item][vertex][rounds] >= roots[vertex])

    solver = cp_model.CpSolver()
    solver.parameters.num_search_workers = 8
    solver.parameters.symmetry_level = 3
    status = solver.solve(model)
    if status not in {cp_model.OPTIMAL, cp_model.INFEASIBLE}:
        raise RuntimeError(f"Polling CP-SAT did not certify feasibility: {solver.status_name(status)}")
    return status == cp_model.OPTIMAL


def polling_time_milp(graph: nx.Graph) -> int:
    order = len(graph)
    lower = max(2 * nx.radius(graph), ceil(log2(order)) + 1)
    upper = 2 * (order - 1)
    fixed_root = None
    balanced_bipartite = _balanced_complete_bipartite_order(graph)
    if _is_complete(graph):
        upper = 2 * ceil(log2(order))
        fixed_root = 0
    elif balanced_bipartite is not None:
        upper = 2 * ceil(log2(order))
        fixed_root = 0
    return _minimum_feasible_rounds(
        lower,
        upper,
        lambda rounds: _polling_feasible_cp_sat(
            graph, rounds, fixed_root=fixed_root
        ),
    )


def _is_star(graph: nx.Graph) -> bool:
    return len(graph) >= 3 and sorted(dict(graph.degree()).values()) == [1] * (
        len(graph) - 1
    ) + [len(graph) - 1]


def _is_path(graph: nx.Graph) -> bool:
    return len(graph) >= 2 and nx.is_tree(graph) and max(dict(graph.degree()).values()) <= 2


def _is_cycle(graph: nx.Graph) -> bool:
    return len(graph) >= 3 and all(degree == 2 for _, degree in graph.degree())


def _is_complete(graph: nx.Graph) -> bool:
    return graph.number_of_edges() == len(graph) * (len(graph) - 1) // 2


def _balanced_complete_bipartite_order(graph: nx.Graph) -> int | None:
    if not nx.is_bipartite(graph):
        return None
    left, right = nx.bipartite.sets(graph)
    if len(left) != len(right):
        return None
    if graph.number_of_edges() != len(left) * len(right):
        return None
    return len(left)


def broadcast_time(graph: nx.Graph) -> int:
    order = len(graph)
    if _is_complete(graph):
        return ceil(log2(order))
    if _balanced_complete_bipartite_order(graph) is not None:
        return ceil(log2(order))
    if _is_star(graph):
        return order - 1
    if _is_path(graph) or _is_cycle(graph):
        return ceil(order / 2)
    if order <= 10:
        return broadcast_time_bruteforce(graph)
    return broadcast_time_milp(graph)


def gossip_time(graph: nx.Graph) -> int:
    order = len(graph)
    if _is_complete(graph):
        return ceil(log2(order)) + (order % 2)
    if _balanced_complete_bipartite_order(graph) is not None:
        return ceil(log2(order))
    if _is_star(graph):
        return 2 * order - 3
    if _is_path(graph):
        return order - 1 + (order % 2)
    if _is_cycle(graph):
        return order // 2 if order % 2 == 0 else (order + 3) // 2
    if order <= 6:
        return gossip_time_bruteforce(graph)
    return gossip_time_milp(graph)


def polling_time(graph: nx.Graph) -> int:
    order = len(graph)
    if _is_star(graph):
        return 2 * order - 2
    if _is_path(graph):
        return 2 if order == 2 else max(order, 4)
    if _is_cycle(graph):
        return order
    if order <= 6:
        return polling_time_bruteforce(graph)
    return polling_time_milp(graph)

