from __future__ import annotations

from dataclasses import dataclass
from itertools import combinations, product

import networkx as nx
import numpy as np
from scipy.optimize import Bounds, LinearConstraint, milp


@dataclass(frozen=True)
class DomaticInterventionBundle:
    broadcast_domination_number: int
    domatic_number: int
    total_domatic_number: int
    connected_domatic_number: int
    paired_domatic_number: int | None
    edge_domatic_number: int
    bondage_number: int
    reinforcement_number: int


def _milp(c, integrality, lower, upper, rows, row_lower, row_upper):
    constraints = None
    if rows:
        constraints = LinearConstraint(
            np.asarray(rows, dtype=float),
            np.asarray(row_lower, dtype=float),
            np.asarray(row_upper, dtype=float),
        )
    result = milp(
        np.asarray(c, dtype=float),
        integrality=np.asarray(integrality, dtype=int),
        bounds=Bounds(np.asarray(lower, dtype=float), np.asarray(upper, dtype=float)),
        constraints=constraints,
        options={"presolve": True},
    )
    return result


def _append(rows, lower, upper, row, low, high) -> None:
    rows.append(row)
    lower.append(low)
    upper.append(high)


def _indexed_graph(graph: nx.Graph):
    nodes = list(graph)
    index = {node: i for i, node in enumerate(nodes)}
    neighbors = [[index[u] for u in graph[node]] for node in nodes]
    edges = [(index[u], index[v]) for u, v in graph.edges()]
    return nodes, neighbors, edges


def _domatic_at_least(graph: nx.Graph, classes: int, mode: str) -> bool:  # noqa: C901
    nodes, neighbors, edges = _indexed_graph(graph)
    order = len(nodes)
    x_size = order * classes
    rows, row_lower, row_upper = [], [], []

    if mode == "connected":
        directed = [(u, v) for u, v in edges for u, v in ((u, v), (v, u))]
        root_offset = x_size
        source_offset = root_offset + x_size
        flow_offset = source_offset + x_size
        variable_count = flow_offset + len(directed) * classes
    elif mode == "paired":
        matching_offset = x_size
        variable_count = matching_offset + len(edges) * classes
    else:
        variable_count = x_size

    def x(vertex: int, color: int) -> int:
        return color * order + vertex

    for vertex in range(order):
        row = [0] * variable_count
        for color in range(classes):
            row[x(vertex, color)] = 1
        _append(rows, row_lower, row_upper, row, 1, 1)

    open_neighborhood = mode == "total"
    for color in range(classes):
        for vertex in range(order):
            row = [0] * variable_count
            if not open_neighborhood:
                row[x(vertex, color)] = 1
            for neighbor in neighbors[vertex]:
                row[x(neighbor, color)] += 1
            _append(rows, row_lower, row_upper, row, 1, np.inf)

    integrality = [1] * variable_count
    upper = [1] * variable_count
    if mode == "connected":
        for color in range(classes):
            row = [0] * variable_count
            for vertex in range(order):
                row[root_offset + x(vertex, color)] = 1
            _append(rows, row_lower, row_upper, row, 1, 1)

            row = [0] * variable_count
            for vertex in range(order):
                row[source_offset + x(vertex, color)] = 1
                row[x(vertex, color)] -= 1
            _append(rows, row_lower, row_upper, row, 0, 0)

            for vertex in range(order):
                root = root_offset + x(vertex, color)
                source = source_offset + x(vertex, color)
                row = [0] * variable_count
                row[root] = 1
                row[x(vertex, color)] = -1
                _append(rows, row_lower, row_upper, row, -np.inf, 0)
                row = [0] * variable_count
                row[source] = 1
                row[root] = -order
                _append(rows, row_lower, row_upper, row, -np.inf, 0)
                upper[source] = order
                integrality[source] = 0

                row = [0] * variable_count
                row[source] = 1
                row[x(vertex, color)] = -1
                for arc_index, (tail, head) in enumerate(directed):
                    flow = flow_offset + color * len(directed) + arc_index
                    if head == vertex:
                        row[flow] += 1
                    if tail == vertex:
                        row[flow] -= 1
                _append(rows, row_lower, row_upper, row, 0, 0)

            for arc_index, (tail, head) in enumerate(directed):
                flow = flow_offset + color * len(directed) + arc_index
                upper[flow] = order
                integrality[flow] = 0
                for endpoint in (tail, head):
                    row = [0] * variable_count
                    row[flow] = 1
                    row[x(endpoint, color)] = -order
                    _append(rows, row_lower, row_upper, row, -np.inf, 0)

    if mode == "paired":
        for color in range(classes):
            for vertex in range(order):
                row = [0] * variable_count
                row[x(vertex, color)] = -1
                for edge_index, edge in enumerate(edges):
                    if vertex in edge:
                        row[matching_offset + color * len(edges) + edge_index] += 1
                _append(rows, row_lower, row_upper, row, 0, 0)

    result = _milp(
        [0] * variable_count,
        integrality,
        [0] * variable_count,
        upper,
        rows,
        row_lower,
        row_upper,
    )
    return bool(result.success)


def _max_domatic(graph: nx.Graph, mode: str) -> int | None:
    order = len(graph)
    if order == 0:
        return None
    minimum_degree = min(dict(graph.degree()).values())
    if mode == "total":
        upper = minimum_degree
    elif mode == "paired":
        upper = min(minimum_degree, order // 2)
    else:
        upper = minimum_degree + 1
    for classes in range(upper, 0, -1):
        if _domatic_at_least(graph, classes, mode):
            return classes
    return None


def broadcast_domination_number(graph: nx.Graph) -> int:
    nodes = list(graph)
    if not nodes:
        return 0
    distances = dict(nx.all_pairs_shortest_path_length(graph))
    choices = [
        (center, radius)
        for center in nodes
        for radius in range(1, max(distances[center].values()) + 1)
    ]
    rows = []
    for target in nodes:
        rows.append([
            int(distances[center][target] <= radius)
            for center, radius in choices
        ])
    result = _milp(
        [radius for _, radius in choices],
        [1] * len(choices),
        [0] * len(choices),
        [1] * len(choices),
        rows,
        [1] * len(rows),
        [np.inf] * len(rows),
    )
    if not result.success:
        raise RuntimeError("Broadcast-domination MILP did not solve")
    return round(float(result.fun))


def domatic_number(graph: nx.Graph) -> int:
    value = _max_domatic(graph, "ordinary")
    if value is None:
        raise ValueError("The domatic number is undefined on the empty graph")
    return value


def total_domatic_number(graph: nx.Graph) -> int:
    value = _max_domatic(graph, "total")
    if value is None:
        raise ValueError("No total-domatic partition exists")
    return value


def connected_domatic_number(graph: nx.Graph) -> int:
    value = _max_domatic(graph, "connected")
    if value is None:
        raise ValueError("No connected-domatic partition exists")
    return value


def paired_domatic_number(graph: nx.Graph) -> int | None:
    return _max_domatic(graph, "paired")


def _complete_bipartition_sizes(graph: nx.Graph) -> tuple[int, int] | None:
    if not nx.is_bipartite(graph):
        return None
    left, right = nx.bipartite.sets(graph)
    if graph.number_of_edges() != len(left) * len(right):
        return None
    return len(left), len(right)


def edge_domatic_number(graph: nx.Graph) -> int:
    order = len(graph)
    if graph.number_of_edges() == order * (order - 1) // 2:
        return order - 1 if order % 2 == 0 else order
    part_sizes = _complete_bipartition_sizes(graph)
    if part_sizes is not None:
        return max(part_sizes)
    return domatic_number(nx.line_graph(graph))


def reinforcement_number(graph: nx.Graph, domination: int | None = None) -> int:
    gamma = domination if domination is not None else _domination_number(graph)
    if gamma <= 1:
        return 0
    nodes, neighbors, _ = _indexed_graph(graph)
    order = len(nodes)
    rows, row_lower, row_upper = [], [], []
    row = [1] * order + [0] * order
    _append(rows, row_lower, row_upper, row, gamma - 1, gamma - 1)
    for vertex in range(order):
        row = [0] * (2 * order)
        for source in [vertex, *neighbors[vertex]]:
            row[source] = 1
        row[order + vertex] = 1
        _append(rows, row_lower, row_upper, row, 1, np.inf)
    result = _milp(
        [0] * order + [1] * order,
        [1] * (2 * order),
        [0] * (2 * order),
        [1] * (2 * order),
        rows,
        row_lower,
        row_upper,
    )
    if not result.success:
        raise RuntimeError("Reinforcement MILP did not solve")
    return round(float(result.fun))


def _dominating_set_of_size(
    order: int,
    edges: list[tuple[int, int]],
    deleted: set[int],
    cardinality: int,
) -> tuple[int, ...] | None:
    neighbors = [[] for _ in range(order)]
    for edge_index, (left, right) in enumerate(edges):
        if edge_index not in deleted:
            neighbors[left].append(right)
            neighbors[right].append(left)
    rows, row_lower, row_upper = [], [], []
    _append(rows, row_lower, row_upper, [1] * order, cardinality, cardinality)
    for vertex in range(order):
        row = [0] * order
        for source in [vertex, *neighbors[vertex]]:
            row[source] = 1
        _append(rows, row_lower, row_upper, row, 1, np.inf)
    result = _milp(
        [0] * order,
        [1] * order,
        [0] * order,
        [1] * order,
        rows,
        row_lower,
        row_upper,
    )
    if not result.success:
        return None
    return tuple(i for i, value in enumerate(result.x) if value > 0.5)


def bondage_number(graph: nx.Graph, domination: int | None = None) -> int:
    nodes, _, edges = _indexed_graph(graph)
    order = len(nodes)
    gamma = domination if domination is not None else _domination_number(graph)
    obstructions: list[tuple[tuple[int, ...], list[tuple[int, ...]]]] = []

    while True:
        variable_count = len(edges) + sum(len(bundles) for _, bundles in obstructions)
        rows, row_lower, row_upper = [], [], []
        witness_offset = len(edges)
        for _, bundles in obstructions:
            row = [0] * variable_count
            for bundle in bundles:
                witness = witness_offset
                witness_offset += 1
                row[witness] = 1
                for edge_index in bundle:
                    constraint = [0] * variable_count
                    constraint[witness] = 1
                    constraint[edge_index] = -1
                    _append(rows, row_lower, row_upper, constraint, -np.inf, 0)
            _append(rows, row_lower, row_upper, row, 1, np.inf)
        result = _milp(
            [1] * len(edges) + [0] * (variable_count - len(edges)),
            [1] * variable_count,
            [0] * variable_count,
            [1] * variable_count,
            rows,
            row_lower,
            row_upper,
        )
        if not result.success:
            raise RuntimeError("Bondage master MILP did not solve")
        deleted = {i for i, value in enumerate(result.x[: len(edges)]) if value > 0.5}
        dominating_set = _dominating_set_of_size(order, edges, deleted, gamma)
        if dominating_set is None:
            return len(deleted)

        selected = set(dominating_set)
        bundles = []
        for vertex in range(order):
            if vertex in selected:
                continue
            bundle = tuple(
                edge_index
                for edge_index, edge in enumerate(edges)
                if vertex in edge and bool(selected & set(edge))
            )
            if bundle:
                bundles.append(bundle)
        obstructions.append((dominating_set, bundles))


def _domination_number(graph: nx.Graph) -> int:
    nodes, neighbors, _ = _indexed_graph(graph)
    order = len(nodes)
    rows = []
    for vertex in range(order):
        row = [0] * order
        for source in [vertex, *neighbors[vertex]]:
            row[source] = 1
        rows.append(row)
    result = _milp(
        [1] * order,
        [1] * order,
        [0] * order,
        [1] * order,
        rows,
        [1] * order,
        [np.inf] * order,
    )
    if not result.success:
        raise RuntimeError("Domination MILP did not solve")
    return round(float(result.fun))


def domatic_intervention_bundle(
    graph: nx.Graph,
    domination: int | None = None,
) -> DomaticInterventionBundle:
    gamma = domination if domination is not None else _domination_number(graph)
    order = len(graph)
    if graph.number_of_edges() == order * (order - 1) // 2:
        return DomaticInterventionBundle(
            1,
            order,
            order // 2,
            order,
            order // 2 if order % 2 == 0 else None,
            order - 1 if order % 2 == 0 else order,
            (order + 1) // 2,
            0,
        )
    part_sizes = _complete_bipartition_sizes(graph)
    if part_sizes is not None:
        left, right = part_sizes
        smaller, larger = min(part_sizes), max(part_sizes)
        if smaller == 1:
            return DomaticInterventionBundle(
                1,
                2,
                1,
                1,
                1 if larger == 1 else None,
                larger,
                1,
                0,
            )
        return DomaticInterventionBundle(
            2,
            smaller,
            smaller,
            smaller,
            smaller if left == right else None,
            larger,
            3 if left == right == 2 else smaller,
            smaller - 1,
        )
    return DomaticInterventionBundle(
        broadcast_domination_number(graph),
        domatic_number(graph),
        total_domatic_number(graph),
        connected_domatic_number(graph),
        paired_domatic_number(graph),
        edge_domatic_number(graph),
        bondage_number(graph, gamma),
        reinforcement_number(graph, gamma),
    )


def _is_dominating(graph: nx.Graph, selected: set) -> bool:
    return all(vertex in selected or set(graph[vertex]) & selected for vertex in graph)


def _without_edges(graph: nx.Graph, deleted) -> nx.Graph:
    result = graph.copy()
    result.remove_edges_from(deleted)
    return result


def _brute_domatic(graph: nx.Graph, mode: str) -> int | None:
    nodes = list(graph)
    order = len(nodes)
    for classes in range(order, 0, -1):
        for assignment in product(range(classes), repeat=order):
            if set(assignment) != set(range(classes)):
                continue
            valid = True
            for color in range(classes):
                selected = {nodes[i] for i, value in enumerate(assignment) if value == color}
                if mode == "total":
                    valid &= all(set(graph[v]) & selected for v in nodes)
                else:
                    valid &= _is_dominating(graph, selected)
                if mode == "connected":
                    valid &= nx.is_connected(graph.subgraph(selected))
                if mode == "paired":
                    matching = nx.max_weight_matching(graph.subgraph(selected), maxcardinality=True)
                    valid &= 2 * len(matching) == len(selected)
            if valid:
                return classes
    return None


def domatic_intervention_bundle_bruteforce(graph: nx.Graph) -> DomaticInterventionBundle:
    nodes = list(graph)
    gamma = min(
        len(selected)
        for size in range(1, len(nodes) + 1)
        for chosen in combinations(nodes, size)
        if _is_dominating(graph, selected := set(chosen))
    )
    distances = dict(nx.all_pairs_shortest_path_length(graph))
    broadcast = min(
        sum(labels)
        for labels in product(
            *(range(max(distances[v].values()) + 1) for v in nodes)
        )
        if all(
            any(
                labels[i] > 0 and labels[i] >= distances[nodes[i]][target]
                for i in range(len(nodes))
            )
            for target in nodes
        )
    )
    reinforcement = 0 if gamma == 1 else min(
        sum(
            not (vertex in selected or set(graph[vertex]) & selected)
            for vertex in nodes
        )
        for chosen in combinations(nodes, gamma - 1)
        for selected in [set(chosen)]
    )
    edges = list(graph.edges())
    bondage = next(
        size
        for size in range(1, len(edges) + 1)
        if any(
            _domination_number(_without_edges(graph, deleted)) > gamma
            for deleted in combinations(edges, size)
        )
    )
    return DomaticInterventionBundle(
        broadcast,
        _brute_domatic(graph, "ordinary"),
        _brute_domatic(graph, "total"),
        _brute_domatic(graph, "connected"),
        _brute_domatic(graph, "paired"),
        _brute_domatic(nx.line_graph(graph), "ordinary"),
        bondage,
        reinforcement,
    )

from __future__ import annotations

from dataclasses import dataclass
from functools import cache
from itertools import combinations
from math import ceil, comb, factorial
from typing import Any

import networkx as nx
import numpy as np
from scipy.optimize import Bounds, LinearConstraint, milp
from scipy.sparse import lil_matrix


@dataclass(frozen=True)
class CertifiedValue[WitnessT]:
    value: int | bool
    witness: WitnessT


def _milp(
    objective: np.ndarray,
    integrality: np.ndarray,
    lower_bounds: np.ndarray,
    upper_bounds: np.ndarray,
    rows: list[dict[int, float]],
    row_lower: list[float],
    row_upper: list[float],
) -> np.ndarray | None:
    matrix = lil_matrix((len(rows), len(objective)), dtype=float)
    for row_index, coefficients in enumerate(rows):
        for column, value in coefficients.items():
            matrix[row_index, column] = value
    result = milp(
        c=objective,
        integrality=integrality,
        bounds=Bounds(lower_bounds, upper_bounds),
        constraints=LinearConstraint(matrix.tocsr(), row_lower, row_upper),
        options={"time_limit": 600.0, "mip_rel_gap": 0.0},
    )
    return result.x if result.success and result.x is not None else None


def _chordless_cycle_vertex_sets(graph: nx.Graph) -> list[tuple[Any, ...]]:
    return [tuple(cycle) for cycle in nx.chordless_cycles(graph)]


def _vertex_partition_milp(
    graph: nx.Graph,
    color_count: int,
    *,
    require_trees: bool,
) -> list[set[Any]] | None:
    nodes = list(graph)
    n = len(nodes)
    edges = list(graph.edges())
    node_index = {node: index for index, node in enumerate(nodes)}
    x_count = n * color_count
    z_count = len(edges) * color_count if require_trees else 0
    variable_count = x_count + z_count
    objective = np.zeros(variable_count)
    integrality = np.ones(variable_count, dtype=int)
    lower_bounds = np.zeros(variable_count)
    upper_bounds = np.ones(variable_count)
    rows: list[dict[int, float]] = []
    row_lower: list[float] = []
    row_upper: list[float] = []

    def add(coefficients: dict[int, float], lower: float, upper: float) -> None:
        rows.append(coefficients)
        row_lower.append(lower)
        row_upper.append(upper)

    def x(vertex: int, color: int) -> int:
        return vertex * color_count + color

    def z(edge: int, color: int) -> int:
        return x_count + edge * color_count + color

    for vertex in range(n):
        add({x(vertex, color): 1.0 for color in range(color_count)}, 1.0, 1.0)
    for color in range(color_count):
        add({x(vertex, color): 1.0 for vertex in range(n)}, 1.0, np.inf)
    for color in range(color_count - 1):
        coefficients = {x(vertex, color): 1.0 for vertex in range(n)}
        coefficients.update(
            {x(vertex, color + 1): -1.0 for vertex in range(n)}
        )
        add(coefficients, 0.0, np.inf)
    for cycle in _chordless_cycle_vertex_sets(graph):
        for color in range(color_count):
            add(
                {x(node_index[vertex], color): 1.0 for vertex in cycle},
                -np.inf,
                len(cycle) - 1,
            )
    if require_trees:
        for edge_index, (u, v) in enumerate(edges):
            iu, iv = node_index[u], node_index[v]
            for color in range(color_count):
                add({z(edge_index, color): 1.0, x(iu, color): -1.0}, -np.inf, 0.0)
                add({z(edge_index, color): 1.0, x(iv, color): -1.0}, -np.inf, 0.0)
                add(
                    {
                        z(edge_index, color): 1.0,
                        x(iu, color): -1.0,
                        x(iv, color): -1.0,
                    },
                    -1.0,
                    np.inf,
                )
        for color in range(color_count):
            coefficients = {
                z(edge_index, color): 1.0 for edge_index in range(len(edges))
            }
            coefficients.update({x(vertex, color): -1.0 for vertex in range(n)})
            add(coefficients, -1.0, -1.0)
    solution = _milp(
        objective,
        integrality,
        lower_bounds,
        upper_bounds,
        rows,
        row_lower,
        row_upper,
    )
    if solution is None:
        return None
    return [
        {nodes[vertex] for vertex in range(n) if solution[x(vertex, color)] > 0.5}
        for color in range(color_count)
    ]


def vertex_arboricity_with_witness(graph: nx.Graph) -> CertifiedValue[list[set[Any]]]:
    if graph.number_of_nodes() == 0:
        return CertifiedValue(0, [])
    if nx.is_forest(graph):
        return CertifiedValue(1, [set(graph)])
    maximum_degree = max(dict(graph.degree()).values(), default=0)
    for color_count in range(2, ceil((maximum_degree + 1) / 2) + 1):
        partition = _vertex_partition_milp(graph, color_count, require_trees=False)
        if partition is not None:
            return CertifiedValue(color_count, partition)
    raise RuntimeError("Vertex-arboricity MILP failed to attain its standard upper bound")


def vertex_arboricity(graph: nx.Graph) -> int:
    return vertex_arboricity_with_witness(graph).value


def tree_vertex_cover_number_with_witness(
    graph: nx.Graph,
) -> CertifiedValue[list[set[Any]]]:
    if graph.number_of_nodes() == 0:
        return CertifiedValue(0, [])
    if nx.is_tree(graph):
        return CertifiedValue(1, [set(graph)])
    for part_count in range(2, graph.number_of_nodes() + 1):
        partition = _vertex_partition_milp(graph, part_count, require_trees=True)
        if partition is not None:
            return CertifiedValue(part_count, partition)
    raise RuntimeError("Singleton vertices must provide an induced-tree partition")


def tree_vertex_cover_number(graph: nx.Graph) -> int:
    return tree_vertex_cover_number_with_witness(graph).value


def _star_obstructions(graph: nx.Graph) -> list[tuple[tuple[Any, Any], ...]]:
    obstructions: set[frozenset[frozenset[Any]]] = set()
    for cycle in nx.enumerate_all_cliques(graph):
        if len(cycle) == 3:
            obstructions.add(
                frozenset(frozenset(edge) for edge in combinations(cycle, 2))
            )
        elif len(cycle) > 3:
            break
    for b, c in graph.edges():
        for a in graph.neighbors(b):
            if a == c:
                continue
            for d in graph.neighbors(c):
                if d in {a, b}:
                    continue
                obstructions.add(
                    frozenset((frozenset((a, b)), frozenset((b, c)), frozenset((c, d))))
                )
    return [tuple(tuple(edge) for edge in obstruction) for obstruction in obstructions]


def _is_star_forest(graph: nx.Graph) -> bool:
    if graph.number_of_nodes() == 0:
        return True
    return nx.is_forest(graph) and all(
        sum(degree > 1 for _, degree in graph.subgraph(component).degree()) <= 1
        for component in nx.connected_components(graph)
    )


def _star_coloring_backtrack(
    graph: nx.Graph,
    color_count: int,
) -> list[list[tuple[Any, Any]]] | None:
    edges = [tuple(edge) for edge in graph.edges()]
    edge_index = {frozenset(edge): index for index, edge in enumerate(edges)}
    obstruction_masks = [
        sum(1 << edge_index[frozenset(edge)] for edge in obstruction)
        for obstruction in _star_obstructions(graph)
    ]
    by_edge: list[list[int]] = [[] for _ in edges]
    for mask in obstruction_masks:
        bits = mask
        while bits:
            bit = bits & -bits
            bits ^= bit
            by_edge[bit.bit_length() - 1].append(mask)
    order = sorted(range(len(edges)), key=lambda edge: (-len(by_edge[edge]), edge))
    color_masks = [0] * color_count
    assignments = [-1] * len(edges)

    def search(position: int, used_colors: int) -> bool:
        if position == len(order):
            return True
        edge = order[position]
        bit = 1 << edge
        for color in range(min(used_colors + 1, color_count)):
            updated = color_masks[color] | bit
            if any(updated & obstruction == obstruction for obstruction in by_edge[edge]):
                continue
            assignments[edge] = color
            previous = color_masks[color]
            color_masks[color] = updated
            if search(position + 1, max(used_colors, color + 1)):
                return True
            color_masks[color] = previous
            assignments[edge] = -1
        return False

    if not search(0, 0):
        return None
    return [
        [edge for edge, color in zip(edges, assignments, strict=True) if color == target]
        for target in range(color_count)
    ]


def star_arboricity_with_witness(
    graph: nx.Graph,
) -> CertifiedValue[list[list[tuple[Any, Any]]]]:
    edges = list(graph.edges())
    if not edges:
        return CertifiedValue(0, [])
    edge_index = {frozenset(edge): index for index, edge in enumerate(edges)}
    obstructions = _star_obstructions(graph)
    lower = max(1, ceil(graph.number_of_edges() / max(1, graph.number_of_nodes() - 1)))
    if nx.is_connected(graph) and nx.is_bipartite(graph):
        coloring = nx.bipartite.color(graph)
        left_size = sum(color == 0 for color in coloring.values())
        right_size = len(graph) - left_size
        if (
            left_size == right_size
            and left_size >= 3
            and graph.number_of_edges() == left_size * right_size
        ):
            lower = ceil(left_size / 2) + 2
    for color_count in range(lower, len(edges) + 1):
        if len(graph) <= 12:
            partition = _star_coloring_backtrack(graph, color_count)
            if partition is not None:
                return CertifiedValue(color_count, partition)
            continue
        colors = color_count
        variable_count = len(edges) * color_count
        objective = np.zeros(variable_count)
        integrality = np.ones(variable_count, dtype=int)
        rows: list[dict[int, float]] = []
        row_lower: list[float] = []
        row_upper: list[float] = []

        def x(edge: int, color: int, color_stride: int = colors) -> int:
            return edge * color_stride + color

        for edge in range(len(edges)):
            rows.append({x(edge, color): 1.0 for color in range(color_count)})
            row_lower.append(1.0)
            row_upper.append(1.0)
        for color in range(color_count - 1):
            coefficients = {x(edge, color): 1.0 for edge in range(len(edges))}
            coefficients.update(
                {x(edge, color + 1): -1.0 for edge in range(len(edges))}
            )
            rows.append(coefficients)
            row_lower.append(0.0)
            row_upper.append(np.inf)
        for obstruction in obstructions:
            indices = [edge_index[frozenset(edge)] for edge in obstruction]
            for color in range(color_count):
                rows.append({x(edge, color): 1.0 for edge in indices})
                row_lower.append(-np.inf)
                row_upper.append(len(indices) - 1)
        solution = _milp(
            objective,
            integrality,
            np.zeros(variable_count),
            np.ones(variable_count),
            rows,
            row_lower,
            row_upper,
        )
        if solution is not None:
            partition = [
                [edges[edge] for edge in range(len(edges)) if solution[x(edge, color)] > 0.5]
                for color in range(color_count)
            ]
            return CertifiedValue(color_count, partition)
    raise RuntimeError("Individual edges must provide a star-forest partition")


def star_arboricity(graph: nx.Graph) -> int:
    return star_arboricity_with_witness(graph).value


def _tree_edge_partition_milp(
    graph: nx.Graph,
    part_count: int,
) -> list[list[tuple[Any, Any]]] | None:
    nodes = list(graph)
    edges = [tuple(edge) for edge in graph.edges()]
    n, m = len(nodes), len(edges)
    node_index = {node: index for index, node in enumerate(nodes)}
    directed = [(u, v) for u, v in edges for u, v in ((u, v), (v, u))]
    x_offset = 0
    y_offset = m * part_count
    r_offset = y_offset + n * part_count
    f_offset = r_offset + n * part_count
    q_offset = f_offset + len(directed) * part_count
    variable_count = q_offset + n * part_count
    objective = np.zeros(variable_count)
    integrality = np.zeros(variable_count, dtype=int)
    integrality[:f_offset] = 1
    lower_bounds = np.zeros(variable_count)
    upper_bounds = np.ones(variable_count)
    upper_bounds[f_offset:] = n
    rows: list[dict[int, float]] = []
    row_lower: list[float] = []
    row_upper: list[float] = []

    def add(coefficients: dict[int, float], lower: float, upper: float) -> None:
        rows.append(coefficients)
        row_lower.append(lower)
        row_upper.append(upper)

    def x(edge: int, part: int) -> int:
        return x_offset + edge * part_count + part

    def y(vertex: int, part: int) -> int:
        return y_offset + vertex * part_count + part

    def root(vertex: int, part: int) -> int:
        return r_offset + vertex * part_count + part

    def flow(arc: int, part: int) -> int:
        return f_offset + arc * part_count + part

    def source(vertex: int, part: int) -> int:
        return q_offset + vertex * part_count + part

    incident_edges: list[list[int]] = [[] for _ in nodes]
    incoming_arcs: list[list[int]] = [[] for _ in nodes]
    outgoing_arcs: list[list[int]] = [[] for _ in nodes]
    for edge_index, (u, v) in enumerate(edges):
        incident_edges[node_index[u]].append(edge_index)
        incident_edges[node_index[v]].append(edge_index)
    for arc_index, (u, v) in enumerate(directed):
        outgoing_arcs[node_index[u]].append(arc_index)
        incoming_arcs[node_index[v]].append(arc_index)

    for edge_index in range(m):
        add({x(edge_index, part): 1.0 for part in range(part_count)}, 1.0, 1.0)
    add({x(0, 0): 1.0}, 1.0, 1.0)
    for part in range(part_count):
        add({root(vertex, part): 1.0 for vertex in range(n)}, 1.0, 1.0)
        for vertex in range(n):
            add({root(vertex, part): 1.0, y(vertex, part): -1.0}, -np.inf, 0.0)
            for earlier in range(vertex):
                add(
                    {
                        root(vertex, part): 1.0,
                        y(earlier, part): 1.0,
                    },
                    -np.inf,
                    1.0,
                )
            root_lower = {
                root(vertex, part): 1.0,
                y(vertex, part): -1.0,
            }
            root_lower.update(
                {y(earlier, part): 1.0 for earlier in range(vertex)}
            )
            add(root_lower, 0.0, np.inf)
            coefficients = {y(vertex, part): 1.0}
            coefficients.update({x(edge, part): -1.0 for edge in incident_edges[vertex]})
            add(coefficients, -np.inf, 0.0)
            add(
                {source(vertex, part): 1.0, root(vertex, part): -float(n)},
                -np.inf,
                0.0,
            )
            conservation = {
                source(vertex, part): 1.0,
                y(vertex, part): -1.0,
            }
            conservation.update(
                {flow(arc, part): 1.0 for arc in incoming_arcs[vertex]}
            )
            conservation.update(
                {flow(arc, part): -1.0 for arc in outgoing_arcs[vertex]}
            )
            add(conservation, 0.0, 0.0)
        for edge_index, (u, v) in enumerate(edges):
            for vertex in (node_index[u], node_index[v]):
                add({x(edge_index, part): 1.0, y(vertex, part): -1.0}, -np.inf, 0.0)
        for arc_index in range(len(directed)):
            edge_index = arc_index // 2
            add(
                {flow(arc_index, part): 1.0, x(edge_index, part): -float(n)},
                -np.inf,
                0.0,
            )
        tree_equation = {x(edge, part): 1.0 for edge in range(m)}
        tree_equation.update({y(vertex, part): -1.0 for vertex in range(n)})
        add(tree_equation, -1.0, -1.0)
    solution = _milp(
        objective,
        integrality,
        lower_bounds,
        upper_bounds,
        rows,
        row_lower,
        row_upper,
    )
    if solution is None:
        return None
    return [
        [edges[edge] for edge in range(m) if solution[x(edge, part)] > 0.5]
        for part in range(part_count)
    ]


def _tree_edge_coloring_backtrack(
    graph: nx.Graph,
    part_count: int,
) -> list[list[tuple[Any, Any]]] | None:
    edges = sorted(
        (tuple(edge) for edge in graph.edges()),
        key=lambda edge: (-(graph.degree(edge[0]) + graph.degree(edge[1])), repr(edge)),
    )
    parts: list[list[tuple[Any, Any]]] = [[] for _ in range(part_count)]
    part_graphs = [nx.Graph() for _ in range(part_count)]

    def search(position: int, used_parts: int) -> bool:
        if position == len(edges):
            return used_parts == part_count and all(nx.is_tree(part) for part in part_graphs)
        if len(edges) - position < part_count - used_parts:
            return False
        u, v = edges[position]
        for part in range(min(used_parts + 1, part_count)):
            working = part_graphs[part]
            if u in working and v in working and nx.has_path(working, u, v):
                continue
            parts[part].append((u, v))
            working.add_edge(u, v)
            if search(position + 1, max(used_parts, part + 1)):
                return True
            parts[part].pop()
            working.remove_edge(u, v)
            for vertex in (u, v):
                if vertex in working and working.degree(vertex) == 0:
                    working.remove_node(vertex)
        return False

    return parts if search(0, 0) else None


def tree_edge_cover_number_with_witness(
    graph: nx.Graph,
) -> CertifiedValue[list[list[tuple[Any, Any]]]]:
    if graph.number_of_edges() == 0:
        return CertifiedValue(0, [])
    if nx.is_tree(graph):
        return CertifiedValue(1, [list(graph.edges())])
    lower = max(
        1,
        ceil(
            graph.number_of_edges()
            / max(1, graph.number_of_nodes() - nx.number_connected_components(graph))
        ),
    )
    for part_count in range(lower, graph.number_of_edges() + 1):
        use_backtracking = (
            len(graph) <= 9 and graph.number_of_edges() <= 17
        ) or (len(graph) <= 12 and graph.number_of_edges() <= 18)
        partition = (
            _tree_edge_coloring_backtrack(graph, part_count)
            if use_backtracking
            else _tree_edge_partition_milp(graph, part_count)
        )
        if partition is not None:
            return CertifiedValue(part_count, partition)
    raise RuntimeError("Individual edges must provide a tree-edge partition")


def tree_edge_cover_number(graph: nx.Graph) -> int:
    return tree_edge_cover_number_with_witness(graph).value


def triangle_edge_cover_number_with_witness(
    graph: nx.Graph,
) -> CertifiedValue[set[tuple[Any, Any]]]:
    edges = [tuple(edge) for edge in graph.edges()]
    edge_index = {frozenset(edge): index for index, edge in enumerate(edges)}
    triangles = [clique for clique in nx.enumerate_all_cliques(graph) if len(clique) == 3]
    if not triangles:
        return CertifiedValue(0, set())
    variable_count = len(edges)
    rows = [
        {edge_index[frozenset(edge)]: 1.0 for edge in combinations(triangle, 2)}
        for triangle in triangles
    ]
    solution = _milp(
        np.ones(variable_count),
        np.ones(variable_count, dtype=int),
        np.zeros(variable_count),
        np.ones(variable_count),
        rows,
        [1.0] * len(rows),
        [np.inf] * len(rows),
    )
    if solution is None:
        raise RuntimeError("Triangle edge-cover MILP failed")
    witness = {edges[index] for index, selected in enumerate(solution) if selected > 0.5}
    return CertifiedValue(len(witness), witness)


def triangle_edge_cover_number(graph: nx.Graph) -> int:
    return triangle_edge_cover_number_with_witness(graph).value


def triangle_edge_packing_number_with_witness(
    graph: nx.Graph,
) -> CertifiedValue[list[tuple[Any, Any, Any]]]:
    edges = [frozenset(edge) for edge in graph.edges()]
    triangles = [
        tuple(clique) for clique in nx.enumerate_all_cliques(graph) if len(clique) == 3
    ]
    if not triangles:
        return CertifiedValue(0, [])
    rows: list[dict[int, float]] = []
    for edge in edges:
        rows.append(
            {
                index: 1.0
                for index, triangle in enumerate(triangles)
                if edge.issubset(triangle)
            }
        )
    solution = _milp(
        -np.ones(len(triangles)),
        np.ones(len(triangles), dtype=int),
        np.zeros(len(triangles)),
        np.ones(len(triangles)),
        rows,
        [-np.inf] * len(rows),
        [1.0] * len(rows),
    )
    if solution is None:
        raise RuntimeError("Triangle edge-packing MILP failed")
    witness = [triangle for triangle, selected in zip(triangles, solution, strict=True) if selected > 0.5]
    return CertifiedValue(len(witness), witness)


def triangle_edge_packing_number(graph: nx.Graph) -> int:
    return triangle_edge_packing_number_with_witness(graph).value


def _square_graph(graph: nx.Graph) -> nx.Graph:
    square = nx.Graph()
    square.add_nodes_from(graph)
    for vertex in graph:
        distance = nx.single_source_shortest_path_length(graph, vertex, cutoff=2)
        square.add_edges_from((vertex, other) for other in distance if other != vertex)
    return square


def _independent_set_milp(
    graph: nx.Graph,
    *,
    minimize_maximal: bool,
) -> CertifiedValue[set[Any]]:
    nodes = list(graph)
    if not nodes:
        return CertifiedValue(0, set())
    index = {node: position for position, node in enumerate(nodes)}
    rows: list[dict[int, float]] = []
    row_lower: list[float] = []
    row_upper: list[float] = []
    for u, v in graph.edges():
        rows.append({index[u]: 1.0, index[v]: 1.0})
        row_lower.append(-np.inf)
        row_upper.append(1.0)
    if minimize_maximal:
        for vertex in nodes:
            rows.append(
                {
                    index[item]: 1.0
                    for item in (vertex, *graph.neighbors(vertex))
                }
            )
            row_lower.append(1.0)
            row_upper.append(np.inf)
    solution = _milp(
        np.ones(len(nodes)) if minimize_maximal else -np.ones(len(nodes)),
        np.ones(len(nodes), dtype=int),
        np.zeros(len(nodes)),
        np.ones(len(nodes)),
        rows,
        row_lower,
        row_upper,
    )
    if solution is None:
        raise RuntimeError("Independent-set MILP failed")
    witness = {nodes[position] for position, selected in enumerate(solution) if selected > 0.5}
    return CertifiedValue(len(witness), witness)


def lower_2_packing_number_with_witness(graph: nx.Graph) -> CertifiedValue[set[Any]]:
    return _independent_set_milp(_square_graph(graph), minimize_maximal=True)


def lower_2_packing_number(graph: nx.Graph) -> int:
    return lower_2_packing_number_with_witness(graph).value


def upper_2_packing_number_with_witness(graph: nx.Graph) -> CertifiedValue[set[Any]]:
    return _independent_set_milp(_square_graph(graph), minimize_maximal=False)


def upper_2_packing_number(graph: nx.Graph) -> int:
    return upper_2_packing_number_with_witness(graph).value


def _matching_milp(
    graph: nx.Graph,
    *,
    kind: str,
) -> CertifiedValue[set[tuple[Any, Any]]]:
    nodes = list(graph)
    edges = [tuple(edge) for edge in graph.edges()]
    if not edges:
        return CertifiedValue(0, set())
    incident = {
        vertex: [index for index, edge in enumerate(edges) if vertex in edge]
        for vertex in nodes
    }
    rows: list[dict[int, float]] = []
    row_lower: list[float] = []
    row_upper: list[float] = []
    for edge_indices in incident.values():
        rows.append(dict.fromkeys(edge_indices, 1.0))
        row_lower.append(-np.inf)
        row_upper.append(1.0)
    if kind == "lower":
        for u, v in edges:
            adjacent = set(incident[u]) | set(incident[v])
            rows.append(dict.fromkeys(adjacent, 1.0))
            row_lower.append(1.0)
            row_upper.append(np.inf)
    elif kind == "induced":
        for first, second in combinations(range(len(edges)), 2):
            endpoints = {*edges[first], *edges[second]}
            if len(endpoints) < 4 or any(
                graph.has_edge(u, v)
                for u in edges[first]
                for v in edges[second]
            ):
                rows.append({first: 1.0, second: 1.0})
                row_lower.append(-np.inf)
                row_upper.append(1.0)
    elif kind == "acyclic":
        for cycle in _chordless_cycle_vertex_sets(graph):
            coefficients: dict[int, float] = {}
            cycle_set = set(cycle)
            for edge_index, edge in enumerate(edges):
                coefficient = sum(vertex in cycle_set for vertex in edge)
                if coefficient:
                    coefficients[edge_index] = float(coefficient)
            rows.append(coefficients)
            row_lower.append(-np.inf)
            row_upper.append(len(cycle) - 1)
    objective = np.ones(len(edges)) if kind == "lower" else -np.ones(len(edges))
    solution = _milp(
        objective,
        np.ones(len(edges), dtype=int),
        np.zeros(len(edges)),
        np.ones(len(edges)),
        rows,
        row_lower,
        row_upper,
    )
    if solution is None:
        raise RuntimeError(f"{kind} matching MILP failed")
    witness = {edges[index] for index, selected in enumerate(solution) if selected > 0.5}
    return CertifiedValue(len(witness), witness)


def _all_matchings(graph: nx.Graph) -> list[set[tuple[Any, Any]]]:
    nodes = list(graph)
    index = {node: position for position, node in enumerate(nodes)}
    adjacency = [
        sum(1 << index[neighbor] for neighbor in graph.neighbors(node))
        for node in nodes
    ]

    @cache
    def enumerate_masks(available: int) -> tuple[tuple[tuple[int, int], ...], ...]:
        if not available:
            return ((),)
        bit = available & -available
        vertex = bit.bit_length() - 1
        remainder = available ^ bit
        output = list(enumerate_masks(remainder))
        neighbors = adjacency[vertex] & remainder
        while neighbors:
            neighbor_bit = neighbors & -neighbors
            neighbors ^= neighbor_bit
            neighbor = neighbor_bit.bit_length() - 1
            output.extend(
                ((vertex, neighbor), *matching)
                for matching in enumerate_masks(remainder ^ neighbor_bit)
            )
        return tuple(output)

    return [
        {(nodes[u], nodes[v]) for u, v in matching}
        for matching in enumerate_masks((1 << len(nodes)) - 1)
    ]


def small_matching_extrema(
    graph: nx.Graph,
) -> dict[str, CertifiedValue[set[tuple[Any, Any]]]]:
    matchings = _all_matchings(graph)
    lower_value = graph.number_of_edges() + 1
    witnesses: dict[str, set[tuple[Any, Any]]] = {
        "lower": set(),
        "induced": set(),
        "acyclic": set(),
        "uniquely_restricted": set(),
    }
    for matching in matchings:
        endpoints = {vertex for edge in matching for vertex in edge}
        unmatched = set(graph) - endpoints
        if (
            not any(u in unmatched and v in unmatched for u, v in graph.edges())
            and len(matching) < lower_value
        ):
            lower_value = len(matching)
            witnesses["lower"] = matching
        induced = graph.subgraph(endpoints)
        if induced.number_of_edges() == len(matching) and len(matching) > len(witnesses["induced"]):
            witnesses["induced"] = matching
        if (not matching or nx.is_forest(induced)) and len(matching) > len(witnesses["acyclic"]):
            witnesses["acyclic"] = matching
        if (
            len(matching) > len(witnesses["uniquely_restricted"])
            and perfect_matching_count(induced) == 1
        ):
            witnesses["uniquely_restricted"] = matching
    if lower_value == graph.number_of_edges() + 1:
        lower_value = 0
    return {
        "lower": CertifiedValue(lower_value, witnesses["lower"]),
        "induced": CertifiedValue(len(witnesses["induced"]), witnesses["induced"]),
        "acyclic": CertifiedValue(len(witnesses["acyclic"]), witnesses["acyclic"]),
        "uniquely_restricted": CertifiedValue(
            len(witnesses["uniquely_restricted"]),
            witnesses["uniquely_restricted"],
        ),
    }


def lower_matching_number_with_witness(graph: nx.Graph) -> CertifiedValue[set[tuple[Any, Any]]]:
    n = len(graph)
    if graph.number_of_edges() == n * (n - 1) // 2:
        matching = set(nx.max_weight_matching(graph, maxcardinality=True))
        return CertifiedValue(len(matching), matching)
    bipartition = _complete_bipartition(graph)
    if bipartition is not None:
        matching = set(nx.max_weight_matching(graph, maxcardinality=True))
        return CertifiedValue(min(map(len, bipartition)), matching)
    if len(graph) <= 12:
        return small_matching_extrema(graph)["lower"]
    return _matching_milp(graph, kind="lower")


def lower_matching_number(graph: nx.Graph) -> int:
    return lower_matching_number_with_witness(graph).value


def induced_matching_number_with_witness(graph: nx.Graph) -> CertifiedValue[set[tuple[Any, Any]]]:
    n = len(graph)
    bipartition = _complete_bipartition(graph)
    if graph.number_of_edges() == n * (n - 1) // 2 or (
        bipartition is not None and min(map(len, bipartition)) >= 2
    ):
        edge = next(iter(graph.edges()), None)
        return CertifiedValue(int(edge is not None), {edge} if edge is not None else set())
    if len(graph) <= 12:
        return small_matching_extrema(graph)["induced"]
    return _matching_milp(graph, kind="induced")


def induced_matching_number(graph: nx.Graph) -> int:
    return induced_matching_number_with_witness(graph).value


def acyclic_matching_number_with_witness(graph: nx.Graph) -> CertifiedValue[set[tuple[Any, Any]]]:
    n = len(graph)
    bipartition = _complete_bipartition(graph)
    if graph.number_of_edges() == n * (n - 1) // 2 or (
        bipartition is not None and min(map(len, bipartition)) >= 2
    ):
        edge = next(iter(graph.edges()), None)
        return CertifiedValue(int(edge is not None), {edge} if edge is not None else set())
    if len(graph) <= 12:
        return small_matching_extrema(graph)["acyclic"]
    return _matching_milp(graph, kind="acyclic")


def acyclic_matching_number(graph: nx.Graph) -> int:
    return acyclic_matching_number_with_witness(graph).value


def uniquely_restricted_matching_number_with_witness(
    graph: nx.Graph,
) -> CertifiedValue[set[tuple[Any, Any]]]:
    n = len(graph)
    bipartition = _complete_bipartition(graph)
    if graph.number_of_edges() == n * (n - 1) // 2 or (
        bipartition is not None and min(map(len, bipartition)) >= 2
    ):
        edge = next(iter(graph.edges()), None)
        return CertifiedValue(int(edge is not None), {edge} if edge is not None else set())
    if len(graph) <= 12:
        return small_matching_extrema(graph)["uniquely_restricted"]
    edges = [tuple(edge) for edge in graph.edges()]
    if not edges:
        return CertifiedValue(0, set())
    forbidden: set[frozenset[int]] = set()
    while True:
        nodes = list(graph)
        incident = {
            vertex: [index for index, edge in enumerate(edges) if vertex in edge]
            for vertex in nodes
        }
        rows = [
            dict.fromkeys(edge_indices, 1.0) for edge_indices in incident.values()
        ]
        row_lower = [-np.inf] * len(rows)
        row_upper = [1.0] * len(rows)
        for edge_set in forbidden:
            rows.append(dict.fromkeys(edge_set, 1.0))
            row_lower.append(-np.inf)
            row_upper.append(len(edge_set) - 1)
        solution = _milp(
            -np.ones(len(edges)),
            np.ones(len(edges), dtype=int),
            np.zeros(len(edges)),
            np.ones(len(edges)),
            rows,
            row_lower,
            row_upper,
        )
        if solution is None:
            raise RuntimeError("Uniquely restricted matching MILP failed")
        selected_indices = {index for index, value in enumerate(solution) if value > 0.5}
        matching = {edges[index] for index in selected_indices}
        endpoints = {vertex for edge in matching for vertex in edge}
        induced = graph.subgraph(endpoints).copy()
        new_cuts: set[frozenset[int]] = set()
        for edge in matching:
            alternative = induced.copy()
            alternative.remove_edge(*edge)
            candidate = nx.algorithms.matching.max_weight_matching(
                alternative, maxcardinality=True
            )
            if len(candidate) == len(matching):
                union = nx.Graph()
                union.add_edges_from(matching)
                union.add_edges_from(candidate)
                for component in nx.connected_components(union):
                    if len(component) < 4:
                        continue
                    cycle_matching_indices = frozenset(
                        index
                        for index in selected_indices
                        if set(edges[index]).issubset(component)
                    )
                    if cycle_matching_indices:
                        new_cuts.add(cycle_matching_indices)
        if not new_cuts:
            return CertifiedValue(len(matching), matching)
        previous_count = len(forbidden)
        forbidden.update(new_cuts)
        if len(forbidden) == previous_count:
            raise RuntimeError("Alternating-cycle separation made no progress")


def uniquely_restricted_matching_number(graph: nx.Graph) -> int:
    return uniquely_restricted_matching_number_with_witness(graph).value


def _complete_graph_matching_counts(n: int) -> tuple[int, ...]:
    return tuple(
        factorial(n) // (factorial(n - 2 * size) * (2**size) * factorial(size))
        for size in range(n // 2 + 1)
    )


def _complete_bipartition(graph: nx.Graph) -> tuple[set[Any], set[Any]] | None:
    if not graph or not nx.is_connected(graph) or not nx.is_bipartite(graph):
        return None
    coloring = nx.bipartite.color(graph)
    left = {vertex for vertex, color in coloring.items() if color == 0}
    right = set(graph) - left
    return (left, right) if graph.number_of_edges() == len(left) * len(right) else None


def matching_size_counts(graph: nx.Graph) -> tuple[int, ...]:
    nodes = list(graph)
    n = len(nodes)
    if graph.number_of_edges() == n * (n - 1) // 2:
        return _complete_graph_matching_counts(n)
    bipartition = _complete_bipartition(graph)
    if bipartition is not None:
        left, right = map(len, bipartition)
        return tuple(
            comb(left, size) * comb(right, size) * factorial(size)
            for size in range(min(left, right) + 1)
        )
    index = {node: position for position, node in enumerate(nodes)}
    adjacency = [
        sum(1 << index[neighbor] for neighbor in graph.neighbors(node)) for node in nodes
    ]

    @cache
    def counts(mask: int) -> tuple[int, ...]:
        if mask == 0:
            return (1,)
        bit = mask & -mask
        vertex = bit.bit_length() - 1
        without_vertex = mask ^ bit
        result = list(counts(without_vertex))
        neighbors = adjacency[vertex] & without_vertex
        while neighbors:
            neighbor_bit = neighbors & -neighbors
            neighbors ^= neighbor_bit
            subcounts = counts(without_vertex ^ neighbor_bit)
            if len(result) < len(subcounts) + 1:
                result.extend([0] * (len(subcounts) + 1 - len(result)))
            for size, value in enumerate(subcounts):
                result[size + 1] += value
        return tuple(result)

    return counts((1 << n) - 1)


def hosoya_index(graph: nx.Graph) -> int:
    return sum(matching_size_counts(graph))


def perfect_matching_count(graph: nx.Graph) -> int:
    if graph.number_of_nodes() % 2:
        return 0
    counts = matching_size_counts(graph)
    size = graph.number_of_nodes() // 2
    return counts[size] if size < len(counts) else 0


def has_unique_perfect_matching(graph: nx.Graph) -> bool:
    return perfect_matching_count(graph) == 1

from __future__ import annotations

import os
from array import array
from functools import cache, lru_cache
from itertools import combinations, combinations_with_replacement, product
from math import comb
from typing import Literal

import networkx as nx

DENSE_GAME_STATE_LIMIT = 25_000_000
GameKind = Literal[
    "domination",
    "total_domination",
    "isolation",
    "total_isolation",
    "connected_domination",
    "independent_domination",
]


def _game_state_limit_from_env() -> int:
    raw = os.environ.get("GRAPHS_GAME_STATE_LIMIT", "20000000").strip()
    if not raw or raw.lower() in {"0", "none", "off"}:
        return 0
    return max(1, int(raw))


def _adjacency_masks(G: nx.Graph) -> tuple[list[int], int]:
    nodes = list(G.nodes())
    node_index = {node: index for index, node in enumerate(nodes)}
    adjacency = [0] * len(nodes)
    for node in nodes:
        index = node_index[node]
        for neighbor in G.neighbors(node):
            adjacency[index] |= 1 << node_index[neighbor]
    return adjacency, (1 << len(nodes)) - 1


def _closed_neighborhood_masks(adjacency: list[int]) -> list[int]:
    return [neighbor_mask | (1 << index) for index, neighbor_mask in enumerate(adjacency)]


def _bit_indices(mask: int) -> list[int]:
    indices: list[int] = []
    while mask:
        bit = mask & -mask
        indices.append(bit.bit_length() - 1)
        mask -= bit
    return indices


def _open_neighborhood_of_mask(mask: int, adjacency: list[int]) -> int:
    neighbors = 0
    while mask:
        bit = mask & -mask
        neighbors |= adjacency[bit.bit_length() - 1]
        mask -= bit
    return neighbors


def _nontrivial_residual_mask(residual_mask: int, *, adjacency: list[int]) -> int:
    nontrivial = 0
    candidates = residual_mask
    while candidates:
        bit = candidates & -candidates
        index = bit.bit_length() - 1
        if adjacency[index] & residual_mask:
            nontrivial |= bit
        candidates -= bit
    return nontrivial


def _total_isolation_unmarked_mask(
    selected_mask: int,
    *,
    open_neighborhood: int,
    adjacency: list[int],
    all_mask: int,
) -> int:
    residual = all_mask & ~open_neighborhood
    isolated_unselected = 0
    candidates = residual & ~selected_mask
    while candidates:
        bit = candidates & -candidates
        index = bit.bit_length() - 1
        if (adjacency[index] & residual) == 0:
            isolated_unselected |= bit
        candidates -= bit

    return all_mask & ~(open_neighborhood | isolated_unselected)


def _game_legal_moves(
    kind: GameKind,
    selected_mask: int,
    covered_mask: int,
    *,
    adjacency: list[int],
    closed_neighborhood: list[int],
    all_mask: int,
) -> list[int]:
    if kind in {"domination", "connected_domination", "independent_domination"}:
        target_mask = all_mask & ~covered_mask
        move_neighborhoods = closed_neighborhood
    elif kind == "total_domination":
        target_mask = all_mask & ~covered_mask
        move_neighborhoods = adjacency
    elif kind == "isolation":
        residual = all_mask & ~covered_mask
        target_mask = _nontrivial_residual_mask(residual, adjacency=adjacency)
        move_neighborhoods = closed_neighborhood
    else:
        target_mask = _total_isolation_unmarked_mask(
            selected_mask,
            open_neighborhood=covered_mask,
            adjacency=adjacency,
            all_mask=all_mask,
        )
        move_neighborhoods = adjacency

    if target_mask == 0:
        return []

    candidates = all_mask & ~selected_mask
    if kind == "connected_domination" and selected_mask:
        candidates &= _open_neighborhood_of_mask(selected_mask, adjacency)
    elif kind == "independent_domination":
        candidates &= all_mask & ~(selected_mask | _open_neighborhood_of_mask(selected_mask, adjacency))

    legal_moves: list[int] = []
    while candidates:
        bit = candidates & -candidates
        index = bit.bit_length() - 1
        if move_neighborhoods[index] & target_mask:
            legal_moves.append(index)
        candidates -= bit
    return legal_moves


def _coverage_game_legal_moves(
    kind: GameKind,
    covered_mask: int,
    *,
    adjacency: list[int],
    closed_neighborhood: list[int],
    all_mask: int,
) -> list[int]:
    if kind == "domination":
        target_mask = all_mask & ~covered_mask
        move_neighborhoods = closed_neighborhood
    elif kind == "total_domination":
        target_mask = all_mask & ~covered_mask
        move_neighborhoods = adjacency
    elif kind == "isolation":
        residual = all_mask & ~covered_mask
        target_mask = _nontrivial_residual_mask(residual, adjacency=adjacency)
        move_neighborhoods = closed_neighborhood
    else:
        raise ValueError(f"{kind} is not a coverage-only game")

    if target_mask == 0:
        return []

    legal_moves: list[int] = []
    candidates = all_mask
    while candidates:
        bit = candidates & -candidates
        index = bit.bit_length() - 1
        if move_neighborhoods[index] & target_mask:
            legal_moves.append(index)
        candidates -= bit
    return legal_moves


@lru_cache(maxsize=4096)
def _coverage_game_number_from_adjacency(
    kind: GameKind,
    adjacency_tuple: tuple[int, ...],
    state_limit: int,
    dominator_starts: bool,
) -> int:
    adjacency = list(adjacency_tuple)
    if kind == "total_domination" and any(mask == 0 for mask in adjacency):
        raise ValueError("the total domination game is undefined for graphs with isolated vertices")

    n = len(adjacency)
    all_mask = (1 << n) - 1
    closed_neighborhood = _closed_neighborhood_masks(adjacency)
    cover_neighborhood = adjacency if kind == "total_domination" else closed_neighborhood
    state_space_size = 1 << n

    use_dense_memo = state_space_size <= DENSE_GAME_STATE_LIMIT and (
        state_limit == 0 or state_space_size <= state_limit
    )
    if use_dense_memo:
        dominator_turn_memo = array("h", [-1]) * state_space_size
        staller_turn_memo = array("h", [-1]) * state_space_size

        def solve_dense(covered_mask: int, dominator_turn: bool) -> int:
            memo = dominator_turn_memo if dominator_turn else staller_turn_memo
            cached = memo[covered_mask]
            if cached >= 0:
                return int(cached)

            legal_moves = _coverage_game_legal_moves(
                kind,
                covered_mask,
                adjacency=adjacency,
                closed_neighborhood=closed_neighborhood,
                all_mask=all_mask,
            )
            if not legal_moves:
                value = 0
            else:
                best = solve_dense(
                    covered_mask | cover_neighborhood[legal_moves[0]],
                    not dominator_turn,
                )
                for move in legal_moves[1:]:
                    next_value = solve_dense(
                        covered_mask | cover_neighborhood[move],
                        not dominator_turn,
                    )
                    best = min(best, next_value) if dominator_turn else max(best, next_value)
                value = 1 + best

            memo[covered_mask] = value
            return value

        return solve_dense(0, dominator_starts)

    sparse_dominator_turn_memo: dict[int, int] = {}
    sparse_staller_turn_memo: dict[int, int] = {}

    def solve_sparse(covered_mask: int, dominator_turn: bool) -> int:
        memo = sparse_dominator_turn_memo if dominator_turn else sparse_staller_turn_memo
        cached = memo.get(covered_mask)
        if cached is not None:
            return cached
        if state_limit != 0 and len(sparse_dominator_turn_memo) + len(sparse_staller_turn_memo) >= state_limit:
            raise RuntimeError(f"{kind} game state limit exceeded ({state_limit})")

        legal_moves = _coverage_game_legal_moves(
            kind,
            covered_mask,
            adjacency=adjacency,
            closed_neighborhood=closed_neighborhood,
            all_mask=all_mask,
        )
        if not legal_moves:
            value = 0
        else:
            best = solve_sparse(
                covered_mask | cover_neighborhood[legal_moves[0]],
                not dominator_turn,
            )
            for move in legal_moves[1:]:
                next_value = solve_sparse(
                    covered_mask | cover_neighborhood[move],
                    not dominator_turn,
                )
                best = min(best, next_value) if dominator_turn else max(best, next_value)
            value = 1 + best

        memo[covered_mask] = value
        return value

    return solve_sparse(0, dominator_starts)


@lru_cache(maxsize=4096)
def _selected_game_number_from_adjacency(
    kind: GameKind,
    adjacency_tuple: tuple[int, ...],
    state_limit: int,
    dominator_starts: bool,
) -> int:
    adjacency = list(adjacency_tuple)
    n = len(adjacency)
    all_mask = (1 << n) - 1
    closed_neighborhood = _closed_neighborhood_masks(adjacency)
    cover_neighborhood = adjacency if kind in {"total_domination", "total_isolation"} else closed_neighborhood
    state_space_size = 1 << n

    use_dense_memo = state_space_size <= DENSE_GAME_STATE_LIMIT and (
        state_limit == 0 or state_space_size <= state_limit
    )
    if use_dense_memo:
        dense_memo = array("h", [-1]) * state_space_size

        def solve_dense(selected_mask: int, covered_mask: int) -> int:
            cached = dense_memo[selected_mask]
            if cached >= 0:
                return int(cached)

            legal_moves = _game_legal_moves(
                kind,
                selected_mask,
                covered_mask,
                adjacency=adjacency,
                closed_neighborhood=closed_neighborhood,
                all_mask=all_mask,
            )
            if not legal_moves:
                value = 0
            else:
                dominator_turn = (selected_mask.bit_count() % 2 == 0) == dominator_starts
                best = solve_dense(
                    selected_mask | (1 << legal_moves[0]),
                    covered_mask | cover_neighborhood[legal_moves[0]],
                )
                for move in legal_moves[1:]:
                    next_value = solve_dense(
                        selected_mask | (1 << move),
                        covered_mask | cover_neighborhood[move],
                    )
                    best = min(best, next_value) if dominator_turn else max(best, next_value)
                value = 1 + best

            dense_memo[selected_mask] = value
            return value

        return solve_dense(0, 0)

    sparse_memo: dict[int, int] = {}

    def solve_sparse(selected_mask: int, covered_mask: int) -> int:
        cached = sparse_memo.get(selected_mask)
        if cached is not None:
            return cached
        if state_limit != 0 and len(sparse_memo) >= state_limit:
            raise RuntimeError(f"{kind} game state limit exceeded ({state_limit})")

        legal_moves = _game_legal_moves(
            kind,
            selected_mask,
            covered_mask,
            adjacency=adjacency,
            closed_neighborhood=closed_neighborhood,
            all_mask=all_mask,
        )
        if not legal_moves:
            value = 0
        else:
            dominator_turn = (selected_mask.bit_count() % 2 == 0) == dominator_starts
            best = solve_sparse(
                selected_mask | (1 << legal_moves[0]),
                covered_mask | cover_neighborhood[legal_moves[0]],
            )
            for move in legal_moves[1:]:
                next_value = solve_sparse(
                    selected_mask | (1 << move),
                    covered_mask | cover_neighborhood[move],
                )
                best = min(best, next_value) if dominator_turn else max(best, next_value)
            value = 1 + best

        sparse_memo[selected_mask] = value
        return value

    return solve_sparse(0, 0)


def _game_number(G: nx.Graph, *, kind: GameKind, dominator_starts: bool) -> int:
    graph = nx.Graph(G)
    if kind == "connected_domination" and graph.number_of_nodes() > 0 and not nx.is_connected(graph):
        raise ValueError("the connected domination game is infeasible for disconnected graphs")

    adjacency, _ = _adjacency_masks(graph)
    state_limit = _game_state_limit_from_env()
    solver = (
        _selected_game_number_from_adjacency
        if kind in {"total_isolation", "connected_domination", "independent_domination"}
        else _coverage_game_number_from_adjacency
    )
    return solver(
        kind,
        tuple(adjacency),
        state_limit,
        dominator_starts,
    )


def _star_leaf_count(graph: nx.Graph) -> int | None:
    order = graph.number_of_nodes()
    if order < 3 or graph.number_of_edges() != order - 1 or not nx.is_connected(graph):
        return None
    degrees = sorted(dict(graph.degree()).values())
    return order - 1 if degrees == [1] * (order - 1) + [order - 1] else None


@lru_cache(maxsize=128)
def _pursuit_position_tuples(n: int, k: int) -> tuple[tuple[int, ...], ...]:
    return tuple(combinations_with_replacement(range(n), k))


def _pursuit_state_count(n: int, k: int) -> int:
    return 2 * n * comb(n + k - 1, k)


def _positions_mask(positions: tuple[int, ...]) -> int:
    mask = 0
    for vertex in positions:
        mask |= 1 << vertex
    return mask


def _check_pursuit_state_limit(n: int, k: int, game_name: str) -> None:
    state_limit = _game_state_limit_from_env()
    state_count = _pursuit_state_count(n, k)
    if state_limit != 0 and state_count > state_limit:
        raise RuntimeError(f"{game_name} state limit exceeded ({state_count} states > {state_limit})")


def _is_complete_graph(adjacency: list[int]) -> bool:
    n = len(adjacency)
    return n > 0 and all(mask.bit_count() == n - 1 for mask in adjacency)


def _is_tree_graph(adjacency: list[int]) -> bool:
    n = len(adjacency)
    return n > 0 and sum(mask.bit_count() for mask in adjacency) // 2 == n - 1


def _is_cycle_graph(adjacency: list[int]) -> bool:
    n = len(adjacency)
    return n >= 3 and all(mask.bit_count() == 2 for mask in adjacency)


def _component_adjacency(adjacency: list[int], component: list[int]) -> list[int]:
    component_index = {old: new for new, old in enumerate(component)}
    out = [0] * len(component)
    component_mask = 0
    for old in component:
        component_mask |= 1 << old
    for old in component:
        new = component_index[old]
        neighbors = adjacency[old] & component_mask
        while neighbors:
            bit = neighbors & -neighbors
            out[new] |= 1 << component_index[bit.bit_length() - 1]
            neighbors -= bit
    return out


def _connected_components_from_adjacency(adjacency: list[int]) -> list[list[int]]:
    n = len(adjacency)
    unseen = (1 << n) - 1
    components: list[list[int]] = []
    while unseen:
        start = (unseen & -unseen).bit_length() - 1
        stack = [start]
        unseen &= ~(1 << start)
        component: list[int] = []
        while stack:
            vertex = stack.pop()
            component.append(vertex)
            neighbors = adjacency[vertex] & unseen
            while neighbors:
                bit = neighbors & -neighbors
                neighbor = bit.bit_length() - 1
                unseen &= ~bit
                stack.append(neighbor)
                neighbors -= bit
        components.append(component)
    return components


def _robber_forced_mask(closed_neighborhood: list[int], cop_turn_wins: int) -> int:
    forced = 0
    for robber, moves in enumerate(closed_neighborhood):
        if moves & ~cop_turn_wins == 0:
            forced |= 1 << robber
    return forced


@lru_cache(maxsize=512)
def _cop_number_connected_from_adjacency(adjacency_tuple: tuple[int, ...]) -> int:
    adjacency = list(adjacency_tuple)
    n = len(adjacency)
    if n <= 1:
        return n
    if _is_complete_graph(adjacency) or _is_tree_graph(adjacency):
        return 1
    if _is_cycle_graph(adjacency):
        return 1 if n == 3 else 2

    closed_neighborhood = _closed_neighborhood_masks(adjacency)
    all_mask = (1 << n) - 1

    for k in range(1, n + 1):
        _check_pursuit_state_limit(n, k, "cop number")
        cop_positions = _pursuit_position_tuples(n, k)
        position_index = {positions: index for index, positions in enumerate(cop_positions)}
        captured_masks = [_positions_mask(positions) for positions in cop_positions]

        cop_next_indices: list[tuple[int, ...]] = []
        closed_neighbors = [_bit_indices(mask) for mask in closed_neighborhood]
        for positions in cop_positions:
            next_positions: set[int] = set()
            for move_choice in product(*(closed_neighbors[position] for position in positions)):
                next_positions.add(position_index[tuple(sorted(move_choice))])
            cop_next_indices.append(tuple(next_positions))

        cop_turn_wins = captured_masks[:]
        robber_turn_wins = captured_masks[:]

        while True:
            changed = False
            next_robber_turn_wins = robber_turn_wins[:]
            for index, captured in enumerate(captured_masks):
                value = captured | _robber_forced_mask(closed_neighborhood, cop_turn_wins[index])
                if value != robber_turn_wins[index]:
                    next_robber_turn_wins[index] = value
                    changed = True

            next_cop_turn_wins = cop_turn_wins[:]
            for index, captured in enumerate(captured_masks):
                value = captured
                for next_index in cop_next_indices[index]:
                    value |= next_robber_turn_wins[next_index]
                    if value == all_mask:
                        break
                if value != cop_turn_wins[index]:
                    next_cop_turn_wins[index] = value
                    changed = True

            cop_turn_wins = next_cop_turn_wins
            robber_turn_wins = next_robber_turn_wins
            if not changed:
                break

        if any(mask == all_mask for mask in cop_turn_wins):
            return k

    return n


def _distance_matrix(adjacency: list[int]) -> list[list[int]]:
    n = len(adjacency)
    distances: list[list[int]] = []
    for source in range(n):
        row = [-1] * n
        row[source] = 0
        queue = [source]
        cursor = 0
        while cursor < len(queue):
            vertex = queue[cursor]
            cursor += 1
            neighbors = adjacency[vertex]
            while neighbors:
                bit = neighbors & -neighbors
                neighbor = bit.bit_length() - 1
                if row[neighbor] < 0:
                    row[neighbor] = row[vertex] + 1
                    queue.append(neighbor)
                neighbors -= bit
        distances.append(row)
    return distances


DamagePursuerKind = Literal["cop", "zombie"]
DamageMoveTable = list[list[tuple[int, ...]]]


def _check_damage_state_limit(n: int, game_name: str) -> None:
    state_limit = _game_state_limit_from_env()
    state_count = 2 * (1 << n) * n * n
    if state_limit != 0 and state_count > state_limit:
        raise RuntimeError(f"{game_name} state limit exceeded ({state_count} states > {state_limit})")


def _damage_pursuer_move_table(
    pursuer_kind: DamagePursuerKind,
    adjacency: list[int],
    closed_moves: list[tuple[int, ...]],
) -> DamageMoveTable:
    n = len(adjacency)
    if pursuer_kind == "cop":
        return [[closed_moves[pursuer] for _ in range(n)] for pursuer in range(n)]

    distances = _distance_matrix(adjacency)
    move_table: DamageMoveTable = [[() for _ in range(n)] for _ in range(n)]
    for pursuer in range(n):
        for evader in range(n):
            if pursuer == evader:
                continue
            move_table[pursuer][evader] = tuple(
                neighbor
                for neighbor in _bit_indices(adjacency[pursuer])
                if distances[neighbor][evader] == distances[pursuer][evader] - 1
            )
    return move_table


def _damage_evader_values(
    n: int,
    damaged_mask: int,
    damage_size: int,
    closed_moves: list[tuple[int, ...]],
    pursuer_values: array,
    pursuer_values_by_mask: list[bytes | None],
) -> array:
    values = array("B", [damage_size]) * (n * n)
    for pursuer in range(n):
        row_offset = pursuer * n
        for evader in range(n):
            if pursuer == evader:
                continue

            next_damaged_mask = damaged_mask | (1 << evader)
            next_damage_size = next_damaged_mask.bit_count()
            if next_damaged_mask == damaged_mask:
                next_pursuer_values = pursuer_values
            else:
                solved_values = pursuer_values_by_mask[next_damaged_mask]
                if solved_values is None:  # pragma: no cover - guards processing order
                    raise RuntimeError("damage masks were not processed in descending order")
                next_pursuer_values = solved_values

            value = next_damage_size
            for next_evader in closed_moves[evader]:
                candidate = (
                    next_damage_size
                    if next_evader == pursuer
                    else next_pursuer_values[row_offset + next_evader]
                )
                value = max(value, candidate)
                if value == n:
                    break
            values[row_offset + evader] = value
    return values


def _advance_damage_pursuer_values(
    n: int,
    damage_size: int,
    move_table: DamageMoveTable,
    pursuer_values: array,
    evader_values: array,
) -> tuple[array, bool]:
    next_values = array("B", pursuer_values)
    changed = False
    for pursuer in range(n):
        row_offset = pursuer * n
        for evader in range(n):
            if pursuer == evader:
                continue

            value = n
            for next_pursuer in move_table[pursuer][evader]:
                candidate = (
                    damage_size
                    if next_pursuer == evader
                    else evader_values[next_pursuer * n + evader]
                )
                value = min(value, candidate)
                if value == damage_size:
                    break

            state_index = row_offset + evader
            if value != pursuer_values[state_index]:
                next_values[state_index] = value
                changed = True
    return next_values, changed


def _solve_damage_mask(
    n: int,
    damaged_mask: int,
    damage_size: int,
    closed_moves: list[tuple[int, ...]],
    move_table: DamageMoveTable,
    pursuer_values_by_mask: list[bytes | None],
) -> bytes:
    pursuer_values = array("B", [damage_size]) * (n * n)
    while True:
        evader_values = _damage_evader_values(
            n,
            damaged_mask,
            damage_size,
            closed_moves,
            pursuer_values,
            pursuer_values_by_mask,
        )
        next_values, changed = _advance_damage_pursuer_values(
            n,
            damage_size,
            move_table,
            pursuer_values,
            evader_values,
        )
        if not changed:
            return pursuer_values.tobytes()
        pursuer_values = next_values


@lru_cache(maxsize=1024)
def _damage_game_value_connected_from_adjacency(
    pursuer_kind: DamagePursuerKind,
    adjacency_tuple: tuple[int, ...],
) -> int:
    """Solve the one-pursuer damage game by monotone value iteration.

    A state records the pursuer position, evader position, turn, and set of
    vertices already damaged. Damage sets are processed from larger to smaller,
    so a move that damages a new vertex refers to an already-solved state. The
    remaining same-set cycles are the least fixed point of the finite-horizon
    payoff iteration; this is also the infinite-game value because damage is
    permanent and at most ``n`` distinct vertices can be damaged.
    """

    adjacency = list(adjacency_tuple)
    n = len(adjacency)
    if n <= 1:
        return 0

    degrees = [mask.bit_count() for mask in adjacency]
    if max(degrees) == n - 1:
        return 0
    if _is_tree_graph(adjacency) and max(degrees) <= 2:
        return max(0, n // 2 - 1)
    if _is_cycle_graph(adjacency):
        if pursuer_kind == "cop":
            return (n - 1) // 2
        return 2 if n == 4 else n

    _check_damage_state_limit(
        n,
        "damage number" if pursuer_kind == "cop" else "zombie damage number",
    )

    closed_neighborhood = _closed_neighborhood_masks(adjacency)
    closed_moves = [tuple(_bit_indices(mask)) for mask in closed_neighborhood]
    move_table = _damage_pursuer_move_table(pursuer_kind, adjacency, closed_moves)
    pursuer_values_by_mask: list[bytes | None] = [None] * (1 << n)

    for damage_size in range(n, -1, -1):
        for damaged_vertices in combinations(range(n), damage_size):
            damaged_mask = 0
            for vertex in damaged_vertices:
                damaged_mask |= 1 << vertex

            pursuer_values_by_mask[damaged_mask] = _solve_damage_mask(
                n,
                damaged_mask,
                damage_size,
                closed_moves,
                move_table,
                pursuer_values_by_mask,
            )

    initial_values = pursuer_values_by_mask[0]
    if initial_values is None:  # pragma: no cover - mask zero is always processed
        raise RuntimeError("initial damage state was not solved")

    return min(
        max(initial_values[pursuer * n + evader] for evader in range(n))
        for pursuer in range(n)
    )


@lru_cache(maxsize=512)
def _zombie_number_connected_from_adjacency(adjacency_tuple: tuple[int, ...]) -> int:
    adjacency = list(adjacency_tuple)
    n = len(adjacency)
    if n <= 1:
        return n
    if _is_complete_graph(adjacency) or _is_tree_graph(adjacency):
        return 1
    if _is_cycle_graph(adjacency):
        return 1 if n == 3 else 2

    closed_neighborhood = _closed_neighborhood_masks(adjacency)
    all_mask = (1 << n) - 1
    distances = _distance_matrix(adjacency)
    geodesic_next: list[list[tuple[int, ...]]] = [[() for _ in range(n)] for _ in range(n)]
    for zombie in range(n):
        for survivor in range(n):
            if zombie == survivor:
                continue
            geodesic_next[zombie][survivor] = tuple(
                neighbor
                for neighbor in _bit_indices(adjacency[zombie])
                if distances[neighbor][survivor] == distances[zombie][survivor] - 1
            )

    lower_bound = _cop_number_connected_from_adjacency(adjacency_tuple)
    for k in range(lower_bound, n + 1):
        _check_pursuit_state_limit(n, k, "zombie number")
        zombie_positions = _pursuit_position_tuples(n, k)
        position_index = {positions: index for index, positions in enumerate(zombie_positions)}
        captured_masks = [_positions_mask(positions) for positions in zombie_positions]

        @cache
        def next_zombie_indices(
            index: int,
            survivor: int,
            *,
            current_zombie_positions: tuple[tuple[int, ...], ...] = zombie_positions,
            current_position_index: dict[tuple[int, ...], int] = position_index,
        ) -> tuple[int, ...]:
            positions = current_zombie_positions[index]
            if any(position == survivor for position in positions):
                return (index,)
            next_positions: set[int] = set()
            for move_choice in product(*(geodesic_next[position][survivor] for position in positions)):
                next_positions.add(current_position_index[tuple(sorted(move_choice))])
            return tuple(next_positions)

        zombie_turn_wins = captured_masks[:]
        survivor_turn_wins = captured_masks[:]

        while True:
            changed = False
            next_survivor_turn_wins = survivor_turn_wins[:]
            for index, captured in enumerate(captured_masks):
                survivor_forced = 0
                for survivor, moves in enumerate(closed_neighborhood):
                    if moves & ~zombie_turn_wins[index] == 0:
                        survivor_forced |= 1 << survivor
                value = captured | survivor_forced
                if value != survivor_turn_wins[index]:
                    next_survivor_turn_wins[index] = value
                    changed = True

            next_zombie_turn_wins = zombie_turn_wins[:]
            for index, captured in enumerate(captured_masks):
                value = captured
                for survivor in range(n):
                    if value & (1 << survivor):
                        continue
                    for next_index in next_zombie_indices(index, survivor):
                        if next_survivor_turn_wins[next_index] & (1 << survivor):
                            value |= 1 << survivor
                            break
                if value != zombie_turn_wins[index]:
                    next_zombie_turn_wins[index] = value
                    changed = True

            zombie_turn_wins = next_zombie_turn_wins
            survivor_turn_wins = next_survivor_turn_wins
            if not changed:
                break

        if any(mask == all_mask for mask in zombie_turn_wins):
            return k

    return n


def _component_sum(adjacency: list[int], compute_component) -> int:
    components = _connected_components_from_adjacency(adjacency)
    if len(components) == 1:
        return compute_component(tuple(adjacency))
    return sum(compute_component(tuple(_component_adjacency(adjacency, component))) for component in components)


def cop_number(G: nx.Graph) -> int:
    adjacency, _ = _adjacency_masks(nx.Graph(G))
