def part_sizes(G) -> tuple[int, int] | None:
    graph = nx.Graph(G)
    if graph.number_of_nodes() < 2 or not nx.is_connected(graph) or not nx.is_bipartite(graph):
        return None
    color = nx.algorithms.bipartite.color(graph)
    part_a = sum(1 for value in color.values() if value == 0)
    part_b = graph.number_of_nodes() - part_a
    if part_a == 0 or part_b == 0 or graph.number_of_edges() != part_a * part_b:
        return None
    if part_a <= part_b:
        return part_a, part_b
    return part_b, part_a


def arboricity_or_graphcalc(G):
    sizes = part_sizes(G)
    if sizes is not None:
        a, b = sizes
        return (a * b + a + b - 2) // (a + b - 1)
    return arboricity_fast_exact(G)


def bipartite_number_or_graphcalc(G) -> int:
