def bipartite_number_fast_exact(G) -> int:
    H = nx.Graph(G)
    H.remove_edges_from(nx.selfloop_edges(H))
    n = H.number_of_nodes()
    if n <= 2 or H.number_of_edges() == 0:
        return n
    if nx.is_bipartite(H):
        return n
    if H.number_of_edges() == n * (n - 1) // 2:
        return 2

    nodes = list(H.nodes())
    node_index = {node: index for index, node in enumerate(nodes)}
    b_offset = n
    rows: list[int] = []
    cols: list[int] = []
    data: list[float] = []
    lower_bounds: list[float] = []
    upper_bounds: list[float] = []
    row_index = 0

    def add_row(terms: list[tuple[int, float]], lower: float, upper: float) -> None:
        nonlocal row_index
        for col, value in terms:
            rows.append(row_index)
            cols.append(col)
            data.append(value)
        lower_bounds.append(lower)
        upper_bounds.append(upper)
        row_index += 1

    for node in nodes:
        index = node_index[node]
        add_row([(index, 1.0), (b_offset + index, 1.0)], 0.0, 1.0)

    for u, v in H.edges():
        u_index = node_index[u]
        v_index = node_index[v]
        add_row([(u_index, 1.0), (v_index, 1.0)], 0.0, 1.0)
        add_row([(b_offset + u_index, 1.0), (b_offset + v_index, 1.0)], 0.0, 1.0)

    result = milp(
        c=[-1.0] * (2 * n),
        integrality=[1] * (2 * n),
        bounds=Bounds(0.0, 1.0),
        constraints=LinearConstraint(
            coo_array((data, (rows, cols)), shape=(row_index, 2 * n)),
            cast(Any, lower_bounds),
            cast(Any, upper_bounds),
        ),
    )
    if not result.success:
        msg = getattr(result, "message", "unknown solver failure")
        raise RuntimeError(f"bipartite_number MILP failed: {msg}")
    return round(-result.fun)


def arboricity_fast_exact(G) -> int:
    """Compute exact graph arboricity with a smaller Nash-Williams min-cut oracle.

    GraphCalc's exact implementation checks a fixed ``k`` by forcing every pair of
    vertices into the source side of the cut. It is exact, but expensive. For the
    same objective it is enough to force one vertex at a time: every violating
    subset of size at least two contains some forced vertex, while a forced
    singleton has objective exactly ``-k`` and therefore is not a false violation.
    """
    if G.is_directed():
        raise nx.NetworkXError("arboricity() here is for undirected graphs only.")

    H = nx.Graph(G)
    H.remove_edges_from(nx.selfloop_edges(H))
    n = H.number_of_nodes()
    m = H.number_of_edges()
    if n <= 1 or m == 0:
        return 0
    if nx.is_forest(H):
        return 1
    if m == n * (n - 1) // 2:
        return (n + 1) // 2

    nodes = list(H.nodes())
    lo = max(1, (m + n - 2) // (n - 1))
    hi = max(1, max((len(list(H.neighbors(node))) for node in nodes), default=0))
    if lo == hi:
        return lo

    edges = list(H.edges())

    def violates(k: int) -> bool:
        inf_capacity = float(m + k * n + 1)
        for forced_vertex in nodes:
            source = ("__theo_arboricity_source__", forced_vertex)
            sink = ("__theo_arboricity_sink__", forced_vertex)
            cut_graph = nx.DiGraph()
            for vertex in nodes:
                cut_graph.add_edge(vertex, sink, capacity=float(k))
            cut_graph.add_edge(source, forced_vertex, capacity=inf_capacity)
            for edge_index, (u, v) in enumerate(edges):
                edge_node = ("__theo_arboricity_edge__", edge_index)
                cut_graph.add_edge(source, edge_node, capacity=1.0)
                cut_graph.add_edge(edge_node, u, capacity=inf_capacity)
                cut_graph.add_edge(edge_node, v, capacity=inf_capacity)

            cut_value, _ = nx.minimum_cut(cut_graph, source, sink, capacity="capacity")
            max_value = m - cut_value
            if max_value + k > 1e-9:
                return True
        return False

    while lo < hi:
        mid = (lo + hi) // 2
        if violates(mid):
            lo = mid + 1
        else:
            hi = mid
    return lo


