def skew_zero_forcing_number_for_standard_family(G) -> int | None:
    graph = nx.Graph(G)
    graph.remove_edges_from(nx.selfloop_edges(graph))
    n = graph.number_of_nodes()
    m = graph.number_of_edges()
    if n == 0:
        return 0
    if m == 0:
        return n
    degrees = sorted(dict(graph.degree()).values())
    if n == 1:
        return 1
    if m == n * (n - 1) // 2:
        return 0 if n == 2 else n - 2
    sizes = part_sizes(graph)
    if sizes is not None:
        return skew_zero_forcing_number_for_sizes(*sizes)
    if nx.is_connected(graph) and degrees == [1, 1, *([2] * (n - 2))]:
        return n % 2
    if n >= 3 and nx.is_connected(graph) and all(degree == 2 for degree in degrees):
        return 1 if n % 2 == 1 else 2
    if _is_wheel_graph(graph):
        return 2 if n % 2 == 0 else 3
    return None


def _is_wheel_graph(graph: nx.Graph) -> bool:
    n = graph.number_of_nodes()
    if n < 4 or graph.number_of_edges() != 2 * (n - 1):
        return False
    degrees = dict(graph.degree())
    hubs = [vertex for vertex, degree in degrees.items() if degree == n - 1]
    if len(hubs) != 1:
        return False
    rim_nodes = [vertex for vertex in graph.nodes() if vertex != hubs[0]]
    rim = graph.subgraph(rim_nodes)
    return nx.is_connected(rim) and all(degree == 2 for _, degree in rim.degree())


