    if a == 0 or b == 0:
        return a + b
    return min(a, b)


def critical_count_matches(base_value: int, modified_value: int, *, kind: str) -> bool:
    if kind == "change":
        return modified_value != base_value
    if kind == "same":
        return modified_value == base_value
    if kind == "increase":
        return modified_value > base_value
    if kind == "decrease":
        return modified_value < base_value
    raise ValueError(f"unknown criticality kind: {kind}")


