def vertex_critical_count_or_graphcalc(G, invariant_from_sizes, fallback_invariant_func, *, kind: str):
    sizes = part_sizes(G)
    if sizes is not None:
        a, b = sizes
        base_value = invariant_from_sizes(a, b)
        count = 0
        if a and critical_count_matches(base_value, invariant_from_sizes(a - 1, b), kind=kind):
            count += a
        if b and critical_count_matches(base_value, invariant_from_sizes(a, b - 1), kind=kind):
            count += b
        return count
    return gc_graphs.vertex_critical_number(G, fallback_invariant_func, kind=kind)


