def psd_zero_forcing_vertex_critical_count_or_graphcalc(G, *, kind: str):
    path_value = _psd_zero_forcing_vertex_critical_count_for_path(G, kind=kind)
    if path_value is not None:
        return path_value
    cycle_value = _psd_zero_forcing_vertex_critical_count_for_cycle(G, kind=kind)
    if cycle_value is not None:
        return cycle_value
    if small_exact.supports(G):
        return small_exact.vertex_critical_count(
            G,
