        )
    return vertex_critical_count_or_graphcalc(
        G,
        positive_semidefinite_zero_forcing_number_for_sizes,
        gc_graphs.positive_semidefinite_zero_forcing_number,
        kind=kind,
    )


def _psd_zero_forcing_vertex_critical_count_for_path(G, *, kind: str) -> int | None:
    n = G.number_of_nodes()
    if n == 0:
        return _critical_kind_count(base=0, modified_values=[], kind=kind)
    if n == 1:
        return _critical_kind_count(base=1, modified_values=[0], kind=kind)
    degrees = sorted(dict(G.degree()).values())
    if degrees != [1, 1, *([2] * (n - 2))]:
        return None
    if not nx.is_connected(G):
        return None
    # For a path P_n, Z_+(P_n)=1.  Deleting a leaf leaves a path, so Z_+=1;
    # deleting an internal vertex leaves two path components, so Z_+=2.
    return _critical_kind_count(base=1, modified_values=[1, 1, *([2] * (n - 2))], kind=kind)


def _psd_zero_forcing_vertex_critical_count_for_cycle(G, *, kind: str) -> int | None:
    n = G.number_of_nodes()
    if n < 3:
        return None
    if any(degree != 2 for _, degree in G.degree()):
        return None
    if not nx.is_connected(G):
        return None
    # For a cycle C_n, Z_+(C_n)=2.  Deleting any vertex leaves a path, so Z_+=1.
    return _critical_kind_count(base=2, modified_values=[1] * n, kind=kind)


def _critical_kind_count(base: int, modified_values: list[int], *, kind: str) -> int:
    if kind == "change":
        return sum(value != base for value in modified_values)
    if kind == "same":
        return sum(value == base for value in modified_values)
    if kind == "increase":
        return sum(value > base for value in modified_values)
    if kind == "decrease":
        return sum(value < base for value in modified_values)
    raise ValueError(f"unknown criticality kind: {kind}")


def independence_noncritical_edge_count_or_graphcalc(G):
    if small_exact.supports(G):
        return small_exact.edge_critical_count(
            G,
            small_exact.independence_number_from_adjacency,
            kind="same",
        )
    sizes = part_sizes(G)
    if sizes is not None:
        a, b = sizes
        return 0 if a == 1 and b == 1 else a * b
    return gc_graphs.edge_critical_number(G, gc_graphs.independence_number, kind="same")


def domination_noncritical_edge_count_or_graphcalc(G):
    if small_exact.supports(G):
        return small_exact.edge_critical_count(
            G,
            small_exact.domination_number_from_adjacency,
            kind="same",
        )
    sizes = part_sizes(G)
