        a, b = sizes
        return 0 if min(a, b) == 1 else a * b
    return gc_graphs.edge_critical_number(G, gc_graphs.domination_number, kind="same")


def zero_forcing_noncritical_edge_count_or_graphcalc(G):
    if small_exact.supports(G):
        return small_exact.edge_critical_count(
            G,
            small_exact.zero_forcing_number_from_adjacency,
            kind="same",
        )
    sizes = part_sizes(G)
    if sizes is not None:
        a, b = sizes
        if min(a, b) == 1:
            spokes = max(a, b)
            # For r >= 3, deleting a spoke from K_{1,r} gives
            # K_{1,r-1} plus one isolated vertex, preserving Z = r - 1.
            return spokes if spokes >= 3 else 0
        return 0
    return gc_graphs.edge_critical_number(G, gc_graphs.zero_forcing_number, kind="same")


def connected_domination_number_or_graphcalc(G):
    if small_exact.supports(G):
