    return gc_graphs.restrained_domination_number(G)

from __future__ import annotations

import itertools
from typing import Any, cast

import networkx as nx
from scipy.optimize import Bounds, LinearConstraint, milp


def _node_index_and_neighbor_masks(G):
    nodes = list(G.nodes())
    node_index = {node: index for index, node in enumerate(nodes)}
    neighbor_masks = []
    for node in nodes:
        mask = 0
        for neighbor in G.neighbors(node):
            mask |= 1 << node_index[neighbor]
        neighbor_masks.append(mask)
    return nodes, node_index, neighbor_masks


def _submasks(mask: int):
    submask = mask
    while True:
        yield submask
        if submask == 0:
            break
        submask = (submask - 1) & mask


def _independent_mask_table(neighbor_masks: list[int]) -> list[bool]:
    total = 1 << len(neighbor_masks)
    table = [True] * total
    for mask in range(1, total):
        least_bit = mask & -mask
        vertex = least_bit.bit_length() - 1
        rest = mask ^ least_bit
        table[mask] = table[rest] and not bool(neighbor_masks[vertex] & rest)
    return table


def _mask_from_subset(subset) -> int:
    selected_mask = 0
    for vertex in subset:
        selected_mask |= 1 << vertex
    return selected_mask


def _mask_nodes(nodes: list[Any], mask: int) -> list[Any]:
    return [node for index, node in enumerate(nodes) if mask & (1 << index)]


def _is_connected_mask(neighbor_masks: list[int], selected_mask: int) -> bool:
    if selected_mask == 0:
        return False
    seen = 0
    frontier = selected_mask & -selected_mask
    while frontier:
        seen |= frontier
        neighbors = 0
        walk = frontier
        while walk:
            bit = walk & -walk
            vertex = bit.bit_length() - 1
            neighbors |= neighbor_masks[vertex]
            walk ^= bit
        frontier = (neighbors & selected_mask) & ~seen
    return seen == selected_mask


def _is_acyclic_mask(G, nodes: list[Any], selected_mask: int) -> bool:
    if selected_mask == 0:
        return True
    return nx.is_forest(G.subgraph(_mask_nodes(nodes, selected_mask)))


def _has_perfect_matching_mask(G, nodes: list[Any], selected_mask: int) -> bool:
    if selected_mask.bit_count() % 2:
        return False
    subgraph = G.subgraph(_mask_nodes(nodes, selected_mask))
    matching = nx.algorithms.matching.max_weight_matching(subgraph, maxcardinality=True)
    return 2 * len(matching) == selected_mask.bit_count()


def _dominates_mask(neighbor_masks: list[int], selected_mask: int) -> bool:
    return all(
        (selected_mask & (1 << vertex)) or (neighbor_masks[vertex] & selected_mask)
        for vertex in range(len(neighbor_masks))
    )


def _dual_server_masks_dominate(
    neighbor_masks: list[int],
    red_mask: int,
    blue_mask: int,
    *,
    strong_total: bool,
) -> bool:
    selected_mask = red_mask | blue_mask
    if not red_mask or not blue_mask:
        return False
    if strong_total:
        return all((neighbor_masks[vertex] & red_mask) and (neighbor_masks[vertex] & blue_mask) for vertex in range(len(neighbor_masks)))
    outside_mask = ((1 << len(neighbor_masks)) - 1) ^ selected_mask
    return all(
        (neighbor_masks[vertex] & red_mask) and (neighbor_masks[vertex] & blue_mask)
        for vertex in range(len(neighbor_masks))
        if outside_mask & (1 << vertex)
    )


def _two_domination_number_bruteforce(G):
    nodes, _node_index, neighbor_masks = _node_index_and_neighbor_masks(G)
    n = len(nodes)
    if n == 0:
        return 0

    for k in range(n + 1):
        for subset in itertools.combinations(range(n), k):
            selected_mask = 0
            for vertex in subset:
                selected_mask |= 1 << vertex
            if all(
                (selected_mask & (1 << vertex)) or (neighbor_masks[vertex] & selected_mask).bit_count() >= 2
                for vertex in range(n)
            ):
                return k
    return n


def _dual_server_domination_number_bruteforce(G, *, independent: bool):
    nodes, _node_index, neighbor_masks = _node_index_and_neighbor_masks(G)
    n = len(nodes)
    if n == 0:
        return 0

    all_mask = (1 << n) - 1
    independent_masks = _independent_mask_table(neighbor_masks) if independent else None
    for k in range(n + 1):
        for subset in itertools.combinations(range(n), k):
            selected_mask = 0
            for vertex in subset:
                selected_mask |= 1 << vertex
            outside_mask = all_mask ^ selected_mask
            if not independent and outside_mask == 0:
                return k
            for red_mask in _submasks(selected_mask):
                blue_mask = selected_mask ^ red_mask
                if independent and (
                    independent_masks is None or not independent_masks[red_mask] or not independent_masks[blue_mask]
                ):
                    continue
                if all(
                    (neighbor_masks[vertex] & red_mask) and (neighbor_masks[vertex] & blue_mask)
                    for vertex in range(n)
                    if outside_mask & (1 << vertex)
                ):
                    return k
    return n


def _dual_server_variant_bruteforce(
    G,
    *,
    independent: bool = False,
    connected: bool = False,
    paired: bool = False,
    acyclic: bool = False,
    strong_total: bool = False,
):
    nodes, _node_index, neighbor_masks = _node_index_and_neighbor_masks(G)
    n = len(nodes)
    if n == 0:
        return 0

    independent_masks = _independent_mask_table(neighbor_masks) if independent else None
    for k in range(n + 1):
        for subset in itertools.combinations(range(n), k):
            selected_mask = _mask_from_subset(subset)
            if connected and not _is_connected_mask(neighbor_masks, selected_mask):
                continue
            if paired and not _has_perfect_matching_mask(G, nodes, selected_mask):
                continue
            if acyclic and not _is_acyclic_mask(G, nodes, selected_mask):
                continue
            for red_mask in _submasks(selected_mask):
                blue_mask = selected_mask ^ red_mask
                if independent and (
                    independent_masks is None or not independent_masks[red_mask] or not independent_masks[blue_mask]
                ):
                    continue
                if _dual_server_masks_dominate(neighbor_masks, red_mask, blue_mask, strong_total=strong_total):
                    return k
    raise ValueError("dual-server variant is infeasible for this graph")


def _acyclic_domination_number_bruteforce(G):
    nodes, _node_index, neighbor_masks = _node_index_and_neighbor_masks(G)
    n = len(nodes)
    if n == 0:
        return 0

    for k in range(n + 1):
        for subset in itertools.combinations(range(n), k):
            selected_mask = _mask_from_subset(subset)
            if _dominates_mask(neighbor_masks, selected_mask) and _is_acyclic_mask(G, nodes, selected_mask):
                return k
    raise ValueError("acyclic domination number is infeasible for this graph")


def two_domination_number(G):
    nodes, node_index, _neighbor_masks = _node_index_and_neighbor_masks(G)
    if len(nodes) <= 12:
        return _two_domination_number_bruteforce(G)
    if not nodes:
        return 0

    c = [1.0] * len(nodes)
    constraint_matrix = []
    lower_bounds = []
    upper_bounds = []

    for node in nodes:
        row = [0.0] * len(nodes)
        row[node_index[node]] = 2.0
        for neighbor in G.neighbors(node):
            row[node_index[neighbor]] = 1.0
        constraint_matrix.append(row)
        lower_bounds.append(2.0)
        upper_bounds.append(float("inf"))

    result = milp(
        c=c,
        integrality=[1] * len(c),
        bounds=Bounds(0.0, 1.0),
        constraints=LinearConstraint(
            constraint_matrix,
            cast(Any, lower_bounds),
            cast(Any, upper_bounds),
        ),
    )
    if not result.success:
        msg = getattr(result, "message", "unknown solver failure")
        raise RuntimeError(f"two_domination_number MILP failed: {msg}")
    return round(result.fun)


def _dual_server_domination_number_milp(G, *, independent: bool):
    nodes, node_index, _neighbor_masks = _node_index_and_neighbor_masks(G)
    if not nodes:
        return 0

    n = len(nodes)
    blue_offset = n
    c = [1.0] * (2 * n)
    constraint_matrix = []
    lower_bounds = []
    upper_bounds = []

    for node in nodes:
        index = node_index[node]
        disjoint_row = [0.0] * len(c)
        disjoint_row[index] = 1.0
        disjoint_row[blue_offset + index] = 1.0
        constraint_matrix.append(disjoint_row)
        lower_bounds.append(0.0)
        upper_bounds.append(1.0)

        red_service_row = [0.0] * len(c)
        blue_service_row = [0.0] * len(c)
        red_service_row[index] = 1.0
        red_service_row[blue_offset + index] = 1.0
        blue_service_row[index] = 1.0
        blue_service_row[blue_offset + index] = 1.0
        for neighbor in G.neighbors(node):
            neighbor_index = node_index[neighbor]
            red_service_row[neighbor_index] = 1.0
            blue_service_row[blue_offset + neighbor_index] = 1.0
        constraint_matrix.append(red_service_row)
        lower_bounds.append(1.0)
        upper_bounds.append(float("inf"))
        constraint_matrix.append(blue_service_row)
        lower_bounds.append(1.0)
        upper_bounds.append(float("inf"))

    if independent:
        for u, v in G.edges():
            u_index = node_index[u]
            v_index = node_index[v]
            red_edge_row = [0.0] * len(c)
            red_edge_row[u_index] = 1.0
            red_edge_row[v_index] = 1.0
            constraint_matrix.append(red_edge_row)
            lower_bounds.append(0.0)
            upper_bounds.append(1.0)

            blue_edge_row = [0.0] * len(c)
            blue_edge_row[blue_offset + u_index] = 1.0
            blue_edge_row[blue_offset + v_index] = 1.0
            constraint_matrix.append(blue_edge_row)
            lower_bounds.append(0.0)
            upper_bounds.append(1.0)

    name = "dual_server_independent_domination_number" if independent else "dual_server_domination_number"
    result = milp(
        c=c,
        integrality=[1] * len(c),
        bounds=Bounds(0.0, 1.0),
        constraints=LinearConstraint(
            constraint_matrix,
            cast(Any, lower_bounds),
            cast(Any, upper_bounds),
        ),
    )
    if not result.success:
        msg = getattr(result, "message", "unknown solver failure")
        raise RuntimeError(f"{name} MILP failed: {msg}")
    return round(result.fun)


def _append_selected_row(row: list[float], vertex_index: int, n: int, coefficient: float) -> None:
    row[vertex_index] += coefficient
    row[n + vertex_index] += coefficient


def _dual_server_variant_milp(  # noqa: C901
    G,
    *,
    independent: bool = False,
    connected: bool = False,
    paired: bool = False,
    acyclic: bool = False,
    strong_total: bool = False,
):
    nodes, node_index, neighbor_masks = _node_index_and_neighbor_masks(G)
    if not nodes:
        return 0

    n = len(nodes)
    blue_offset = n
    edges = list(G.edges())
    edge_offset = 2 * n
    edge_index = {edge: edge_offset + index for index, edge in enumerate(edges)}
    reverse_edge_index = {(v, u): edge_index[(u, v)] for u, v in edges}
    c = [1.0] * (2 * n) + ([0.0] * len(edges) if paired else [])
    bounds = Bounds(0.0, 1.0)
    integrality = [1] * len(c)
    constraint_matrix: list[list[float]] = []
    lower_bounds: list[float] = []
    upper_bounds: list[float] = []
    cut_signatures: set[tuple[str, tuple[int, ...]]] = set()

    for node in nodes:
        index = node_index[node]
        disjoint_row = [0.0] * len(c)
        disjoint_row[index] = 1.0
        disjoint_row[blue_offset + index] = 1.0
        constraint_matrix.append(disjoint_row)
        lower_bounds.append(0.0)
        upper_bounds.append(1.0)

        red_service_row = [0.0] * len(c)
        blue_service_row = [0.0] * len(c)
        if not strong_total:
            red_service_row[index] = 1.0
            red_service_row[blue_offset + index] = 1.0
            blue_service_row[index] = 1.0
            blue_service_row[blue_offset + index] = 1.0
        for neighbor in G.neighbors(node):
            neighbor_index = node_index[neighbor]
            red_service_row[neighbor_index] = 1.0
            blue_service_row[blue_offset + neighbor_index] = 1.0
        constraint_matrix.append(red_service_row)
        lower_bounds.append(1.0)
        upper_bounds.append(float("inf"))
        constraint_matrix.append(blue_service_row)
        lower_bounds.append(1.0)
        upper_bounds.append(float("inf"))

    red_nonempty = [0.0] * len(c)
    blue_nonempty = [0.0] * len(c)
    for index in range(n):
        red_nonempty[index] = 1.0
        blue_nonempty[blue_offset + index] = 1.0
    constraint_matrix.append(red_nonempty)
    lower_bounds.append(1.0)
    upper_bounds.append(float("inf"))
    constraint_matrix.append(blue_nonempty)
    lower_bounds.append(1.0)
    upper_bounds.append(float("inf"))

    if independent:
        for u, v in edges:
            u_index = node_index[u]
            v_index = node_index[v]
            red_edge_row = [0.0] * len(c)
            red_edge_row[u_index] = 1.0
            red_edge_row[v_index] = 1.0
            constraint_matrix.append(red_edge_row)
            lower_bounds.append(0.0)
            upper_bounds.append(1.0)

            blue_edge_row = [0.0] * len(c)
            blue_edge_row[blue_offset + u_index] = 1.0
            blue_edge_row[blue_offset + v_index] = 1.0
            constraint_matrix.append(blue_edge_row)
            lower_bounds.append(0.0)
            upper_bounds.append(1.0)

    if paired:
        incident_matching_edges: dict[Any, list[tuple[Any, Any]]] = {node: [] for node in nodes}
        for edge in edges:
            u, v = edge
            incident_matching_edges[u].append(edge)
            incident_matching_edges[v].append(edge)
        for node in nodes:
            row = [0.0] * len(c)
            index = node_index[node]
            row[index] = -1.0
            row[blue_offset + index] = -1.0
            for edge in incident_matching_edges[node]:
                matching_index = edge_index[edge] if edge in edge_index else reverse_edge_index[edge]
                row[matching_index] = 1.0
            constraint_matrix.append(row)
            lower_bounds.append(0.0)
            upper_bounds.append(0.0)

    name_bits = ["strong_total" if strong_total else "dual_server"]
    if independent:
        name_bits.append("independent")
    if connected:
        name_bits.append("connected")
    if paired:
        name_bits.append("paired")
    if acyclic:
        name_bits.append("acyclic")
    name = "_".join(name_bits)

    for _iteration in range(1000):
        result = milp(
            c=c,
            integrality=integrality,
            bounds=bounds,
            constraints=LinearConstraint(
                constraint_matrix,
                cast(Any, lower_bounds),
                cast(Any, upper_bounds),
            ),
        )
        if not result.success:
            msg = getattr(result, "message", "unknown solver failure")
            raise ValueError(f"{name} MILP infeasible or failed: {msg}")

        red_mask = 0
        blue_mask = 0
        for index in range(n):
            if result.x[index] > 0.5:
                red_mask |= 1 << index
            if result.x[blue_offset + index] > 0.5:
                blue_mask |= 1 << index
        selected_mask = red_mask | blue_mask
        added_cut = False

        if connected and not _is_connected_mask(neighbor_masks, selected_mask):
            selected_nodes = _mask_nodes(nodes, selected_mask)
            selected_subgraph = G.subgraph(selected_nodes)
            for component in nx.connected_components(selected_subgraph):
                component_indices = tuple(sorted(node_index[node] for node in component))
                signature = ("connected", component_indices)
                if signature in cut_signatures:
                    continue
                cut_signatures.add(signature)
                boundary_indices = {
                    node_index[neighbor]
                    for node in component
                    for neighbor in G.neighbors(node)
                    if neighbor not in component
                }
                row = [0.0] * len(c)
                for index in component_indices:
                    _append_selected_row(row, index, n, 1.0)
                for index in boundary_indices:
                    _append_selected_row(row, index, n, -1.0)
                constraint_matrix.append(row)
                lower_bounds.append(float("-inf"))
                upper_bounds.append(float(len(component_indices) - 1))
                added_cut = True

        if acyclic and not _is_acyclic_mask(G, nodes, selected_mask):
            selected_subgraph = G.subgraph(_mask_nodes(nodes, selected_mask))
            for cycle in nx.cycle_basis(selected_subgraph):
                cycle_indices = tuple(sorted(node_index[node] for node in cycle))
                signature = ("acyclic", cycle_indices)
                if signature in cut_signatures:
                    continue
                cut_signatures.add(signature)
                row = [0.0] * len(c)
                for index in cycle_indices:
                    _append_selected_row(row, index, n, 1.0)
                constraint_matrix.append(row)
                lower_bounds.append(float("-inf"))
                upper_bounds.append(float(len(cycle_indices) - 1))
                added_cut = True

        if not added_cut:
            return round(result.fun)

    raise RuntimeError(f"{name} MILP exceeded cut-loop iteration limit")


def _acyclic_domination_number_milp(G):
    nodes, node_index, _neighbor_masks = _node_index_and_neighbor_masks(G)
    if not nodes:
        return 0

    n = len(nodes)
    c = [1.0] * n
    bounds = Bounds(0.0, 1.0)
    integrality = [1] * n
    constraint_matrix = []
    lower_bounds = []
    upper_bounds = []
    cut_signatures: set[tuple[int, ...]] = set()

    for node in nodes:
        row = [0.0] * n
        row[node_index[node]] = 1.0
        for neighbor in G.neighbors(node):
            row[node_index[neighbor]] = 1.0
        constraint_matrix.append(row)
        lower_bounds.append(1.0)
        upper_bounds.append(float("inf"))

    for _iteration in range(1000):
        result = milp(
            c=c,
            integrality=integrality,
            bounds=bounds,
            constraints=LinearConstraint(
                constraint_matrix,
                cast(Any, lower_bounds),
                cast(Any, upper_bounds),
            ),
        )
        if not result.success:
            msg = getattr(result, "message", "unknown solver failure")
            raise ValueError(f"acyclic_domination_number MILP infeasible or failed: {msg}")

        selected_mask = 0
        for index in range(n):
            if result.x[index] > 0.5:
                selected_mask |= 1 << index
        if _is_acyclic_mask(G, nodes, selected_mask):
            return round(result.fun)

        selected_subgraph = G.subgraph(_mask_nodes(nodes, selected_mask))
        added_cut = False
        for cycle in nx.cycle_basis(selected_subgraph):
            cycle_indices = tuple(sorted(node_index[node] for node in cycle))
            if cycle_indices in cut_signatures:
                continue
            cut_signatures.add(cycle_indices)
            row = [0.0] * n
            for index in cycle_indices:
                row[index] = 1.0
            constraint_matrix.append(row)
            lower_bounds.append(float("-inf"))
            upper_bounds.append(float(len(cycle_indices) - 1))
            added_cut = True
        if not added_cut:
            raise RuntimeError("acyclic_domination_number MILP failed to generate a violated cycle cut")

    raise RuntimeError("acyclic_domination_number MILP exceeded cut-loop iteration limit")


def dual_server_domination_number(G):
    if G.number_of_nodes() <= 12:
        return _dual_server_domination_number_bruteforce(G, independent=False)
    return _dual_server_domination_number_milp(G, independent=False)


