def roman_domination_number(G):
    nodes = list(G.nodes())
    if not nodes:
        return 0

    n = len(nodes)
    node_index = {node: index for index, node in enumerate(nodes)}
    two_offset = n

    c = [1.0] * n + [2.0] * n
    bounds = Bounds(0.0, 1.0)
    integrality = [1] * len(c)
    constraint_matrix = []
    lower_bounds = []
    upper_bounds = []

    for node in nodes:
        row = [0.0] * len(c)
        index = node_index[node]
        row[index] = 1.0
        row[two_offset + index] = 1.0
        for neighbor in G.neighbors(node):
            row[two_offset + node_index[neighbor]] = 1.0
        constraint_matrix.append(row)
        lower_bounds.append(1.0)
        upper_bounds.append(float("inf"))

    for node in nodes:
        row = [0.0] * len(c)
        index = node_index[node]
        row[index] = 1.0
        row[two_offset + index] = 1.0
        constraint_matrix.append(row)
        lower_bounds.append(0.0)
        upper_bounds.append(1.0)

    result = milp(
        c=c,
        integrality=integrality,
        bounds=bounds,
        constraints=LinearConstraint(
            constraint_matrix,
            cast(Any, lower_bounds),
            cast(Any, upper_bounds),
        ),
    )
    if not result.success:
        msg = getattr(result, "message", "unknown solver failure")
        raise RuntimeError(f"roman_domination_number MILP failed: {msg}")
    return round(result.fun)


def rainbow_domination_number(G, *, color_count: int):
    nodes = list(G.nodes())
    if not nodes:
        return 0

    node_index = {node: index for index, node in enumerate(nodes)}
    variable_count = len(nodes) * color_count
    c = [1.0] * variable_count
    bounds = Bounds(0.0, 1.0)
    integrality = [1] * variable_count
    constraint_matrix = []
    lower_bounds = []
    upper_bounds = []

    def variable_index(node, color_index: int) -> int:
        return node_index[node] * color_count + color_index

    for node in nodes:
        own_variable_indexes = [variable_index(node, color_index) for color_index in range(color_count)]
        for color_index in range(color_count):
            row = [0.0] * variable_count
            for own_index in own_variable_indexes:
                row[own_index] = 1.0
            for neighbor in G.neighbors(node):
                row[variable_index(neighbor, color_index)] = 1.0
            constraint_matrix.append(row)
            lower_bounds.append(1.0)
            upper_bounds.append(float("inf"))

    result = milp(
        c=c,
        integrality=integrality,
        bounds=bounds,
        constraints=LinearConstraint(
            constraint_matrix,
            cast(Any, lower_bounds),
            cast(Any, upper_bounds),
        ),
    )
    if not result.success:
        msg = getattr(result, "message", "unknown solver failure")
        raise RuntimeError(f"{color_count}_rainbow_domination_number MILP failed: {msg}")
    return round(result.fun)


def two_rainbow_domination_number(G):
    return rainbow_domination_number(G, color_count=2)


def three_rainbow_domination_number(G):
    return rainbow_domination_number(G, color_count=3)

from __future__ import annotations

import os
from collections.abc import Callable, Sequence
from functools import cache

import networkx as nx

SMALL_GRAPH_MAX_ORDER = int(os.environ.get("GRAPHS_SMALL_EXACT_MAX_ORDER", "10"))


def supports(G) -> bool:
    return G.number_of_nodes() <= SMALL_GRAPH_MAX_ORDER


def adjacency_masks(G) -> tuple[int, tuple[int, ...]]:
    graph = nx.Graph(G)
    nodes = list(graph.nodes())
    node_index = {node: index for index, node in enumerate(nodes)}
    adj = [0] * len(nodes)
    for u, v in graph.edges():
        if u == v:
            continue
        i = node_index[u]
        j = node_index[v]
        adj[i] |= 1 << j
        adj[j] |= 1 << i
    return len(nodes), tuple(adj)


def _full_mask(n: int) -> int:
    return (1 << n) - 1


def _single_bit(mask: int) -> bool:
    return mask != 0 and (mask & (mask - 1)) == 0


def _bits(mask: int):
    while mask:
        bit = mask & -mask
        yield bit.bit_length() - 1
        mask ^= bit


def _subsets_of_size(n: int, size: int):
    limit = 1 << n
    for mask in range(limit):
        if mask.bit_count() == size:
            yield mask


def _induced_adjacency(adj: Sequence[int], subset: int) -> tuple[int, ...]:
    old_to_new = {}
    for new_index, old_index in enumerate(_bits(subset)):
        old_to_new[old_index] = new_index

    induced = [0] * len(old_to_new)
    for old_i, new_i in old_to_new.items():
        neighbors = adj[old_i] & subset
        new_mask = 0
        for old_j in _bits(neighbors):
            new_mask |= 1 << old_to_new[old_j]
        induced[new_i] = new_mask
    return tuple(induced)


def _edge_count(adj: Sequence[int], mask: int | None = None) -> int:
    if mask is None:
        return sum(bits.bit_count() for bits in adj) // 2
    return sum((adj[i] & mask).bit_count() for i in _bits(mask)) // 2


def _is_complete(adj: Sequence[int]) -> bool:
    n = len(adj)
    full = _full_mask(n)
    return all(adj[i] == (full ^ (1 << i)) for i in range(n))


def _is_connected_on_mask(adj: Sequence[int], mask: int) -> bool:
    if mask == 0:
        return False
    seen = 0
    frontier = mask & -mask
    while frontier:
        bit = frontier & -frontier
        vertex = bit.bit_length() - 1
        frontier ^= bit
        if seen & bit:
            continue
        seen |= bit
        frontier |= adj[vertex] & mask & ~seen
    return seen == mask


def _is_forest(adj: Sequence[int], mask: int) -> bool:
    unseen = mask
    while unseen:
        component = 0
        frontier = unseen & -unseen
        while frontier:
            bit = frontier & -frontier
            vertex = bit.bit_length() - 1
            frontier ^= bit
            if component & bit:
                continue
            component |= bit
            frontier |= adj[vertex] & unseen & ~component
        vertices = component.bit_count()
        edges = _edge_count(adj, component)
        if edges != vertices - 1:
            return False
        unseen &= ~component
    return True


def _is_bipartite(adj: Sequence[int], mask: int) -> bool:
    uncolored = mask
    color_a = 0
    color_b = 0
    while uncolored:
        start = uncolored & -uncolored
        color_a |= start
        frontier = start
        uncolored ^= start
        while frontier:
            bit = frontier & -frontier
            vertex = bit.bit_length() - 1
            frontier ^= bit
            same_color = color_a if color_a & bit else color_b
            neighbors = adj[vertex] & mask
            if neighbors & same_color:
                return False
            new_vertices = neighbors & ~(color_a | color_b)
            if color_a & bit:
                color_b |= new_vertices
            else:
                color_a |= new_vertices
            frontier |= new_vertices
            uncolored &= ~new_vertices
    return True


def _without_vertex_adjacency(adj: Sequence[int], vertex: int) -> tuple[int, ...]:
    full = _full_mask(len(adj))
    return _induced_adjacency(adj, full ^ (1 << vertex))


def _without_edge_adjacency(adj: Sequence[int], u: int, v: int) -> tuple[int, ...]:
    updated = list(adj)
    updated[u] &= ~(1 << v)
    updated[v] &= ~(1 << u)
    return tuple(updated)


def _is_clique(adj: Sequence[int], mask: int) -> bool:
    remaining = mask
    while remaining:
        bit = remaining & -remaining
        i = bit.bit_length() - 1
        if (mask ^ bit) & ~adj[i]:
            return False
        remaining ^= bit
    return True


def _is_independent(adj: Sequence[int], mask: int) -> bool:
    remaining = mask
    while remaining:
        bit = remaining & -remaining
        i = bit.bit_length() - 1
        if adj[i] & (mask ^ bit):
            return False
        remaining ^= bit
    return True


def clique_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n, -1, -1):
        for mask in _subsets_of_size(n, size):
            if _is_clique(adj, mask):
                return size
    return 0


def independence_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n, -1, -1):
        for mask in _subsets_of_size(n, size):
            if _is_independent(adj, mask):
                return size
    return 0


def chromatic_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    if n == 0:
        return 0
    if all(mask == 0 for mask in adj):
        return 1

    lower = clique_number_from_adjacency(adj)
    order = sorted(range(n), key=lambda i: adj[i].bit_count(), reverse=True)

    def can_color(k: int) -> bool:
        color_masks = [0] * k

        def search(pos: int, used_colors: int) -> bool:
            if pos == n:
                return True

            vertex = order[pos]
            for color in range(min(used_colors + 1, k)):
                if adj[vertex] & color_masks[color]:
                    continue
                color_masks[color] |= 1 << vertex
                if search(pos + 1, max(used_colors, color + 1)):
                    return True
                color_masks[color] &= ~(1 << vertex)
                if color == used_colors:
                    break
            return False

        return search(0, 0)

    for colors in range(lower, n + 1):
        if can_color(colors):
            return colors
    return n


def vertex_clique_cover_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    full = _full_mask(n)
    complement = tuple(full ^ (1 << i) ^ adj[i] for i in range(n))
    return chromatic_number_from_adjacency(complement)


def domination_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    full = _full_mask(n)
    closed = tuple(adj[i] | (1 << i) for i in range(n))
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            dominated = 0
            for i in _bits(mask):
                dominated |= closed[i]
            if dominated == full:
                return size
    return n


def total_domination_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    full = _full_mask(n)
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            dominated = 0
            for i in _bits(mask):
                dominated |= adj[i]
            if dominated == full:
                return size
    raise ValueError("total domination number is undefined for graphs with isolated vertices")


def matching_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)

    @cache
    def best(available: int) -> int:
        if available == 0:
            return 0
        bit = available & -available
        vertex = bit.bit_length() - 1
        answer = best(available ^ bit)
        candidates = adj[vertex] & (available ^ bit)
        while candidates:
            mate_bit = candidates & -candidates
            answer = max(answer, 1 + best(available ^ bit ^ mate_bit))
            candidates ^= mate_bit
        return answer

    return best(_full_mask(n))


def vertex_cover_number_from_adjacency(adj: Sequence[int]) -> int:
    return len(adj) - independence_number_from_adjacency(adj)


def edge_cover_number_from_adjacency(adj: Sequence[int]) -> int:
    if any(mask == 0 for mask in adj):
        raise ValueError("edge cover number is undefined for graphs with isolated vertices")
    return len(adj) - matching_number_from_adjacency(adj)


def bipartite_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n, -1, -1):
        for mask in _subsets_of_size(n, size):
            if _is_bipartite(adj, mask):
                return size
    return 0


def maximum_induced_forest_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n, -1, -1):
        for mask in _subsets_of_size(n, size):
            if _is_forest(adj, mask):
                return size
    return 0


def decycling_number_from_adjacency(adj: Sequence[int]) -> int:
    return len(adj) - maximum_induced_forest_number_from_adjacency(adj)


def path_cover_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    if n == 0:
        return 0
    full = _full_mask(n)
    path_endpoints = [0] * (1 << n)
    for vertex in range(n):
        path_endpoints[1 << vertex] = 1 << vertex
    for mask in range(1 << n):
        endpoints = path_endpoints[mask]
        for endpoint in _bits(endpoints):
            for neighbor in _bits(adj[endpoint] & ~mask):
                path_endpoints[mask | (1 << neighbor)] |= 1 << neighbor

    pathable = [endpoints != 0 for endpoints in path_endpoints]
    cover = [n + 1] * (1 << n)
    cover[0] = 0
    for mask in range(1, 1 << n):
        sub = mask
        while sub:
            if pathable[sub]:
                candidate = 1 + cover[mask ^ sub]
                if candidate < cover[mask]:
                    cover[mask] = candidate
            sub = (sub - 1) & mask
    return cover[full]


def burning_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    if n == 0:
        return 0
    if n == 1:
        return 1

    distances = [[n + 1] * n for _ in range(n)]
    for source in range(n):
        distances[source][source] = 0
        frontier = 1 << source
        seen = frontier
        distance = 0
        while frontier:
            distance += 1
            next_frontier = 0
            for vertex in _bits(frontier):
                next_frontier |= adj[vertex]
            next_frontier &= ~seen
            for vertex in _bits(next_frontier):
                distances[source][vertex] = distance
            seen |= next_frontier
            frontier = next_frontier

    for horizon in range(1, n + 1):
        coverage_by_round = []
        for round_index in range(horizon):
            radius = horizon - 1 - round_index
            round_coverage = []
            for source in range(n):
                covered = 0
                for target in range(n):
                    if distances[source][target] <= radius:
                        covered |= 1 << target
                round_coverage.append(covered)
            coverage_by_round.append(round_coverage)

        coverage_by_round_tuple = tuple(tuple(round_coverage) for round_coverage in coverage_by_round)

        @cache
        def can_cover(
            round_index: int,
            covered: int,
            horizon: int = horizon,
            coverage_by_round: tuple[tuple[int, ...], ...] = coverage_by_round_tuple,
        ) -> bool:
            if covered == _full_mask(n):
                return True
            if round_index == horizon:
                return False
            remaining_rounds = range(round_index, horizon)
            possible = covered
            for future_round in remaining_rounds:
                for source_coverage in coverage_by_round[future_round]:
                    possible |= source_coverage
            if possible != _full_mask(n):
                return False
            for source_coverage in sorted(
                coverage_by_round[round_index],
                key=lambda mask: (mask & ~covered).bit_count(),
                reverse=True,
            ):
                if can_cover(round_index + 1, covered | source_coverage):
                    return True
            return False

        if can_cover(0, 0):
            return horizon
    return n


def _is_dominating(adj: Sequence[int], mask: int) -> bool:
    full = _full_mask(len(adj))
    dominated = 0
    for i in _bits(mask):
        dominated |= adj[i] | (1 << i)
    return dominated == full


def connected_domination_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    if n == 0:
        return 0
    for size in range(1, n + 1):
        for mask in _subsets_of_size(n, size):
            if _is_dominating(adj, mask) and _is_connected_on_mask(adj, mask):
                return size
    return n


def independent_domination_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            if _is_dominating(adj, mask) and _is_independent(adj, mask):
                return size
    return n


def restrained_domination_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    full = _full_mask(n)
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            if not _is_dominating(adj, mask):
                continue
            outside = full ^ mask
            if all(adj[vertex] & outside for vertex in _bits(outside)):
                return size
    return n


def _has_hamiltonian_cycle_on_mask(adj: Sequence[int], mask: int) -> bool:
    if mask.bit_count() < 3:
        return False
    start_bit = mask & -mask
    start = start_bit.bit_length() - 1

    def search(vertex: int, remaining: int) -> bool:
        if remaining == 0:
            return bool(adj[vertex] & start_bit)
        candidates = adj[vertex] & remaining
        while candidates:
            bit = candidates & -candidates
            if search(bit.bit_length() - 1, remaining ^ bit):
                return True
            candidates ^= bit
        return False

    return search(start, mask ^ start_bit)


def maximum_number_of_vertex_disjoint_cycles_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    if _is_complete(adj):
        return n // 3
    cycle_masks = [
        mask for mask in range(1 << n) if mask.bit_count() >= 3 and _has_hamiltonian_cycle_on_mask(adj, mask)
    ]

    @cache
    def best(available: int) -> int:
        answer = 0
        for cycle_mask in cycle_masks:
            if cycle_mask & available == cycle_mask:
                answer = max(answer, 1 + best(available ^ cycle_mask))
        return answer

    return best(_full_mask(n))


def linear_arboricity_complete_graph_from_adjacency(adj: Sequence[int]) -> int | None:
    n = len(adj)
    if _edge_count(adj) == 0:
        return 0
    if _is_forest(adj, _full_mask(n)) and max((mask.bit_count() for mask in adj), default=0) <= 2:
        return 1
    if _is_complete(adj):
        return (n + 1) // 2
    return None


def zero_forcing_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            if _is_zero_forcing_set(adj, mask):
                return size
    return n


def skew_zero_forcing_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            if _is_skew_zero_forcing_set(adj, mask):
                return size
    return n


def psd_zero_forcing_number_from_adjacency(adj: Sequence[int]) -> int:
    n = len(adj)
    for size in range(n + 1):
        for mask in _subsets_of_size(n, size):
            if _is_psd_zero_forcing_set(adj, mask):
                return size
    return n


def _is_zero_forcing_set(adj: Sequence[int], black: int) -> bool:
    full = _full_mask(len(adj))
    while True:
        forces = 0
        white = full ^ black
        for vertex in _bits(black):
            white_neighbors = adj[vertex] & white
            if _single_bit(white_neighbors):
                forces |= white_neighbors
        forces &= ~black
        if forces == 0:
            return black == full
        black |= forces


def _is_skew_zero_forcing_set(adj: Sequence[int], black: int) -> bool:
    full = _full_mask(len(adj))
    while True:
        forces = 0
        white = full ^ black
        for vertex in range(len(adj)):
            white_neighbors = adj[vertex] & white
            if _single_bit(white_neighbors):
                forces |= white_neighbors
        forces &= ~black
        if forces == 0:
            return black == full
        black |= forces


def _components(adj: Sequence[int], mask: int) -> list[int]:
    components = []
    unseen = mask
    while unseen:
        start = unseen & -unseen
        component = 0
        frontier = start
        unseen ^= start
        while frontier:
            bit = frontier & -frontier
            vertex = bit.bit_length() - 1
            frontier ^= bit
            component |= bit
            new_vertices = adj[vertex] & unseen
            frontier |= new_vertices
            unseen &= ~new_vertices
        components.append(component)
    return components


def _is_psd_zero_forcing_set(adj: Sequence[int], black: int) -> bool:
    full = _full_mask(len(adj))
    while True:
        white = full ^ black
        if white == 0:
            return True
        components = _components(adj, white)
        forces = 0
        for vertex in _bits(black):
            for component in components:
                targets = adj[vertex] & component
                if _single_bit(targets):
                    forces |= targets
        forces &= ~black
        if forces == 0:
            return False
        black |= forces


def _core_number(adj: Sequence[int], predicate: Callable[[Sequence[int], int], bool], target_size: int) -> int:
    if not adj:
        return 0
    intersection = _full_mask(len(adj))
    found = False
    for mask in _subsets_of_size(len(adj), target_size):
        if predicate(adj, mask):
            intersection &= mask
            found = True
    return intersection.bit_count() if found else 0


def alpha_core_number_from_adjacency(adj: Sequence[int]) -> int:
    alpha = independence_number_from_adjacency(adj)
    return _core_number(adj, _is_independent, alpha)


def clique_core_number_from_adjacency(adj: Sequence[int]) -> int:
    omega = clique_number_from_adjacency(adj)
