def domination_core_number_from_adjacency(adj: Sequence[int]) -> int:
    gamma = domination_number_from_adjacency(adj)

    return _core_number(adj, _is_dominating, gamma)


def local_parameter_from_adjacency(
    adj: Sequence[int],
    invariant_from_adjacency: Callable[[Sequence[int]], int],
) -> int:
    if not adj:
        return 0
    best = 0
    for neighborhood in adj:
        value = invariant_from_adjacency(_induced_adjacency(adj, neighborhood))
        if value > best:
            best = value
    return best


def vertex_critical_count_from_adjacency(
    adj: Sequence[int],
    invariant_from_adjacency: Callable[[Sequence[int]], int],
    *,
    kind: str,
) -> int:
    base_value = invariant_from_adjacency(adj)
    count = 0
    for vertex in range(len(adj)):
        modified = invariant_from_adjacency(_without_vertex_adjacency(adj, vertex))
        if critical_count_matches(base_value, modified, kind=kind):
            count += 1
    return count


def edge_critical_count_from_adjacency(
    adj: Sequence[int],
    invariant_from_adjacency: Callable[[Sequence[int]], int],
    *,
    kind: str,
) -> int:
    base_value = invariant_from_adjacency(adj)
    count = 0
    for u in range(len(adj)):
        for v in range(u + 1, len(adj)):
            if not (adj[u] & (1 << v)):
                continue
            modified = invariant_from_adjacency(_without_edge_adjacency(adj, u, v))
            if critical_count_matches(base_value, modified, kind=kind):
                count += 1
    return count


def critical_count_matches(base_value: int, modified_value: int, *, kind: str) -> bool:
    if kind == "change":
        return modified_value != base_value
    if kind == "same":
        return modified_value == base_value
    if kind == "increase":
        return modified_value > base_value
    if kind == "decrease":
        return modified_value < base_value
    raise ValueError(f"unknown criticality kind: {kind}")


