    upper_external_redundance_number: int


def _star_leaf_count(graph: nx.Graph) -> int | None:
    order = graph.number_of_nodes()
    if order < 3 or graph.number_of_edges() != order - 1 or not nx.is_connected(graph):
        return None
    degrees = sorted(dict(graph.degree()).values())
    return order - 1 if degrees == [1] * (order - 1) + [order - 1] else None


def _ordinary_irredundant(graph: nx.Graph, selected: set) -> bool:
    return all(
        any(
            (set(graph[witness]) | {witness}) & selected == {vertex}
            for witness in set(graph[vertex]) | {vertex}
        )
        for vertex in selected
    )


def _open_irredundant(graph: nx.Graph, selected: set) -> bool:
    return all(
        any(
            witness not in selected
            and set(graph[witness]) & selected == {vertex}
            for witness in graph[vertex]
        )
        for vertex in selected
    )


def _open_open_irredundant(graph: nx.Graph, selected: set) -> bool:
    return all(
        any(
            set(graph[witness]) & selected == {vertex}
            for witness in graph[vertex]
        )
        for vertex in selected
    )


def _closed_open_irredundant(graph: nx.Graph, selected: set) -> bool:
    return all(
        (set(graph[vertex]) | {vertex}) & selected == {vertex}
        or any(
            set(graph[witness]) & selected == {vertex}
            for witness in graph[vertex]
        )
        for vertex in selected
    )


def _total_irredundant(graph: nx.Graph, selected: set) -> bool:
    for vertex in graph:
        reduced = selected - {vertex}
        dominated = set(reduced)
        for source in reduced:
            dominated.update(graph[source])
        if not ((set(graph[vertex]) | {vertex}) - dominated):
            return False
    return True


def _private_neighbor_count(graph: nx.Graph, selected: set) -> int:
    return sum(
        any(
            (set(graph[witness]) | {witness}) & selected == {vertex}
            for witness in set(graph[vertex]) | {vertex}
        )
        for vertex in selected
    )


def _external_redundant(graph: nx.Graph, selected: set) -> bool:
    count = _private_neighbor_count(graph, selected)
    return all(
        _private_neighbor_count(graph, selected | {vertex}) <= count
        for vertex in set(graph) - selected
    )


def _maximal(graph: nx.Graph, selected: set, property_fn) -> bool:
    return property_fn(graph, selected) and all(
        not property_fn(graph, selected | {vertex})
        for vertex in set(graph) - selected
    )


def _lower(graph: nx.Graph, property_fn) -> int:
    nodes = list(graph)
    for cardinality in range(1, len(nodes) + 1):
        for chosen in combinations(nodes, cardinality):
            if _maximal(graph, set(chosen), property_fn):
                return cardinality
    raise RuntimeError("No maximal irredundant set found")


def _upper_milp(graph: nx.Graph, *, open_variant: bool) -> int:
    nodes = list(graph)
    order = len(nodes)
    index = {node: i for i, node in enumerate(nodes)}
    neighborhoods = [{index[u] for u in graph[node]} for node in nodes]
    witnesses = []
    for vertex in range(order):
        candidates = neighborhoods[vertex] if open_variant else neighborhoods[vertex] | {vertex}
        witnesses.extend((vertex, witness) for witness in candidates)
    witness_index = {pair: order + i for i, pair in enumerate(witnesses)}
    variable_count = order + len(witnesses)
    rows, lower, upper = [], [], []

    def append(row, low, high) -> None:
        rows.append(row)
        lower.append(low)
        upper.append(high)

    for vertex, witness in witnesses:
        y = witness_index[vertex, witness]
        row = [0] * variable_count
        row[y] = 1
        row[vertex] = -1
        append(row, -np.inf, 0)
        if open_variant:
            row = [0] * variable_count
            row[y] = row[witness] = 1
            append(row, -np.inf, 1)
            forbidden = neighborhoods[witness] - {vertex}
        else:
            forbidden = (neighborhoods[witness] | {witness}) - {vertex}
        for other in forbidden:
            row = [0] * variable_count
            row[y] = row[other] = 1
            append(row, -np.inf, 1)

    for vertex in range(order):
        row = [0] * variable_count
        row[vertex] = -1
        for pair in witnesses:
            if pair[0] == vertex:
                row[witness_index[pair]] += 1
        append(row, 0, np.inf)

    result = milp(
        np.asarray([-1] * order + [0] * len(witnesses), dtype=float),
        integrality=np.ones(variable_count),
        bounds=Bounds(np.zeros(variable_count), np.ones(variable_count)),
        constraints=LinearConstraint(
            np.asarray(rows, dtype=float),
            np.asarray(lower, dtype=float),
            np.asarray(upper, dtype=float),
        ),
        options={"presolve": True},
    )
    if not result.success:
        raise RuntimeError("Irredundance MILP did not solve")
    return -round(float(result.fun))


def _upper_extended_milp(graph: nx.Graph, *, closed_open: bool) -> int:
    nodes = list(graph)
    order = len(nodes)
    index = {node: i for i, node in enumerate(nodes)}
    neighborhoods = [{index[u] for u in graph[node]} for node in nodes]
    witnesses: list[tuple[int, tuple[int, ...]]] = []
    for vertex in range(order):
        if closed_open:
            witnesses.append((vertex, tuple(neighborhoods[vertex])))
        for witness in neighborhoods[vertex]:
            witnesses.append((vertex, tuple(neighborhoods[witness] - {vertex})))
    variable_count = order + len(witnesses)
    rows, lower, upper = [], [], []

    for witness_index, (vertex, forbidden) in enumerate(witnesses, start=order):
        row = [0] * variable_count
        row[witness_index] = 1
        row[vertex] = -1
        rows.append(row)
        lower.append(-np.inf)
        upper.append(0)
        for other in forbidden:
            row = [0] * variable_count
            row[witness_index] = row[other] = 1
            rows.append(row)
            lower.append(-np.inf)
            upper.append(1)

    for vertex in range(order):
        row = [0] * variable_count
        row[vertex] = -1
        for witness_index, (owner, _) in enumerate(witnesses, start=order):
            if owner == vertex:
                row[witness_index] += 1
        rows.append(row)
        lower.append(0)
        upper.append(np.inf)

    result = milp(
        np.asarray([-1] * order + [0] * len(witnesses), dtype=float),
        integrality=np.ones(variable_count),
        bounds=Bounds(np.zeros(variable_count), np.ones(variable_count)),
        constraints=LinearConstraint(
            np.asarray(rows, dtype=float),
            np.asarray(lower, dtype=float),
            np.asarray(upper, dtype=float),
        ),
        options={"presolve": True},
    )
    if not result.success:
        raise RuntimeError("Extended irredundance MILP did not solve")
    return -round(float(result.fun))


def lower_irredundance_number(graph: nx.Graph) -> int:
    return _lower(graph, _ordinary_irredundant)


def upper_irredundance_number(graph: nx.Graph) -> int:
    return _upper_milp(graph, open_variant=False)


def lower_open_irredundance_number(graph: nx.Graph) -> int:
    return _lower(graph, _open_irredundant)


def upper_open_irredundance_number(graph: nx.Graph) -> int:
    return _upper_milp(graph, open_variant=True)


def lower_open_open_irredundance_number(graph: nx.Graph) -> int:
    return _lower(graph, _open_open_irredundant)


def upper_open_open_irredundance_number(graph: nx.Graph) -> int:
    return _upper_extended_milp(graph, closed_open=False)


def lower_closed_open_irredundance_number(graph: nx.Graph) -> int:
    return _lower(graph, _closed_open_irredundant)


def upper_closed_open_irredundance_number(graph: nx.Graph) -> int:
    return _upper_extended_milp(graph, closed_open=True)


def lower_co_irredundance_number(
    graph: nx.Graph,
    upper_irredundance: int | None = None,
) -> int:
    upper_value = upper_irredundance or upper_irredundance_number(graph)
    return len(graph) - upper_value


def upper_co_irredundance_number(
    graph: nx.Graph,
    lower_irredundance: int | None = None,
) -> int:
    lower_value = lower_irredundance or lower_irredundance_number(graph)
    return len(graph) - lower_value


def extended_irredundance_bundle(
    graph: nx.Graph,
    *,
    lower_irredundance: int | None = None,
    upper_irredundance: int | None = None,
) -> ExtendedIrredundanceBundle:
    return ExtendedIrredundanceBundle(
        lower_open_open_irredundance_number(graph),
        upper_open_open_irredundance_number(graph),
        lower_closed_open_irredundance_number(graph),
        upper_closed_open_irredundance_number(graph),
        lower_co_irredundance_number(graph, upper_irredundance),
        upper_co_irredundance_number(graph, lower_irredundance),
    )


def _extrema_by_subsets(
    graph: nx.Graph,
    property_fn,
    *,
    require_maximal: bool,
) -> tuple[int, int]:
    nodes = list(graph)
    values = []
    for cardinality in range(len(nodes) + 1):
        for chosen in combinations(nodes, cardinality):
            selected = set(chosen)
            qualifies = property_fn(graph, selected)
            if require_maximal:
                qualifies = _maximal(graph, selected, property_fn)
            if qualifies:
                values.append(cardinality)
    if not values:
        raise RuntimeError("No extremal irredundance set found")
    return min(values), max(values)


def total_external_irredundance_bundle(graph: nx.Graph) -> TotalExternalIrredundanceBundle:
    leaf_count = _star_leaf_count(graph)
    if leaf_count is not None:
        return TotalExternalIrredundanceBundle(
            lower_total_irredundance_number=leaf_count - 1,
            upper_total_irredundance_number=leaf_count - 1,
            lower_external_redundance_number=1,
            upper_external_redundance_number=leaf_count + 1,
        )
    total_lower, total_upper = _extrema_by_subsets(graph, _total_irredundant, require_maximal=True)
    external_lower, external_upper = _extrema_by_subsets(graph, _external_redundant, require_maximal=False)
    return TotalExternalIrredundanceBundle(
        total_lower,
        total_upper,
        external_lower,
        external_upper,
    )


def lower_total_irredundance_number(graph: nx.Graph) -> int:
    return total_external_irredundance_bundle(graph).lower_total_irredundance_number


def upper_total_irredundance_number(graph: nx.Graph) -> int:
    return total_external_irredundance_bundle(graph).upper_total_irredundance_number


def lower_external_redundance_number(graph: nx.Graph) -> int:
    return total_external_irredundance_bundle(graph).lower_external_redundance_number


def upper_external_redundance_number(graph: nx.Graph) -> int:
    return total_external_irredundance_bundle(graph).upper_external_redundance_number


def irredundance_bundle(graph: nx.Graph) -> IrredundanceBundle:
    return IrredundanceBundle(
        lower_irredundance_number(graph),
        upper_irredundance_number(graph),
        lower_open_irredundance_number(graph),
        upper_open_irredundance_number(graph),
    )


def irredundance_bundle_bruteforce(graph: nx.Graph) -> IrredundanceBundle:
    nodes = list(graph)
    ordinary = []
    open_sets = []
    for cardinality in range(1, len(nodes) + 1):
        for chosen in combinations(nodes, cardinality):
            selected = set(chosen)
            if _maximal(graph, selected, _ordinary_irredundant):
                ordinary.append(cardinality)
            if _maximal(graph, selected, _open_irredundant):
                open_sets.append(cardinality)
    return IrredundanceBundle(
        min(ordinary),
        max(ordinary),
        min(open_sets),
        max(open_sets),
    )


def extended_irredundance_bundle_bruteforce(graph: nx.Graph) -> ExtendedIrredundanceBundle:
    nodes = list(graph)
    open_open = []
    closed_open = []
    for cardinality in range(1, len(nodes) + 1):
        for chosen in combinations(nodes, cardinality):
            selected = set(chosen)
            if _maximal(graph, selected, _open_open_irredundant):
                open_open.append(cardinality)
            if _maximal(graph, selected, _closed_open_irredundant):
                closed_open.append(cardinality)
    core = irredundance_bundle_bruteforce(graph)
    return ExtendedIrredundanceBundle(
        min(open_open),
        max(open_open),
        min(closed_open),
        max(closed_open),
        len(graph) - core.upper_irredundance_number,
        len(graph) - core.lower_irredundance_number,
    )

