from __future__ import annotations

import networkx as nx


def component_count(graph: nx.Graph) -> int:
    """Return the number of connected components of an undirected graph."""
    return nx.number_connected_components(graph)


def block_count(graph: nx.Graph) -> int:
    """Return the number of blocks, including isolated-vertex blocks.

    NetworkX's biconnected-component iterator includes each bridge as a
    two-vertex block but omits isolated vertices. The glossary definition uses
    maximal nonseparable subgraphs, under which every isolated vertex is a
    one-vertex block, so those vertices are added explicitly.
    """
    nontrivial_blocks = sum(1 for _ in nx.biconnected_components(graph))
    return nontrivial_blocks + nx.number_of_isolates(graph)


def bridge_count(graph: nx.Graph) -> int:
    """Return the number of bridges."""
    return sum(1 for _ in nx.bridges(graph))


def cutvertex_count(graph: nx.Graph) -> int:
    """Return the number of cutvertices."""
    return sum(1 for _ in nx.articulation_points(graph))


def isolated_vertex_count(graph: nx.Graph) -> int:
    """Return the number of vertices of degree zero."""
    return nx.number_of_isolates(graph)


def periphery_size(graph: nx.Graph) -> int:
    """Return the number of vertices whose eccentricity equals the diameter."""
    if graph.number_of_nodes() == 0 or not nx.is_connected(graph):
        raise ValueError("periphery size is undefined for an empty or disconnected graph")
    return len(nx.periphery(graph))


def vertex_connectivity(graph: nx.Graph) -> int:
    """Return vertex connectivity with value zero for trivial/disconnected graphs."""
    if graph.number_of_nodes() <= 1 or not nx.is_connected(graph):
        return 0
    return int(nx.node_connectivity(graph))


def edge_connectivity(graph: nx.Graph) -> int:
    """Return edge connectivity, with the glossary convention lambda(K1)=0."""
    if graph.number_of_nodes() <= 1 or not nx.is_connected(graph):
        return 0
    return int(nx.edge_connectivity(graph))


def wiener_index(graph: nx.Graph) -> int:
    """Return the sum of distances over unordered vertex pairs.

    The value is computed with unweighted breadth-first searches and integer
    accumulation. It is undefined for an empty or disconnected graph under the
    connected-graph distance convention used by the glossary.
    """
    if graph.number_of_nodes() == 0 or not nx.is_connected(graph):
        raise ValueError("Wiener index is undefined for an empty or disconnected graph")

    nodes = list(graph)
    index = {node: position for position, node in enumerate(nodes)}
    total = 0
    for source in nodes:
        source_index = index[source]
        distances = nx.single_source_shortest_path_length(graph, source)
        total += sum(distance for target, distance in distances.items() if index[target] > source_index)
    return total


def first_zagreb_index(graph: nx.Graph) -> int:
    """Return the sum of squared vertex degrees."""
    return sum(degree * degree for _, degree in graph.degree())


def second_zagreb_index(graph: nx.Graph) -> int:
    """Return the sum of endpoint-degree products over all edges."""
    degree = dict(graph.degree())
    return sum(degree[u] * degree[v] for u, v in graph.edges())

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from itertools import product
from math import ceil, isclose
from typing import Any

import networkx as nx
import numpy as np
from scipy.optimize import Bounds, LinearConstraint, linprog, milp


@dataclass(frozen=True)
class FractionalDominationCertificate:
    value: Fraction
    primal_weights: tuple[tuple[Any, Fraction], ...]
    dual_weights: tuple[tuple[Any, Fraction], ...]


@dataclass(frozen=True)
class WeightedDominationBundle:
    fractional_domination_number: Fraction
    majority_domination_number: int
    minus_domination_number: int
    signed_domination_number: int
    differential_number: int


def _closed_incidence(graph: nx.Graph) -> tuple[list[Any], np.ndarray]:
    nodes = list(graph)
    matrix = np.asarray(
        [
            [int(source == target or graph.has_edge(source, target)) for source in nodes]
            for target in nodes
        ],
        dtype=float,
    )
    return nodes, matrix


def _fraction(value: float) -> Fraction:
    if isclose(value, 0.0, abs_tol=1e-9):
        return Fraction(0)
    return Fraction(float(value)).limit_denominator(10**9)


def verify_fractional_domination_certificate(
    graph: nx.Graph,
    certificate: FractionalDominationCertificate,
) -> bool:
    primal = dict(certificate.primal_weights)
    dual = dict(certificate.dual_weights)
    if set(primal) != set(graph) or set(dual) != set(graph):
        return False
    if any(not 0 <= weight <= 1 for weight in primal.values()):
        return False
    if any(weight < 0 for weight in dual.values()):
        return False
    if any(
        sum(primal[source] for source in set(graph[target]) | {target}) < 1
        for target in graph
    ):
        return False
    if any(
        sum(dual[target] for target in set(graph[source]) | {source}) > 1
        for source in graph
    ):
        return False
    return (
        sum(primal.values(), Fraction(0))
        == sum(dual.values(), Fraction(0))
        == certificate.value
    )


def fractional_domination_with_certificate(
    graph: nx.Graph,
) -> FractionalDominationCertificate:
    nodes, incidence = _closed_incidence(graph)
    if not nodes:
        return FractionalDominationCertificate(Fraction(0), (), ())
    primal_result = linprog(
        np.ones(len(nodes)),
        A_ub=-incidence,
        b_ub=-np.ones(len(nodes)),
        bounds=(0, 1),
        method="highs",
    )
    dual_result = linprog(
        -np.ones(len(nodes)),
        A_ub=incidence.T,
        b_ub=np.ones(len(nodes)),
        bounds=(0, None),
        method="highs",
    )
    if not primal_result.success or not dual_result.success:
        raise RuntimeError("Fractional-domination LP did not solve")
    primal = tuple(_fraction(value) for value in primal_result.x)
    dual = tuple(_fraction(value) for value in dual_result.x)
    certificate = FractionalDominationCertificate(
        sum(primal, Fraction(0)),
        tuple(zip(nodes, primal, strict=True)),
        tuple(zip(nodes, dual, strict=True)),
    )
    if not verify_fractional_domination_certificate(graph, certificate):
        raise RuntimeError("LP basis did not yield an exact rational certificate")
    return certificate


def _integer_function_minimum(graph: nx.Graph, mode: str) -> int:
    nodes, incidence = _closed_incidence(graph)
    order = len(nodes)
    if mode == "signed":
        lower = np.ceil((incidence.sum(axis=1) + 1) / 2)
        result = milp(
            np.ones(order),
            integrality=np.ones(order),
            bounds=Bounds(np.zeros(order), np.ones(order)),
            constraints=LinearConstraint(incidence, lower, np.inf),
            options={"presolve": True},
        )
        if not result.success:
            raise RuntimeError("Signed-domination MILP did not solve")
        selected = np.rint(result.x).astype(int)
        return int(2 * selected.sum() - order)
    if mode == "minus":
        result = milp(
            np.ones(order),
            integrality=np.ones(order),
            bounds=Bounds(-np.ones(order), np.ones(order)),
            constraints=LinearConstraint(incidence, np.ones(order), np.inf),
            options={"presolve": True},
        )
        if not result.success:
            raise RuntimeError("Minus-domination MILP did not solve")
        labels = np.rint(result.x).astype(int)
        return int(labels.sum())
    if mode != "majority":
        raise ValueError(mode)
    objective = np.concatenate([np.ones(order), np.zeros(order)])
    integrality = np.ones(2 * order)
    lower_bounds = np.concatenate([-np.ones(order), np.zeros(order)])
    upper_bounds = np.ones(2 * order)
    big_m = incidence.sum(axis=1) + 1
    local = np.hstack([incidence, -np.diag(big_m)])
    majority = np.concatenate([np.zeros(order), np.ones(order)])[None, :]
    constraints = [
        LinearConstraint(local, 1 - big_m, np.inf),
        LinearConstraint(majority, ceil(order / 2), np.inf),
    ]
    result = milp(
        objective,
        integrality=integrality,
        bounds=Bounds(lower_bounds, upper_bounds),
        constraints=constraints,
        options={"presolve": True},
    )
    if not result.success:
        raise RuntimeError("Majority-domination MILP did not solve")
    labels = np.rint(result.x[:order]).astype(int)
    return int(labels.sum())


def differential_number(graph: nx.Graph) -> int:
    nodes = list(graph)
    order = len(nodes)
    objective = np.concatenate([np.ones(order), -np.ones(order)])
    rows = []
    upper = []
    for vertex, node in enumerate(nodes):
        row = np.zeros(2 * order)
        row[order + vertex] = 1
        row[vertex] = 1
        rows.append(row)
        upper.append(1)
        row = np.zeros(2 * order)
        row[order + vertex] = 1
        for neighbor in graph[node]:
            row[nodes.index(neighbor)] -= 1
        rows.append(row)
        upper.append(0)
    result = milp(
        objective,
        integrality=np.ones(2 * order),
        bounds=Bounds(np.zeros(2 * order), np.ones(2 * order)),
        constraints=LinearConstraint(np.asarray(rows), -np.inf, np.asarray(upper)),
        options={"presolve": True},
    )
    if not result.success:
        raise RuntimeError("Differential MILP did not solve")
    selected = np.rint(result.x[:order]).astype(int)
    boundary = np.rint(result.x[order:]).astype(int)
    return int(boundary.sum() - selected.sum())


def weighted_domination_bundle(graph: nx.Graph) -> WeightedDominationBundle:
    return WeightedDominationBundle(
        fractional_domination_with_certificate(graph).value,
        _integer_function_minimum(graph, "majority"),
        _integer_function_minimum(graph, "minus"),
        _integer_function_minimum(graph, "signed"),
        differential_number(graph),
    )


def weighted_domination_bundle_bruteforce(graph: nx.Graph) -> WeightedDominationBundle:
    nodes = list(graph)
    closed = [set(graph[node]) | {node} for node in nodes]
    majority = len(nodes) + 1
    minus = len(nodes) + 1
    signed = len(nodes) + 1
    differential = 0
    for labels in product((-1, 0, 1), repeat=len(nodes)):
        sums = [sum(labels[nodes.index(source)] for source in neighborhood) for neighborhood in closed]
        weight = sum(labels)
        if sum(value >= 1 for value in sums) >= ceil(len(nodes) / 2):
            majority = min(majority, weight)
        if all(value >= 1 for value in sums):
            minus = min(minus, weight)
        if 0 not in labels and all(value >= 1 for value in sums):
            signed = min(signed, weight)
    for bits in product((0, 1), repeat=len(nodes)):
        selected = {nodes[index] for index, bit in enumerate(bits) if bit}
        boundary = set().union(*(set(graph[node]) for node in selected)) - selected if selected else set()
        differential = max(differential, len(boundary) - len(selected))
    return WeightedDominationBundle(
        fractional_domination_with_certificate(graph).value,
        majority,
        minus,
        signed,
        differential,
    )


def fractional_domination_number(graph: nx.Graph) -> float:
    return float(fractional_domination_with_certificate(graph).value)


def fractional_domination_numerator(graph: nx.Graph) -> int:
    return fractional_domination_with_certificate(graph).value.numerator


def fractional_domination_denominator(graph: nx.Graph) -> int:
    return fractional_domination_with_certificate(graph).value.denominator


def majority_domination_number(graph: nx.Graph) -> int:
    return _integer_function_minimum(graph, "majority")


def minus_domination_number(graph: nx.Graph) -> int:
    return _integer_function_minimum(graph, "minus")


def signed_domination_number(graph: nx.Graph) -> int:
    return _integer_function_minimum(graph, "signed")

