@lru_cache(maxsize=1)
def _catalogs():
    from .full.features import GRAPH_DERIVED_FEATURE_SPECS, GRAPH_FEATURE_SPECS

    return GRAPH_FEATURE_SPECS, GRAPH_DERIVED_FEATURE_SPECS


def available_descriptor_keys() -> tuple[str, ...]:
    base, derived = _catalogs()
    return tuple(sorted({*base, *derived}))


def _method_name(function: Any) -> str:
    module = getattr(function, "__module__", "unknown")
    name = getattr(function, "__qualname__", getattr(function, "__name__", "callable"))
    return f"extracted_legacy.{module}.{name}"


def _normalize_value(value: Any) -> Any:
    if hasattr(value, "item"):
        return value.item()
    return value


def _compute_value(
    descriptor_key: str,
    graph: nx.Graph,
    cache: dict[str, Any],
) -> tuple[Any, str, float | None, str | None]:
    from .full.features import timed_feature_call

    base, derived = _catalogs()
    if descriptor_key in cache:
        return cache[descriptor_key], "dependency_cache", None, None
    if descriptor_key in base:
        spec = base[descriptor_key]
        value, is_defined, status, elapsed, error = timed_feature_call(spec.compute, graph)
        normalized = _normalize_value(value)
        if is_defined:
            cache[descriptor_key] = normalized
        return normalized, _method_name(spec.compute), elapsed, error or (None if status == "ok" else status)
    try:
        spec = derived[descriptor_key]
    except KeyError as exc:
        raise KeyError(f"Unknown graph descriptor {descriptor_key!r}") from exc
    for dependency in spec.dependencies:
        if dependency not in cache:
            value, _, _, _ = _compute_value(dependency, graph, cache)
            cache[dependency] = value
    value, is_defined, status, elapsed, error = timed_feature_call(spec.compute, cache)
    normalized = _normalize_value(value)
    if is_defined:
        cache[descriptor_key] = normalized
    return normalized, _method_name(spec.compute), elapsed, error or (None if status == "ok" else status)


def evaluate_extracted(descriptor_key: str, graph: nx.Graph) -> EvaluationReceipt:
    value, method, elapsed, error = _compute_value(descriptor_key, graph, {})
    if error is not None:
        return EvaluationReceipt(
            descriptor_key=descriptor_key,
            value=None,
            status="undefined" if value is None else "failed",
            exactness="exact",
            method=method,
            solver={"elapsed_seconds": elapsed},
            message=error,
        )
    return EvaluationReceipt(
        descriptor_key=descriptor_key,
        value=value,
        status="computed_unverified",
        exactness="approximate" if isinstance(value, float) else "exact",
        method=method,
        solver={"elapsed_seconds": elapsed},
        message="Evaluator migrated from the legacy registry; descriptor-specific verification is pending.",
    )

from __future__ import annotations

from typing import Any

import networkx as nx


def graph_from_representation(representation: dict[str, Any]) -> nx.Graph:
    """Reconstruct and validate an owned `edge_list_v1` graph representation."""

    if representation.get("format") != "edge_list_v1":
        raise ValueError("Expected an edge_list_v1 graph representation")
    nodes = representation.get("nodes")
    edges = representation.get("edges")
    if not isinstance(nodes, list) or not isinstance(edges, list):
        raise ValueError("Graph representation must contain list-valued nodes and edges")
    if len(nodes) != len(set(nodes)):
        raise ValueError("Graph representation contains duplicate node identifiers")
    graph = nx.Graph()
    graph.add_nodes_from(nodes)
    for edge in edges:
        if not isinstance(edge, list | tuple) or len(edge) != 2:
            raise ValueError(f"Invalid edge record: {edge!r}")
        u, v = edge
        if u == v:
            raise ValueError("Simple graph representations may not contain loops")
        if u not in graph or v not in graph:
            raise ValueError("Every edge endpoint must occur in the node list")
        graph.add_edge(u, v)
    if graph.number_of_edges() != len(edges):
        raise ValueError("Simple graph representations may not contain duplicate edges")
    return graph


def representation_from_graph(graph: nx.Graph) -> dict[str, Any]:
    if graph.is_directed() or graph.is_multigraph() or nx.number_of_selfloops(graph):
        raise ValueError("Only finite simple undirected graphs are supported")
    return {
        "format": "edge_list_v1",
        "nodes": list(graph.nodes()),
        "edges": [list(edge) for edge in graph.edges()],
    }

from __future__ import annotations

from collections.abc import Callable
from itertools import combinations

import networkx as nx


def _minimum_subset(graph: nx.Graph, accepts: Callable[[set[object]], bool]) -> tuple[int, list[object]]:
    nodes = list(graph.nodes())
    if len(nodes) > 12:
        raise ValueError("Enumeration oracle is restricted to graphs of order at most 12")
    for size in range(len(nodes) + 1):
        for choice in combinations(nodes, size):
            selected = set(choice)
            if accepts(selected):
                return size, list(choice)
    raise AssertionError("No feasible subset found")


def domination_number(graph: nx.Graph) -> tuple[int, list[object]]:
    return _minimum_subset(
        graph,
        lambda selected: all(
            vertex in selected or any(neighbor in selected for neighbor in graph[vertex]) for vertex in graph
        ),
    )


def vertex_cover_number(graph: nx.Graph) -> tuple[int, list[object]]:
    return _minimum_subset(graph, lambda selected: all(u in selected or v in selected for u, v in graph.edges()))


def independence_number(graph: nx.Graph) -> tuple[int, list[object]]:
    size, complement = vertex_cover_number(graph)
    selected = [node for node in graph if node not in set(complement)]
    return graph.number_of_nodes() - size, selected

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pyarrow.parquet as pq

from .model import graph_from_representation


def load_object(study_root: Path, object_key: str) -> tuple[dict[str, Any], Any]:
    for line in (study_root / "objects/objects.jsonl").read_text(encoding="utf-8").splitlines():
        record = json.loads(line)
        if record["object_key"] == object_key:
            return record, graph_from_representation(record["representation"])
    raise KeyError(f"Unknown graph object: {object_key}")


def load_table_row(study_root: Path, row_index: int) -> dict[str, Any]:
    table = pq.read_table(study_root / "tables/registry.parquet")
    if row_index < 0 or row_index >= table.num_rows:
        raise IndexError(row_index)
    return table.slice(row_index, 1).to_pylist()[0]

