          "parameters": []
        },
        "role": "function"
      },
      {
        "body_sort": null,
        "bound_sorts": [],
        "definition": "A set \\(S\\subseteq V(G)\\) is well-splitting if every connected component of \\(G-S\\) has order at most \\(\\lceil(|V(G)|-|S|)/2\\rceil\\). The well-splitting number \\(S_w(G)\\) is the minimum cardinality of a well-splitting set.",
        "input_sorts": [
