          "parameters": []
        },
        "role": "function"
      },
      {
        "body_sort": null,
        "bound_sorts": [],
        "definition": "For connected \\(G\\), the Wiener index is \\(W(G)=\\sum_{\\{u,v\\}\\subseteq V(G)}d_G(u,v)\\), where each unordered pair of distinct vertices occurs once.",
        "input_sorts": [
          {
            "key": "graph_theory.finite_connected_simple_graph_value",
