        },
        "role": "function"
      },
      {
        "body_sort": null,
        "bound_sorts": [],
        "definition": "Let \\(A(G)\\) be the adjacency matrix of \\(G\\). The zero adjacency eigenvalues count is the number of adjacency eigenvalues equal to 0, counted with algebraic multiplicity. This is the same quantity as adjacency nullity.",
        "input_sorts": [
          {
            "key": "graph_theory.finite_connected_simple_graph_value",
