      },
      {
        "body_sort": null,
        "bound_sorts": [],
        "definition": "Starting from a set S of initially colored vertices, repeatedly apply the zero forcing rule that a colored vertex with exactly one uncolored neighbor forces that neighbor to become colored. A zero forcing set of a graph G is an initial colored set S that eventually colors every vertex of G. The zero forcing number Z(G) of G is the minimum cardinality of a zero forcing set of G.",
        "input_sorts": [
          {
            "key": "graph_theory.finite_connected_simple_graph_value",
