import GraphTheoryFoundation.Basic

namespace GraphTheoryFoundation

/-- The degree of a vertex. -/
def degree (G : FiniteSimpleGraph) (v : Fin G.order) : Nat :=
  ((vertices G).filter fun w => G.Adj v w).card

/-- The number of ordered adjacent pairs. It is twice the ordinary edge count. -/
def orderedEdgeCount (G : FiniteSimpleGraph) : Nat :=
  ((vertices G).product (vertices G) |>.filter fun edge => G.Adj edge.1 edge.2).card

/-- A graph is complete when every two distinct vertices are adjacent. -/
def IsComplete (G : FiniteSimpleGraph) : Prop :=
  ∀ u v, u ≠ v → G.Adj u v

/-- A graph is regular when all vertices have the same degree. -/
def IsRegular (G : FiniteSimpleGraph) : Prop :=
  ∃ k, ∀ v, degree G v = k

/-- A vertex is isolated when its degree is zero. -/
def IsIsolated (G : FiniteSimpleGraph) (v : Fin G.order) : Prop :=
  degree G v = 0

/-- A graph has an isolated vertex. -/
def HasIsolatedVertex (G : FiniteSimpleGraph) : Prop :=
  ∃ v, IsIsolated G v

/-- A set of vertices is independent when it contains no adjacent pair. -/
def IsIndependent (G : FiniteSimpleGraph) (S : Finset (Fin G.order)) : Prop :=
  ∀ u ∈ S, ∀ v ∈ S, u ≠ v → ¬G.Adj u v

/-- A set of vertices is dominating when every outside vertex has a neighbor in it. -/
def IsDominating (G : FiniteSimpleGraph) (S : Finset (Fin G.order)) : Prop :=
  ∀ v, v ∈ S ∨ ∃ u ∈ S, G.Adj u v

/-- A set of vertices covers every edge. -/
def IsVertexCover (G : FiniteSimpleGraph) (S : Finset (Fin G.order)) : Prop :=
  ∀ u v, G.Adj u v → u ∈ S ∨ v ∈ S

end GraphTheoryFoundation

